export const OVERLAYS = {"avian-medicine--avian-ib":{"avian-medicine--avian-ib--ภาพรวมของโรค-overview":{"claims":[{"id":"avian-medicine--avian-ib--ภาพรวมของโรค-overview--v1","statement":"IB เป็นโรคเฉียบพลันที่ติดต่อได้ง่าย มีอาการหลักที่ระบบหายใจในไก่รุ่น ส่วนในแม่ไก่ไข่จะพบไข่ลดและคุณภาพไข่แย่ลง และบาง strain เป็น nephropathogenic ทำให้เกิด interstitial nephritis และการตายได้ ตรงกับที่สไลด์ระบุว่าโรคนี้กระทบทั้ง respiratory, reproductive และ nephritis","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2018","locator":"Chapter 3.3.2, Summary, p. 1","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"IB is an acute, contagious disease characterised primarily by respiratory signs in growing chickens. In hens, decreased egg production and quality are often observed. Several strains of the virus are nephropathogenic and may produce interst"}},{"id":"avian-medicine--avian-ib--ภาพรวมของโรค-overview--v2","statement":"ความเสียหายทางเศรษฐกิจของ IB มาจาก production loss คือ ไก่เนื้อโตช้า (growth retardation) และไก่ไข่ให้ไข่ลดลงทั้งปริมาณและคุณภาพ ซึ่งบางฝูงอาจไม่กลับมาเป็นปกติอีกเลย สนับสนุนประเด็นในสไลด์ที่ว่าโรคไม่ได้ฆ่าไก่โดยตรงแต่สร้างความเสียหายทางเศรษฐกิจมาก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17296157","locator":"Section 7 Epidemiology and clinical signs, p. 289","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Infection of meat-type birds results in growth retardation. In layers, there is a drop in egg production, which might never return to normal, and in quality of eggs."}}]},"avian-medicine--avian-ib--ประวัติช่วงแรกของโรค-1930-1941":{"claims":[{"id":"avian-medicine--avian-ib--ประวัติช่วงแรกของโรค-1930-1941--v1","statement":"IB ถูกสังเกตและรายงานครั้งแรกโดย Schalk and Hawn ที่รัฐ North Dakota สหรัฐอเมริกา ในลูกไก่อายุ 2-3 สัปดาห์ ตรงกับที่สไลด์ระบุ (สไลด์ใช้ปี 1930 ซึ่งเป็นปีที่พบโรค ส่วนรายงานตีพิมพ์ในปี 1931)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"doi-10-1016-b978-0-12-814966-9-00003-2","locator":"pp. 31-44, Introduction","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Infectious bronchitis (IB) was first observed by Schalk and Hawn (1931) in North Dakota in the United States in 2- to 3-week-old chickens."}},{"id":"avian-medicine--avian-ib--ประวัติช่วงแรกของโรค-1930-1941--v2","statement":"ห้าปีหลังรายงานแรก Beach and Schalm (1936) เป็นผู้แสดงว่าสาเหตุของโรคนี้คือไวรัส ซึ่งต่อมาเรียกว่า IBV สอดคล้องกับสไลด์ที่ระบุปี 1936 และชื่อผู้วิจัย แต่แหล่งอ้างอิงอธิบายว่าเป็นการพิสูจน์ว่าเชื้อสาเหตุเป็นไวรัส ไม่ได้ระบุรายละเอียดเรื่องการแยกจาก ILT ด้วย neutralization","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"doi-10-1016-b978-0-12-814966-9-00003-2","locator":"pp. 31-44, Introduction","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Five years later, it was demonstrated that the causative agent of this disease is a virus, which was named IBV (Beach and Schalm, 1936)."}}]},"avian-medicine--avian-ib--ประวัติ-วัคซีนตัวแรกและการค้นพบว่ามีหลาย-serotype":{"claims":[{"id":"avian-medicine--avian-ib--ประวัติ-วัคซีนตัวแรกและการค้นพบว่ามีหลาย-serotype--v1","statement":"Jungherr และคณะ (1956) แสดงว่าเชื้อ Connecticut (Conn) ที่แยกได้ปี 1951 ไม่ cross-neutralize และไม่ cross-protect กับเชื้อ Massachusetts (Mass) ดั้งเดิม จึงเป็นจุดเริ่มต้นของแนวคิดว่า IBV มีหลาย serotype ที่ไม่คุ้มกันข้ามกัน ตรงกับสไลด์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-21711181","locator":"History section","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Jungherr et al. (1956) in the USA showed that the Connecticut (Conn) isolate of 1951 neither cross-neutralized nor cross-protected with the original Massachusetts (Mass) isolate from the early 1940s."}},{"id":"avian-medicine--avian-ib--ประวัติ-วัคซีนตัวแรกและการค้นพบว่ามีหลาย-serotype--v2","statement":"ผลจากการมีหลาย serotype คือวัคซีนที่ทำจาก serotype หนึ่งอาจป้องกันไวรัสที่อยู่คนละ antigenic group ได้น้อยมากหรือไม่ได้เลย ยืนยันหลัก no cross protection ที่สไลด์กล่าวถึง","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2018","locator":"Section B.1.4 Serotype identification, p. 4","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"vaccines based on one particular serotype may show little or no protection against viruses of a different antigenic group"}}]},"avian-medicine--avian-ib--เชื้อสาเหตุและการจัดจำแนก-etiology":{"claims":[{"id":"avian-medicine--avian-ib--เชื้อสาเหตุและการจัดจำแนก-etiology--v1","statement":"IBV จัดอยู่ใน genus Gammacoronavirus, subfamily Coronavirinae, family Coronaviridae, order Nidovirales ตรงกับ taxonomy ที่สไลด์ระบุทุกระดับ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2018","locator":"Section A Introduction, p. 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The virus is a member of the genus Gammacoronavirus, subfamily Coronavirinae, family Coronaviridae, in the order Nidovirales."}},{"id":"avian-medicine--avian-ib--เชื้อสาเหตุและการจัดจำแนก-etiology--v2","statement":"จีโนมของ coronavirus เป็น RNA สายเดี่ยว สายบวก (positive-sense, single-stranded) และไม่แบ่งเป็นท่อน (non-segmented) ตรงกับที่สไลด์อธิบายว่าเป็นอาร์เอ็นเอไวรัสสายเดี่ยวสายบวก","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2018","locator":"Section A Introduction, p. 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Coronaviruses have a non-segmented, positive-sense, single-stranded RNA genome."}}]},"avian-medicine--avian-ib--genotype-และสายพันธุ์ของ-ibv":{"claims":[{"id":"avian-medicine--avian-ib--genotype-และสายพันธุ์ของ-ibv--v1","statement":"ระบบจำแนก genotype ของ IBV ที่ใช้กันสากลอาศัยลำดับนิวคลีโอไทด์ทั้งสายของ S1 gene โดยงานตั้งต้นของ Valastro และคณะ (2016) แบ่งได้ 6 genotypes ครอบคลุม 32 lineages พร้อม inter-lineage recombinants ยืนยันหลักการที่สไลด์ใช้ว่า genotype จำแนกด้วย S1 gene (ตัวเลข GI-1 ถึง GI-29 และ GVII ในสไลด์เป็นการขยายเพิ่มในภายหลังจากกรอบเดิมนี้)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26883378","locator":"Vol. 39, pp. 349-364, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"By using complete nucleotide sequences of the S1 gene we determined the phylogenetic structure of IBV, which in turn allowed us to define 6 genotypes that together comprise 32 distinct viral lineages and a number of inter-lineage recombinan"}},{"id":"avian-medicine--avian-ib--genotype-และสายพันธุ์ของ-ibv--v2","statement":"GI-19 lineage คือกลุ่มที่เรียกกันว่า QX type ตรงกับที่สไลด์จับคู่ GI-19 กับ QX/QX-like และวรรณกรรมปัจจุบันยังอ้างถึง lineage GI-28 และ GI-29 ซึ่งสอดคล้องกับช่วง GI-1 ถึง GI-29 ที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-42127850","locator":"Vol. 105(8), 107032, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Complete genome analysis of three IBV isolates showed the highest nucleotide homology with YX10 strain (GI-19 lineage, QX type)."}}]},"avian-medicine--avian-ib--ความรุนแรงของโรคและปัจจัยที่มีผล":{"claims":[{"id":"avian-medicine--avian-ib--ความรุนแรงของโรคและปัจจัยที่มีผล--v1","statement":"ความรุนแรงและผลกระทบของการติดเชื้อ IBV ขึ้นกับ strain ของไวรัส อายุไก่ตอนติดเชื้อ โภชนาการ และสภาพแวดล้อมทั้งในโรงเรือน เช่น ระดับแอมโมเนีย และภายนอก เช่น อุณหภูมิ ตรงกับรายการปัจจัยที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17296157","locator":"Section 9 Prevention, p. 289","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The extent to which infection is an economic problem will depend on many factors, including the strain of virus, age of chicken at infection, nutrition, and the environment both within the poultry house e.g. ammonia levels, and outside e.g."}},{"id":"avian-medicine--avian-ib--ความรุนแรงของโรคและปัจจัยที่มีผล--v2","statement":"ความรุนแรงของโรคที่ระบบหายใจจะเพิ่มขึ้นเมื่อมีเชื้อก่อโรคอื่นโดยเฉพาะแบคทีเรียร่วมด้วย จนกลายเป็น chronic complicated airsacculitis ซึ่งอธิบายว่าเหตุใดตัวเลขอัตราการตายในสไลด์หน้า 7 (0%) กับหน้า 11 (5-25%) จึงต่างกัน คือขึ้นกับว่ามี co-infection หรือไม่","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2018","locator":"Chapter 3.3.2, Summary, p. 1","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The severity of IBV-induced respiratory disease is enhanced by the presence of other pathogens, including bacteria, leading to chronic complicated airsacculitis."}}]},"avian-medicine--avian-ib--เซลล์และอวัยวะเป้าหมาย-การติดต่อ-ระยะฟักตัว":{"claims":[{"id":"avian-medicine--avian-ib--เซลล์และอวัยวะเป้าหมาย-การติดต่อ-ระยะฟักตัว--v1","statement":"IBV เริ่มติดเชื้อที่ upper respiratory tract โดยจำกัดอยู่เฉพาะ ciliated cells และ mucus-secreting cells ตรงกับที่สไลด์ระบุว่าเซลล์เป้าหมายคือ epithelial cells ของท่อลม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17296157","locator":"Section 3 Pathogenesis of IBV, p. 284","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"IBV initially infects the upper respiratory tract, where it is restricted to the ciliated and mucus-secreting cells"}},{"id":"avian-medicine--avian-ib--เซลล์และอวัยวะเป้าหมาย-การติดต่อ-ระยะฟักตัว--v2","statement":"ระยะฟักตัวของ IB อยู่ที่ประมาณ 18 ถึง 36 ชั่วโมงหลังได้รับเชื้อ ซึ่งครอบคลุมตัวเลข 36 ชั่วโมงที่สไลด์ระบุ (แหล่งอ้างอิงให้เป็นช่วง ไม่ใช่ค่าเดียว)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38771617","locator":"Vol. 73(5), clinical signs section","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the incubation period can vary between 18 to 36 h post-infection"}},{"id":"avian-medicine--avian-ib--เซลล์และอวัยวะเป้าหมาย-การติดต่อ-ระยะฟักตัว--v3","statement":"IB ติดต่อทางอากาศ (air-borne route) การสัมผัสไก่ต่อไก่โดยตรง และทางอ้อมผ่านอุปกรณ์ ถาดไข่ มูลไก่ และการเยี่ยมฟาร์ม อีกทั้งเกิดได้กับไก่ทุกอายุ ตรงกับสไลด์ที่ระบุ aerosol, direct contact และ susceptible age = all ages","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2018","locator":"Section A Introduction, p. 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"IB affects chickens of all ages ... The disease is transmitted by the air-borne route, direct chicken-to-chicken contact and indirectly through mechanical spread (contaminated poultry equipment or egg-packing materials, manure used as ferti"}},{"id":"avian-medicine--avian-ib--เซลล์และอวัยวะเป้าหมาย-การติดต่อ-ระยะฟักตัว--v4","statement":"ทั้งเชื้อวัคซีนและเชื้อ field strain ของ IBV สามารถคงอยู่ที่ caecal tonsil ของทางเดินอาหารและถูกขับออกทางมูลได้นานเป็นสัปดาห์หรือนานกว่านั้นในไก่ที่ดูปกติ สนับสนุนที่สไลด์ระบุว่า chronic: intestinal tract คือ cecal tonsil","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2018","locator":"Section A Introduction, p. 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Vaccine and field strains of IBV may persist in the caecal tonsils of the intestinal tract and be excreted in faeces for weeks or longer in clinically normal chickens."}}]},"avian-medicine--avian-ib--พยาธิกำเนิดในระบบหายใจ-pathogenesis-respiratory-tract":{"claims":[{"id":"avian-medicine--avian-ib--พยาธิกำเนิดในระบบหายใจ-pathogenesis-respiratory-tract--v1","statement":"ปริมาณไวรัสที่มีชีวิตขึ้นสูงสุดในจมูกและท่อลมภายใน 3 วัน และคงอยู่ต่ออีก 2 ถึง 5 วัน สอดคล้องกับที่สไลด์ระบุว่าพบไวรัสใน nose และ trachea ช่วง 1-5 DPI","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17296157","locator":"Section 3 Pathogenesis of IBV, p. 284","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Titres of live virus are maximal in the nose and trachea within three days and remain so for two to five days further"}},{"id":"avian-medicine--avian-ib--พยาธิกำเนิดในระบบหายใจ-pathogenesis-respiratory-tract--v2","statement":"พบ titre ไวรัสในปอดและถุงลมใกล้เคียงกับในท่อลม และแม้จะเห็นบริเวณปอดอักเสบเล็กน้อยได้ แต่ IBV ไม่ถือว่าเป็นสาเหตุของ pneumonia ตรงกับสไลด์ที่ระบุ mild or no pneumonia หากไม่มี secondary infection","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17296157","locator":"Section 3 Pathogenesis of IBV, p. 284","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Similar virus titres occur in the lungs and airsacs. Small areas of pneumonia may be observed in the lungs, although IBV is not considered to cause pneumonia"}},{"id":"avian-medicine--avian-ib--พยาธิกำเนิดในระบบหายใจ-pathogenesis-respiratory-tract--v3","statement":"หลังติดเชื้อจะเกิดการสูญเสีย cilia (deciliation) ของเยื่อบุจมูกและท่อลม และตามมาด้วย secondary bacterial infection ซึ่งเป็นสาเหตุหลักของโรคที่รุนแรงที่สุดรวมถึงการตาย ตรงกับกลไกที่สไลด์อธิบาย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17296157","locator":"Section 3 Pathogenesis of IBV, p. 284","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Deciliation of the ciliated epithelia of the nose and trachea follows infection. Infection is commonly followed by secondary bacterial infections, which can be the main cause of the most debilitating disease, including mortality"}}]},"avian-medicine--avian-ib--อวัยวะที่-ibv-เข้าไปติดเชื้อได้":{"claims":[{"id":"avian-medicine--avian-ib--อวัยวะที่-ibv-เข้าไปติดเชื้อได้--v1","statement":"นอกจากเนื้อเยื่อระบบหายใจ IBV ยังเจริญได้ที่ผิว epithelium อื่นอีกหลายแห่ง ได้แก่ ไต (สัมพันธ์กับ nephritis) ท่อนำไข่ อัณฑะ และหลายส่วนของทางเดินอาหารรวมถึง caecal tonsil ครอบคลุมทั้ง 4 ระบบที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17296157","locator":"Section 3 Pathogenesis of IBV, p. 284","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"IBV grows at many other epithelial surfaces, including in kidney (associated with minor or major nephritis), oviduct, testes, and many parts of the alimentary tract"}}]},"avian-medicine--avian-ib--อาการโดยรวม":{"claims":[{"id":"avian-medicine--avian-ib--อาการโดยรวม--v1","statement":"IBV มี tissue tropism และความรุนแรงที่แตกต่างกันตาม strain โดยบาง strain ทำให้เกิดอาการเพียงเล็กน้อย ขณะที่บาง strain ทำให้อัตราการตายสูง ยืนยันหลักที่สไลด์ระบุว่าอาการขึ้นกับ IBV strain ระดับภูมิคุ้มกัน และอายุไก่","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35978541","locator":"Vol. 100(10), pp. 496-512, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"IBV has variable tissue tropism depending on the strain, and can affect the respiratory, reproductive, or urinary tracts ... the pathogenicity of IBV is also variable, with some strains causing only mild clinical signs, while infection with"}},{"id":"avian-medicine--avian-ib--อาการโดยรวม--v2","statement":"IBV ติดต่อได้ง่ายมาก และเนื่องจาก serotype ต่าง ๆ คุ้มกันข้ามกันได้ไม่ดี ไก่จึงติดเชื้อซ้ำได้หลายครั้ง แม้ภายในช่วงชีวิตสั้น ๆ 6 สัปดาห์ของไก่เนื้อ สนับสนุนอัตราการป่วยที่สูงถึง 100% ตามที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17296157","locator":"Section 7 Epidemiology and clinical signs, p. 289","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The virus is highly infectious ... As serotypes cross-protect poorly, chickens can be productively infected several times including more than once within the short, six-week life of a meat-type chicken."}}]},"avian-medicine--avian-ib--อาการระบบหายใจ-และ-secondary-infection":{"claims":[{"id":"avian-medicine--avian-ib--อาการระบบหายใจ-และ-secondary-infection--v1","statement":"ไก่โดยเฉพาะไก่เล็กจะแสดงอาการน้ำมูกไหล จาม (snicking) มีเสียง rales จากทางเดินหายใจส่วนล่าง ตาแฉะน้ำตาไหล และซึม ตรงกับรายการอาการที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17296157","locator":"Section 7 Epidemiology and clinical signs, p. 289","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Chickens, especially young ones, exhibit nasal discharge, snicking (similar to sneezing), râles (a vibration emanating from lower in the respiratory tract watery), watery eyes and lethargy."}},{"id":"avian-medicine--avian-ib--อาการระบบหายใจ-และ-secondary-infection--v2","statement":"ลูกไก่อาจตายจาก IBV โดยตรงได้ แต่จำนวนที่ตายจาก secondary bacterial infection มีมากกว่า ยืนยันข้อความหลักของสไลด์ที่ว่า IBV เองไม่ค่อยทำให้ไก่ตาย แต่เปิดทางให้เชื้อแทรกซ้อน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17296157","locator":"Section 7 Epidemiology and clinical signs, p. 289","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Young chicks may die directly from IBV infection but a greater number die following secondary bacterial infection."}},{"id":"avian-medicine--avian-ib--อาการระบบหายใจ-และ-secondary-infection--v3","statement":"โรคระบบหายใจแบบหลายปัจจัยในไก่มักเกิดจากการติดเชื้อร่วมระหว่างแบคทีเรีย เช่น Mycoplasma gallisepticum, M. synoviae, Escherichia coli กับไวรัสอย่าง IBV และ ILT ยืนยันรายการเชื้อแทรกซ้อน E. coli, MG, MS ที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30973078","locator":"Vol. 31(3), pp. 336-342, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Multifactorial respiratory diseases were commonly caused by coinfection with bacteria (e.g., Mycoplasma gallisepticum and M. synoviae, Escherichia coli, Avibacterium spp.) and viruses, such as infectious bronchitis and infectious laryngotra"}}]},"avian-medicine--avian-ib--อาการระบบสืบพันธุ์-ไข่ลดและคุณภาพไข่":{"claims":[{"id":"avian-medicine--avian-ib--อาการระบบสืบพันธุ์-ไข่ลดและคุณภาพไข่--v1","statement":"ในแม่ไก่ไข่ IBV ทำให้ผลผลิตไข่ลดลงและคุณภาพไข่แย่ลง โดยผลผลิตอาจไม่กลับคืนสู่ระดับปกติอีกเลย ตรงกับที่สไลด์ระบุว่าบางฝูงอาจให้ไข่ลดลงถาวรและกลับมาไม่ได้อีก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17296157","locator":"Section 7 Epidemiology and clinical signs, p. 289","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In layers, there is a drop in egg production, which might never return to normal, and in quality of eggs."}},{"id":"avian-medicine--avian-ib--อาการระบบสืบพันธุ์-ไข่ลดและคุณภาพไข่--v2","statement":"การติดเชื้อที่ท่อนำไข่ตอนอายุน้อยมากทำให้เกิดความเสียหายถาวร และในแม่ไก่ทำให้หยุดไข่ หรือให้ไข่เปลือกบางผิดรูปและสีเปลือกซีดลง ตรงกับลักษณะคุณภาพไข่ที่สไลด์ระบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2018","locator":"Section A Introduction, p. 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Infection of the oviduct at a very young age can lead to permanent damage and, in hens, can lead to cessation of egg-laying or production of thin-walled and misshapen shells with loss of shell pigmentation."}}]},"avian-medicine--avian-ib--false-layer-และ-penguin-like-posture":{"claims":[{"id":"avian-medicine--avian-ib--false-layer-และ-penguin-like-posture--v1","statement":"ลักษณะเด่นที่สุดของ QX IBV คือการติดเชื้อในระยะไก่เล็กทำให้ท่อนำไข่พัฒนาผิดปกติ ส่งผลให้เกิด false layer ในสัดส่วนสูงในฝูงไก่ไข่และไก่พ่อแม่พันธุ์ ตรงกับที่สไลด์ระบุว่า false layer มักเกิดเมื่อติดเชื้อตอนอายุน้อย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35392927","locator":"Vol. 19, article 62, Background","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The most significant feature of QX IBV is that its infection in the early growing stage can cause abnormal oviduct development, resulting in a high proportion of 'false layers' in poultry flocks of laying hens and breeders."}},{"id":"avian-medicine--avian-ib--false-layer-และ-penguin-like-posture--v2","statement":"False layer syndrome (FLS) คือภาวะที่แม่ไก่ซึ่งโตเต็มวัยตกไข่ได้ตามปกติแต่ไม่สามารถออกไข่ได้ อธิบายที่มาของถุงน้ำในช่องท้องและท่าทางยืนตั้งตัวแบบเพนกวินที่ปรากฏในรูปสไลด์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34427410","locator":"Vol. 65(3), pp. 373-380, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"occasionally leading to a condition called false layer syndrome (FLS), where sexually mature hens ovulate normally but are unable to lay eggs"}}]},"avian-medicine--avian-ib--อาการไตอักเสบ-และฝูงที่ป่วยน้อย":{"claims":[{"id":"avian-medicine--avian-ib--อาการไตอักเสบ-และฝูงที่ป่วยน้อย--v1","statement":"ในการระบาดของ nephropathogenic IB อาการเริ่มแรกคือ อัตราการตายในฝูงสูงขึ้น และการสูญเสียน้ำทางปัสสาวะ (polyuria และ pollakiuria) จนสิ่งปูรองเปียก ตรงกับที่สไลด์ระบุว่าไก่ดื่มน้ำเยอะ ถ่ายเหลว และมีสภาพแห้งน้ำ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12495045","locator":"Vol. 46(4), pp. 847-858, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Early clinical signs were increased flock mortality and urinary water loss (polyuria and pollakiuria) leading to wet litter."}},{"id":"avian-medicine--avian-ib--อาการไตอักเสบ-และฝูงที่ป่วยน้อย--v2","statement":"ในฝูงไก่เนื้อที่เป็น nephropathogenic IB พบอาการทางระบบหายใจน้อยมาก ซึ่งอธิบายว่าเหตุใดฝูงที่ป่วยน้อยจึงอาจไม่แสดงอาการ IB ให้เห็นชัดและทำให้วินิจฉัยสาเหตุผิดพลาดได้ตามที่สไลด์เตือนไว้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12495045","locator":"Vol. 46(4), pp. 847-858, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Minimal respiratory disease signs were noted in broilers."}}]},"avian-medicine--avian-ib--รอยโรค-lesions":{"claims":[{"id":"avian-medicine--avian-ib--รอยโรค-lesions--v1","statement":"รอยโรคที่ไตของ nephropathogenic IB คือ ไตบวมอย่างรุนแรงและมี urate สะสมในท่อไต ซึ่งบางครั้งพบ visceral gout และ urolithiasis ร่วมด้วย ตรงกับรอยโรคไตที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12495045","locator":"Vol. 46(4), pp. 847-858, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Severe renal swelling and accumulation of urates in the tubules were commonly seen. Visceral gout and urolithiasis were less frequently observed."}},{"id":"avian-medicine--avian-ib--รอยโรค-lesions--v2","statement":"การติดเชื้อ IBV ทำให้เห็นไตบวมและมี urate deposits ร่วมกับ nephritis ในไก่ที่แสดงอาการหายใจลำบาก ยืนยันภาพรอยโรค ไตบวม ซีด หรือเป็นสี marble ที่สไลด์บรรยาย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-19934604","locator":"Vol. 10(4), pp. 357-359, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"chickens exhibited severe respiratory symptoms (dyspnea) and nephropathogenic lesions (swollen kidneys with nephritis and urate deposits)"}},{"id":"avian-medicine--avian-ib--รอยโรค-lesions--v3","statement":"รอยโรคที่ถุงลมแบบเรื้อรังในรูป chronic complicated airsacculitis เกิดขึ้นเมื่อมีเชื้อก่อโรคอื่นโดยเฉพาะแบคทีเรียร่วมด้วย สนับสนุนรอยโรค foamy air sac และถุงลมขุ่นมี caseous exudate ที่สไลด์ระบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2018","locator":"Chapter 3.3.2, Summary, p. 1","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The severity of IBV-induced respiratory disease is enhanced by the presence of other pathogens, including bacteria, leading to chronic complicated airsacculitis."}}]},"avian-medicine--avian-ib--การวินิจฉัย-diagnosis":{"claims":[{"id":"avian-medicine--avian-ib--การวินิจฉัย-diagnosis--v1","statement":"เมื่อฉีดเชื้อเข้า allantoic cavity ของไข่ไก่ฟัก SPF เชื้อ IBV จะทำให้ตัวอ่อนแคระ (stunting) ขดตัว (curling) ขนเป็นกระจุก (clubbing of the down) หรือมี urate สะสมที่ mesonephros ของไต โดยมักเห็นภายใน 3 passages ตรงกับ stunting/curling ที่สไลด์ระบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2018","locator":"Chapter 3.3.2, Summary, p. 1 and Section B.1.2 Culture, p. 4","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Following inoculation of the allantoic cavity, IBV produces embryo stunting, curling, clubbing of the down, or urate deposits in the mesonephros of the kidney, often within three serial passages."}},{"id":"avian-medicine--avian-ib--การวินิจฉัย-diagnosis--v2","statement":"สำหรับโรคระบบหายใจแบบเฉียบพลัน ตัวอย่างที่เหมาะสมคือ swab จากทางเดินหายใจส่วนต้นหรือเนื้อเยื่อท่อลมและปอด ส่วนกรณีที่มี nephritis หรือปัญหาการผลิตไข่ ต้องเก็บไตหรือท่อนำไข่เพิ่ม ยืนยันที่สไลด์ระบุว่าตัวอย่างหลักคือ trachea","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2018","locator":"Section B.1.1 Sampling, p. 3","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"For acute respiratory disease, swabs from the upper respiratory tract of live birds or tracheal and lung tissues from diseased birds should be harvested. For birds with nephritis and or egg-production problems, samples from the kidneys or o"}},{"id":"avian-medicine--avian-ib--การวินิจฉัย-diagnosis--v3","statement":"บริเวณเป้าหมายมาตรฐานสำหรับการตรวจจำแนก IBV ด้วย RT-PCR และการทำ sequencing คือ S1 subunit ของ S glycoprotein gene และการวิเคราะห์นี้ใช้ตรวจหา vaccine strain ภายในฝูงได้ ตรงกับที่สไลด์ระบุว่าใช้ S1 sequencing แยก field strain ออกจาก vaccine strain","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2018","locator":"Section B.1.5.1 RT-PCR, p. 5","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The usual target region for IBV characterisation is the S1 subunit of the S glycoprotein gene. ... Such analyses allow rapid epidemiological assessment of the origins and spread of the viruses responsible for IBV outbreaks and the detection"}},{"id":"avian-medicine--avian-ib--การวินิจฉัย-diagnosis--v4","statement":"ในบรรดาการตรวจทางซีรั่มวิทยา ELISA เหมาะที่สุดสำหรับงานตรวจประจำและตรวจจับแอนติบอดีทั้งจากวัคซีนและการติดเชื้อในสนาม ขณะที่ VN จำเพาะต่อ serotype มากกว่าแต่แพงและไม่สะดวกในภาคสนาม ซึ่งเป็นข้อจำกัดที่สไลด์ไม่ได้กล่าวถึง","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2018","locator":"Section B.2 Serological tests, p. 6","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In general, ELISAs are most suitable for routine serological testing and can detect antibodies caused by vaccination and field exposure. ... VN tests are too expensive and impractical for use in field conditions."}}]},"avian-medicine--avian-ib--การควบคุมและป้องกันโรค-หลักการ-2-ข้อ":{"claims":[{"id":"avian-medicine--avian-ib--การควบคุมและป้องกันโรค-หลักการ-2-ข้อ--v1","statement":"ในพื้นที่ที่มีฟาร์มสัตว์ปีกหนาแน่น แทบเป็นไปไม่ได้ที่จะเลี้ยงไก่ให้ปลอดจาก IBV และ biosecurity เพียงอย่างเดียวมักไม่เพียงพอเพราะไวรัสแพร่ได้ง่าย จึงต้องใช้การทำวัคซีนร่วมด้วย อธิบายว่าเหตุใดสไลด์จึงวางหลักการควบคุมไว้ 2 ข้อคู่กัน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17296157","locator":"Section 9 Prevention, p. 289","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In areas where there are many poultry farms, it is virtually impossible to keep chickens free of IBV. Biosecurity is likely to be insufficient, as the virus is spread readily. Consequently vaccination is commonly practised."}}]},"avian-medicine--avian-ib--biosecurity":{"claims":[{"id":"avian-medicine--avian-ib--biosecurity--v1","statement":"IBV แพร่กระจายทางอ้อมผ่านการพาไปเชิงกล ได้แก่ อุปกรณ์การเลี้ยงและวัสดุบรรจุไข่ที่ปนเปื้อน มูลไก่ที่นำไปใช้เป็นปุ๋ย และการเข้าเยี่ยมฟาร์ม ซึ่งเป็นเหตุผลโดยตรงของมาตรการควบคุมคน สิ่งของ ยานพาหนะ และการฆ่าเชื้อที่สไลด์ระบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2018","locator":"Section A Introduction, p. 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"indirectly through mechanical spread (contaminated poultry equipment or egg-packing materials, manure used as fertiliser, farm visits, etc.)"}}]},"avian-medicine--avian-ib--management":{"claims":[{"id":"avian-medicine--avian-ib--management--v1","statement":"โภชนาการและสภาพแวดล้อมภายในโรงเรือน โดยเฉพาะระดับแอมโมเนีย รวมถึงอุณหภูมิภายนอก เป็นปัจจัยที่กำหนดว่าการติดเชื้อ IBV จะสร้างความเสียหายมากเพียงใด สนับสนุนรายการจัดการเรื่องคุณภาพอาหาร การถ่ายเทอากาศ และความหนาแน่นที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17296157","locator":"Section 9 Prevention, p. 289","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"will depend on many factors, including the strain of virus, age of chicken at infection, nutrition, and the environment both within the poultry house e.g. ammonia levels, and outside e.g. temperature"}}]},"avian-medicine--avian-ib--วัคซีนเชื้อเป็น-live-vaccine":{"claims":[{"id":"avian-medicine--avian-ib--วัคซีนเชื้อเป็น-live-vaccine--v1","statement":"วิธีให้วัคซีนเชื้อเป็นที่ใช้กันทั่วไปคือการพ่นแบบ coarse spray หรือ aerosol และการให้ทางน้ำดื่ม ส่วนการหยอดตาเป็นวิธีที่ดีมากหากทำอย่างระมัดระวังแต่มักมีต้นทุนสูงเกินไป ตรงกับรายการ route ที่สไลด์ระบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2018","locator":"Section C.1 Requirements for vaccines, Background, p. 8","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Commonly used administration routes for live vaccines are spray (course spray or aerosol) or in the drinking water (oral route). Administration by eye-drop, if carefully done, is a very good method but in many cases too expensive."}},{"id":"avian-medicine--avian-ib--วัคซีนเชื้อเป็น-live-vaccine--v2","statement":"โดยทั่วไปวัคซีนเชื้อเป็นจะให้แก่ไก่เนื้อตั้งแต่อายุ 1 วันที่โรงฟัก ตรงกับโปรแกรม 1 day old at hatchery ที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17296157","locator":"Section 10.1 Live vaccines, p. 290","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Live vaccines are usually applied to meat-type chickens at one day of age, in the hatchery."}},{"id":"avian-medicine--avian-ib--วัคซีนเชื้อเป็น-live-vaccine--v3","statement":"ภูมิคุ้มกันจากวัคซีนเชื้อเป็นอยู่ได้ไม่นาน เริ่มลดลงตั้งแต่ 9 สัปดาห์หลังทำวัคซีน ไก่ไข่ที่เลี้ยงยาวกว่าหนึ่งปีจึงต้องทำวัคซีนเชื้อเป็นซ้ำหลายครั้ง และไก่เนื้อก็อาจต้องทำซ้ำหากพื้นที่นั้นมีปัญหา IB มาก สนับสนุนโปรแกรม booster ทั้งไก่เนื้อและไก่ไข่ที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17296157","locator":"Section 10.1 Live vaccines, p. 290","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"protection is short-lived, the start of the decline being apparent nine weeks after vaccination. Consequently commercial egg layers, which are kept for a year or more, are vaccinated several times with live vaccine, perhaps with more than o"}}]},"avian-medicine--avian-ib--วัคซีนเชื้อตาย-killed-vaccine":{"claims":[{"id":"avian-medicine--avian-ib--วัคซีนเชื้อตาย-killed-vaccine--v1","statement":"วัคซีนเชื้อตายชนิดฉีดเข็มเดียวโดยไม่มี live priming ไม่ให้ความคุ้มโรคที่มีนัยสำคัญ จึงต้องนำหน้าด้วยวัคซีนเชื้อเป็นอย่างน้อยหนึ่งครั้ง ตรงกับที่สไลด์ระบุว่าต้อง booster ด้วยวัคซีนเชื้อเป็นอย่างสม่ำเสมอ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2018","locator":"Chapter 3.3.2, Summary, p. 1","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Inactivated vaccines are injected and a single inoculation does not confer significant protection unless preceded by one or more live IBV priming vaccinations."}},{"id":"avian-medicine--avian-ib--วัคซีนเชื้อตาย-killed-vaccine--v2","statement":"วัคซีนเชื้อตายชนิด oil emulsion ถูกพัฒนาขึ้นเพื่อสร้างภูมิคุ้มกันระยะยาวในแม่ไก่และป้องกันการลดลงของผลผลิตไข่ แต่การให้ครั้งเดียวไม่ป้องกันการสูญเสียการทำงานของ cilia ในท่อลม ยืนยันข้อความในสไลด์ที่ว่าวัคซีนเชื้อตายป้องกันอวัยวะภายในได้ดีแต่ไม่ค่อยมีผลกับ epithelial cell ของทางเดินหายใจ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17296157","locator":"Section 10.2 Inactivated virus and subunit vaccines, p. 290","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The objective was to make a vaccine that would give long-lasting immunity to the hen bird, to protect against drops in egg production. Single applications of inactivated virus induced little or no protection against egg loss, and no protect"}},{"id":"avian-medicine--avian-ib--วัคซีนเชื้อตาย-killed-vaccine--v3","statement":"แนวปฏิบัติทั่วไปคือทำวัคซีนเชื้อเป็นในไก่ไข่ตั้งแต่อายุ 2-3 สัปดาห์ แล้วทำเชื้อเป็นซ้ำอีกหลายครั้ง จนกระทั่งก่อนไก่เริ่มให้ไข่ไม่นานจึงให้วัคซีนเชื้อตาย ตรงกับที่สไลด์ระบุว่าวัคซีนเชื้อตายให้ช่วงก่อนให้ไข่","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17296157","locator":"Section 10.2 Inactivated virus and subunit vaccines, p. 290","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"common practice is to vaccinate egg layers with live vaccine at two or three weeks of age, followed by more live vaccinations until shortly before the birds start laying eggs they are given killed vaccine"}},{"id":"avian-medicine--avian-ib--วัคซีนเชื้อตาย-killed-vaccine--v4","statement":"วัคซีนเชื้อตายต้องให้ทีละตัวโดยการฉีดเข้ากล้ามเนื้อหรือใต้ผิวหนัง และประสิทธิภาพขึ้นกับการ prime ด้วยวัคซีนเชื้อเป็นอย่างเหมาะสมเป็นหลัก","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2018","locator":"Section C.1 Requirements for vaccines, Background, p. 8","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The efficacy of inactivated vaccines depends heavily on proper priming with a live vaccine(s). Inactivated vaccines must be administered to birds individually, by intramuscular or subcutaneous injection."}}]},"avian-medicine--avian-ib--mda-และหลักการเลือกวัคซีนให้ตรงสายพันธุ์":{"claims":[{"id":"avian-medicine--avian-ib--mda-และหลักการเลือกวัคซีนให้ตรงสายพันธุ์--v1","statement":"ลูกไก่ที่มี maternal antibody ได้รับความคุ้มกันต่อการ challenge จนถึงอายุ 4 สัปดาห์ โดย MDA มีค่าครึ่งชีวิต 5-6 วัน และผู้วิจัยสรุปว่าอายุที่เหมาะสมที่สุดสำหรับการทำวัคซีนครั้งแรกคือประมาณ 2 สัปดาห์ สนับสนุนทั้งสองประเด็นของสไลด์ คือ MDA ช่วยป้องกันในไก่อายุน้อย แต่ก็มีผลต่อการตอบสนองต่อวัคซีนเชื้อเป็นที่ทำตอนอายุ 1 วัน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-2983406","locator":"Vol. 38(1), pp. 14-21, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Maternal antibody in unvaccinated chicks declined linearly with a mean half-life of five to six days based on both HI and SN tests; these chicks were protected against challenge until four weeks old ... It was concluded that the optimum age"}},{"id":"avian-medicine--avian-ib--mda-และหลักการเลือกวัคซีนให้ตรงสายพันธุ์--v2","statement":"ความแตกต่างของกรดอะมิโนใน S1 เพียง 2-3% (ราว 10-15 ตำแหน่ง) ก็เพียงพอที่จะเปลี่ยน serotype ได้ และภูมิคุ้มกันจาก serotype หนึ่งป้องกันการติดเชื้อ serotype อื่นได้ไม่ดี ยืนยันหลัก low cross-protection ที่สไลด์ใช้เป็นเหตุผลในการเลือกวัคซีนให้ตรงสายพันธุ์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17296157","locator":"Section 8 Antigenic diversity, p. 289","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the immunity induced by inoculation with one serotype protects poorly against infection with heterologous serotypes ... differences of as few as 2 to 3% of S1 amino acid residues (10 to 15 residues) can result in a change in serotype"}},{"id":"avian-medicine--avian-ib--mda-และหลักการเลือกวัคซีนให้ตรงสายพันธุ์--v3","statement":"เนื่องจากความสัมพันธ์ระหว่างความเหมือนของยีน S กับระดับ cross-protection ไม่แน่นพอ จึงต้องทำ cross-immunisation study เพื่อระบุความคุ้มกันข้ามสายพันธุ์ของเชื้อแต่ละตัว ตรงกับที่สไลด์แนะนำว่าอาจต้องตรวจ cross-protection ก่อน","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2018","locator":"Section C.1 Requirements for vaccines, Background, p. 8","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"However, the vaccination-challenge experiments have shown that the relationship is not very strong. Therefore, a cross-immunisation study has to be performed to be able to determine the cross-protective immunity of a strain."}},{"id":"avian-medicine--avian-ib--mda-และหลักการเลือกวัคซีนให้ตรงสายพันธุ์--v4","statement":"การใช้วัคซีนเชื้อเป็นที่ต่างกันทาง antigen สองตัว เช่น Mass ร่วมกับ 4/91 สามารถให้ cross-protection ที่กว้างครอบคลุม IBV หลายชนิด สนับสนุนคำแนะนำในสไลด์ที่ว่าสามารถเติมวัคซีนเชื้อเป็นสายพันธุ์อื่นที่ระบาดในพื้นที่เข้าไปในโปรแกรมได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-21711181","locator":"Vaccination strategies section","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"vaccination with two antigenically distinct live-attenuated vaccines such as Mass and 4/91 can result in a broad cross-protection against many different IBV types."}}]},"avian-medicine--avian-ib--ข้อควรระวังในการใช้วัคซีนเชื้อเป็น":{"claims":[{"id":"avian-medicine--avian-ib--ข้อควรระวังในการใช้วัคซีนเชื้อเป็น--v1","statement":"การนำเชื้อวัคซีน IBV ไป passage ซ้ำในไก่ทำให้เชื้อกลับมามีความรุนแรงเพิ่มขึ้น โดยเพิ่มอุบัติการณ์และความรุนแรงของ airsacculitis จาก Mycoplasma synoviae ยืนยันกลไก rolling infection ที่สไลด์อธิบายว่าไวรัสวัคซีนพัฒนาให้ก่อโรครุนแรงกว่าต้นฉบับ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-3015106","locator":"Vol. 30(1), pp. 221-223, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Serial passage of two infectious bronchitis virus (IBV) vaccine strains in chickens enhanced their capacity to increase the incidence and severity of Mycoplasma synoviae (MS) airsacculitis. ... All IBV strains studied to date have either po"}},{"id":"avian-medicine--avian-ib--ข้อควรระวังในการใช้วัคซีนเชื้อเป็น--v2","statement":"วัคซีนเชื้อเป็นมีความเสี่ยงเรื่อง residual pathogenicity จากการ back-passage ในฝูง แต่การให้วัคซีนอย่างถูกต้องจนกระจายทั่วทั้งฝูงจะช่วยหลีกเลี่ยง back-passage ได้ ตรงกับคำเตือนของสไลด์ว่าการให้วัคซีนไม่ทั่วทั้งฝูงทำให้เกิด rolling infection","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2018","locator":"Section C.1 Requirements for vaccines, Background, p. 8","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Live vaccines carry a risk of residual pathogenicity associated with vaccine back-passage in flocks. However, proper application of vaccine can achieve uniform distribution of the vaccine in the flock and avoid back-passage."}},{"id":"avian-medicine--avian-ib--ข้อควรระวังในการใช้วัคซีนเชื้อเป็น--v3","statement":"การให้วัคซีน IBV ร่วมกับ NDV พบว่าเชื้อ IBV สายพันธุ์ Mass และ Ark รบกวนการเพิ่มจำนวนของ NDV และในการทดลองหนึ่งภูมิคุ้มกันต่อ ND ลดลงเมื่อใช้วัคซีนเดี่ยวสองชนิดให้พร้อมกัน ผู้วิจัยจึงเน้นให้ใช้วัคซีนรวมที่ผู้ผลิตเตรียมมาแล้วเพื่อเลี่ยงการรบกวน ยืนยันคำเตือนเรื่อง interference ในสไลด์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-18251404","locator":"Vol. 51(4), pp. 924-934, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the replication of IBV strains Mass and Ark interfered with the growth of NDV strains B1, VG/GA, and C2 as measured by qRT-PCR ... This finding emphasizes the importance of using manufactured combination vaccines whenever possible to avoid "}},{"id":"avian-medicine--avian-ib--ข้อควรระวังในการใช้วัคซีนเชื้อเป็น--v4","statement":"เชื้อ variant strain สามารถนำมาเตรียมเป็น inactivated autogenous vaccine สำหรับควบคุม IB ในไก่ไข่และไก่พ่อแม่พันธุ์ได้ ภายใต้ข้อกำหนดของกฎหมายท้องถิ่น ตรงกับที่สไลด์ระบุว่า autogenous vaccine ของ new variant หรือ recombinant strain ต้องทำเป็นวัคซีนเชื้อตาย","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2018","locator":"Section C.1 Requirements for vaccines, Background, p. 8","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Variant strains may be used to prepare inactivated autogenous vaccines for controlling IB in layers and breeders, subject to local legislative requirements."}}]},"avian-medicine--avian-ib--วัคซีนที่มีในประเทศไทย":{"claims":[{"id":"avian-medicine--avian-ib--วัคซีนที่มีในประเทศไทย--v1","statement":"การวิเคราะห์ S1 gene ของ IBV 120 ตัวที่แยกได้จากไก่ในประเทศไทยช่วงปี 2014-2016 พบว่าอยู่ใน 3 lineages คือ GI-1 (Massachusetts), GI-13 (793B/4-91) และ GI-19 (QX) พร้อมด้วย variant ตัวใหม่ ซึ่งตรงกับกลุ่มสายพันธุ์วัคซีนที่สไลด์ระบุว่ามีใช้ในประเทศไทย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32241468","locator":"Vol. 99(4), pp. 1888-1895, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Phylogenetic analysis of the complete S1 gene of 120 Thai IBVs revealed that the 2014-2016 Thai IBVs were divided into 3 lineages (GI-1, GI-13, and GI-19) and a novel IBV variant."}},{"id":"avian-medicine--avian-ib--วัคซีนที่มีในประเทศไทย--v2","statement":"GI-19 (QX) กลายเป็น lineage หลักที่ระบาดในฝูงไก่ของประเทศไทยระหว่างปี 2014-2016 ซึ่งอธิบายว่าเหตุใดวัคซีน QX-like จึงอยู่ในรายการวัคซีนที่มีใช้ในประเทศไทยตามที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32241468","locator":"Vol. 99(4), pp. 1888-1895, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Our results also showed that GI-19 lineage has become the predominant lineage of IBV circulating in chicken flocks in Thailand from 2014 to 2016."}}]},"avian-medicine--avian-ib--ตัวอย่างโปรแกรมวัคซีนในไก่เนื้อ":{"claims":[{"id":"avian-medicine--avian-ib--ตัวอย่างโปรแกรมวัคซีนในไก่เนื้อ--v1","statement":"ไก่เนื้อได้รับวัคซีนเชื้อเป็นครั้งแรกตอนอายุ 1 วันที่โรงฟัก และอาจได้รับซ้ำอีกครั้งหากพื้นที่นั้นมีปัญหา IB มาก โดยการทำซ้ำอาจใช้ serotype อื่นซึ่งบางครั้งให้ความคุ้มกันที่กว้างขึ้น ตรงกับโปรแกรม 2 ครั้งในไก่เนื้อที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17296157","locator":"Section 10.1 Live vaccines, p. 290","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Live vaccines are usually applied to meat-type chickens at one day of age, in the hatchery. ... Even broilers, which are processed at only six or so weeks of age, may be revaccinated if IB is very problematic in an area. Revaccination may b"}}]},"avian-medicine--avian-ib--ตัวอย่างโปรแกรมวัคซีนในไก่ไข่และไก่พ่อแม่พันธุ์-ช่วงไก่เล็กถึงไก":{"claims":[{"id":"avian-medicine--avian-ib--ตัวอย่างโปรแกรมวัคซีนในไก่ไข่และไก่พ่อแม่พันธุ์-ช่วงไก่เล็กถึงไก--v1","statement":"มีวัคซีนรวมทั้งชนิดเชื้อเป็นและเชื้อตายที่ผสม fraction อื่นเข้าด้วยกัน เช่น Newcastle disease, infectious bursal disease, avian metapneumovirus, reovirus และ EDS76 ซึ่งรองรับโปรแกรมที่ให้ IB คู่กับ ND ทุกครั้งและเข็มเชื้อตายรวม ND+IB+EDS+IC ตามที่สไลด์ระบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2018","locator":"Section C.2.1.2 Validation as a vaccine strain, p. 11","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Both live and inactivated multivalent vaccines containing other fractions such as Newcastle disease, infectious bursal disease, avian metapneumo-, reo- and EDS76 viruses are available."}},{"id":"avian-medicine--avian-ib--ตัวอย่างโปรแกรมวัคซีนในไก่ไข่และไก่พ่อแม่พันธุ์-ช่วงไก่เล็กถึงไก--v2","statement":"สำหรับไก่ที่เลี้ยงยาว การทำวัคซีนเชื้อเป็นเฉพาะช่วงไก่รุ่นมักไม่พอที่จะสร้างความคุ้มกันระยะยาวไปถึงช่วงให้ไข่ จึงต้อง boost ด้วยวัคซีนเชื้อตายคุณภาพดี ซึ่งอธิบายว่าเหตุใดโปรแกรมในสไลด์จึงจบด้วยเข็มเชื้อตายที่ 12 สัปดาห์ก่อนเข้าไข่","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2018","locator":"Section C.1 Requirements for vaccines, Background, p. 8","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"For long-living birds, vaccination with live vaccines only during the rearing period will often not be sufficient to induce a long-lasting protection against challenge in the laying period. Boosting with inactivated vaccines of a good quali"}}]},"avian-medicine--avian-ib--เชื้อและการจำแนก-genotype":{"claims":[{"id":"avian-medicine--avian-ib--เชื้อและการจำแนก-genotype--v1","statement":"ระบบจำแนก genotype ของ IBV ที่เป็นมาตรฐานสากลใช้ลำดับนิวคลีโอไทด์ทั้งยีนของ S1 มาสร้าง phylogeny แบ่งได้ 6 genotypes ซึ่งรวมกันมี 32 lineages ที่แตกต่างกัน พร้อมทั้งมีไวรัสลูกผสมข้าม lineage อีกจำนวนหนึ่ง สนับสนุนหลักที่สรุปเขียนว่าใช้ S1 gene ในการจำแนกและตั้งชื่อแบบ GI-x","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26883378","locator":"vol 39:349-364, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"By using complete nucleotide sequences of the S1 gene we determined the phylogenetic structure of IBV, which in turn allowed us to define 6 genotypes that together comprise 32 distinct viral lineages and a number of inter-lineage recombinan"}},{"id":"avian-medicine--avian-ib--เชื้อและการจำแนก-genotype--v2","statement":"IBV ที่ตรวจพบในไก่ในประเทศไทยช่วงปี 2014-2016 จำนวน 120 ตัวอย่าง แบ่งได้เป็น 3 lineages คือ GI-1, GI-13 และ GI-19 ตรงกับ 3 genotype ที่สรุประบุ (Massachusetts, 4/91, QX) โดย GI-19 กลายเป็น lineage เด่นที่สุด และยังพบไวรัสสายพันธุ์ใหม่ที่เป็นลูกผสมระหว่าง GI-19 กับ GI-13 ด้วย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32241468","locator":"vol 99(4):1888-1895, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Phylogenetic analysis of the complete S1 gene of 120 Thai IBVs revealed that the 2014-2016 Thai IBVs were divided into 3 lineages (GI-1, GI-13, and GI-19) and a novel IBV variant. Our results also showed that GI-19 lineage has become the pr"}}]},"avian-medicine--avian-ib--การวินิจฉัยและวัคซีน":{"claims":[{"id":"avian-medicine--avian-ib--การวินิจฉัยและวัคซีน--v1","statement":"ทั้งวัคซีนเชื้อเป็นและเชื้อตายของ IB ถูกใช้อย่างแพร่หลาย โดยวัคซีนเชื้อตายต้องมีการ prime ด้วยวัคซีนเชื้อเป็นก่อน และประสิทธิภาพของวัคซีนลดลงเพราะ cross protection ระหว่าง serotype ไม่ดี ตรงกับสองข้อที่สรุปเน้น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17296157","locator":"vol 38(2):281-97, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Both live and inactivated IB vaccines are used extensively, the latter requiring priming by the former. Their effectiveness is diminished by poor cross-protection."}},{"id":"avian-medicine--avian-ib--การวินิจฉัยและวัคซีน--v2","statement":"ความแตกต่างของกรดอะมิโนบนโปรตีน spike เพียงไม่กี่ตำแหน่งก็เพียงพอที่จะทำให้ cross protection เสียไป ซึ่งอธิบายว่าทำไมการมี IBV หลายสายพันธุ์ในฝูงจึงทำให้ผลของวัคซีนไม่แน่นอนตามที่สรุปเขียน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17296157","locator":"vol 38(2):281-97, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"There is increasing evidence that only a few amino acid differences amongst S proteins are sufficient to have a detrimental impact on cross-protection."}},{"id":"avian-medicine--avian-ib--การวินิจฉัยและวัคซีน--v3","statement":"ข้อกังวลของวัคซีน IB เชื้อเป็นที่สรุปไม่ได้เขียนไว้ครบ คือความเสี่ยงที่เชื้อจะกลับมามีความรุนแรง (reversion to virulence) การถูกลบล้างด้วย maternal antibody และเหตุการณ์ recombination กับ mutation ซึ่งเป็นเหตุผลเชิงวิชาการที่หนุนคำแนะนำในสรุปว่าถ้าทำ autogenous vaccine ของสายพันธุ์ใหม่ควรทำเป็นเชื้อตาย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-25954763","locator":"vol 2015:424860, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Although live attenuated IB vaccines remarkably induce potent immune response, the potential risk of reversion to virulence, neutralization by the maternal antibodies, and recombination and mutation events are important concern on their usa"}}]},"avian-medicine--avian-ib--อาการและรอยโรค-แยกตาม-3-ระบบ":{"claims":[{"id":"avian-medicine--avian-ib--อาการและรอยโรค-แยกตาม-3-ระบบ--v1","statement":"IBV ที่ติดเชื้อในระบบสืบพันธุ์เพศเมียภายใน 2 สัปดาห์แรกของชีวิต ทำให้เยื่อบุท่อนำไข่เกิด necrosis และเป็นแผลเป็น กลายเป็น cystic oviduct เรื้อรัง ทำให้ไก่สร้างไข่ไม่ได้เมื่อโตเต็มวัย ซึ่งคือกลไกของ false layer ตรงตามที่สรุประบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35068104","locator":"เล่ม 65 ฉบับ 4 หน้า 600-611, Abstract ส่วนระบบสืบพันธุ์","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Viral infection of the female reproductive tract in the first 2 weeks of life causes necrosis and scarring of the oviduct mucosa, resulting in a chronic cystic oviduct that precludes egg formation when the hen matures."}},{"id":"avian-medicine--avian-ib--อาการและรอยโรค-แยกตาม-3-ระบบ--v2","statement":"IBV ที่ติดเชื้อเยื่อบุจมูกและหลอดลมทำให้ ciliated epithelium หลุดลอกอย่างรวดเร็วและ mucociliary clearance เสียไป จึงทำให้ไก่ติดเชื้อแบคทีเรียแทรกซ้อน (secondary bacterial infection) ได้ง่าย ตรงกับที่สรุประบุว่า IB ไม่ได้ทำให้ไก่ตายเอง แต่เปิดทางให้เกิด secondary infection","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35068104","locator":"เล่ม 65 ฉบับ 4 หน้า 600-611, Abstract ส่วนระบบหายใจ","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Infection of the nasal and tracheal mucosa causes a rapid loss of ciliated epithelium and impaired mucociliary clearance that predispose chickens to secondary bacterial infections."}},{"id":"avian-medicine--avian-ib--อาการและรอยโรค-แยกตาม-3-ระบบ--v3","statement":"IBV สายพันธุ์ nephrotropic ทำให้เกิดโรคไตรุนแรง โดยมี necrosis ของเซลล์เยื่อบุท่อไต การอักเสบ และภาวะไตวาย สนับสนุนรอยโรคไตอักเสบที่สรุประบุ (ไตบวม ซีด มี urate คั่งในท่อไต)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35068104","locator":"เล่ม 65 ฉบับ 4 หน้า 600-611, Abstract ส่วนไต","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Nephrotropic IBV causes severe disease in the kidney with necrosis of tubular epithelial cells, inflammation, and renal failure."}},{"id":"avian-medicine--avian-ib--อาการและรอยโรค-แยกตาม-3-ระบบ--v4","statement":"การทดลอง challenge ไก่ SPF ด้วย IBV สายพันธุ์ DMV/1639 และ Massachusetts ที่อายุ 3, 7 และ 14 วัน พบว่ากลุ่มที่ติดเชื้อเมื่ออายุ 14 วันเกิด cystic oviduct น้อยกว่ากลุ่มที่ติดเชื้อเมื่ออายุ 3 หรือ 7 วัน และกลุ่มอายุ 3 วันมีคะแนนรอยโรคทางจุลพยาธิรุนแรงที่สุด ยืนยันเชิงปริมาณว่าอายุที่ติดเชื้อยิ่งน้อยยิ่งเสี่ยงต่อ false layer","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35632594","locator":"เล่ม 14 ฉบับ 5 บทความ 852, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Cystic oviducts were seen in all the challenged groups, and the pullets challenged at 14 days of age had fewer cystic oviducts than pullets challenged at 3 or 7 days of age. The highest percentage of severe histology lesion scores were seen"}}]}},"avian-medicine--avian-lt":{"avian-medicine--avian-lt--ภาพรวมของโรค-overview":{"claims":[{"id":"avian-medicine--avian-lt--ภาพรวมของโรค-overview--v1","statement":"ILT พบกระจายอยู่ทั่วโลกจริง โดยในช่วงปี 2000-2013 มีรายงานโรคนี้แล้วอย่างน้อย 100 ประเทศ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32315579","locator":"Section 3, Epidemiology","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"During the period of 2000-2013, the disease had been reported at least in 100 countries"}},{"id":"avian-medicine--avian-lt--ภาพรวมของโรค-overview--v2","statement":"ไก่ทุกช่วงอายุตั้งแต่ 8 วันจนถึง 4 ปี ติดเชื้อ ILTV ได้ แต่ไก่ที่อายุมากกว่า 3 สัปดาห์ถือว่ามีความไวต่อการติดเชื้อสูง ซึ่งสอดคล้องกับที่สไลด์ระบุว่าอาจพบโรคได้ตั้งแต่อายุ 3 สัปดาห์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32315579","locator":"Section 3, Epidemiology","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Birds of all ages starting from eight days to four years of age are susceptible to ILTV infection; however, birds over three weeks of age are reported to be highly susceptible"}}]},"avian-medicine--avian-lt--เชื้อสาเหตุ-etiology":{"claims":[{"id":"avian-medicine--avian-lt--เชื้อสาเหตุ-etiology--v1","statement":"เชื้อสาเหตุของ ILT คือ gallid alphaherpesvirus 1 ซึ่งเป็นชื่อปัจจุบันของไวรัสที่สไลด์เรียกว่า Gallid herpesvirus type 1 (GaHV-1)","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section A, Introduction","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Avian infectious laryngotracheitis (ILT) is a respiratory disease of chickens caused by gallid alphaherpesvirus 1."}},{"id":"avian-medicine--avian-lt--เชื้อสาเหตุ-etiology--v2","statement":"ILTV เป็นดีเอ็นเอไวรัสสายคู่ที่มีเปลือกหุ้มจริง จีโนมเป็น linear double-stranded DNA ขนาด 150-155 kb และ virion ประกอบด้วย DNA core ภายใน icosahedral capsid ที่ล้อมด้วยชั้น tegument และ envelope ที่มี glycoprotein อยู่ด้านนอก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32315579","locator":"Section 2.1, The virus","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The virions of ILTV under electron microscopy appear as typical herpes virions consisting of a DNA core within an icosahedral capsid which is surrounded by a tegument layer, and outer envelope glycoproteins"}}]},"avian-medicine--avian-lt--เซลล์เป้าหมาย-การติดต่อ-และระยะฟักตัว":{"claims":[{"id":"avian-medicine--avian-lt--เซลล์เป้าหมาย-การติดต่อ-และระยะฟักตัว--v1","statement":"เซลล์เป้าหมายคือ epithelial cells ที่บุกล่องเสียงและหลอดลม ซึ่งถูกทำลายเสมอในทุกราย ขณะที่ respiratory sinuses ถุงลม และเนื้อปอด อาจถูกทำลายหรือไม่ก็ได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32315579","locator":"Section 2.2, Viral replication","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Within respiratory system, the epithelial cells that lines larynx and trachea are always affected, while respiratory sinuses, air sacs and lung tissues may or may not be affected"}},{"id":"avian-medicine--avian-lt--เซลล์เป้าหมาย-การติดต่อ-และระยะฟักตัว--v2","statement":"ILTV สร้าง latency ใน trigeminal ganglion หลังการติดเชื้อเฉียบพลันประมาณ 7 วัน และถูกกระตุ้นให้กลับมาแบ่งตัวเมื่อไก่เครียด เช่น การเคลื่อนย้าย การเริ่มให้ไข่ และการรวมฝูง ตรงตามที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32315579","locator":"Section 3, Epidemiology","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"ILTV can establish latency in the trigeminal ganglion of the central nervous system after 7 days of acute infection. The virus gets reactivated under the stress conditions during shifting, onset of laying and mixing of flocks"}},{"id":"avian-medicine--avian-lt--เซลล์เป้าหมาย-การติดต่อ-และระยะฟักตัว--v3","statement":"ไก่ที่หายจากโรคเป็นพาหะได้จริง เชื้อคงอยู่แบบไม่แสดงอาการเป็นเวลานานและถูกขับออกมาเป็นระยะ ทำให้ไก่กลุ่มนี้เป็นแหล่งแพร่โรคที่สำคัญ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section A, Introduction","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"clinically inapparent infection can persist for long periods with intermittent re-excretion of the virus, and these recovered carrier birds are also a potential means of transmission of the disease"}}]},"avian-medicine--avian-lt--พยาธิกำเนิด-pathogenesis-และวงจรการแพร่เชื้อ":{"claims":[{"id":"avian-medicine--avian-lt--พยาธิกำเนิด-pathogenesis-และวงจรการแพร่เชื้อ--v1","statement":"ทางเข้าตามธรรมชาติของ ILTV คือทางระบบหายใจและทางตา โดยเชื้อเพิ่มจำนวนครั้งแรกที่ epithelium ของเยื่อบุตา respiratory sinuses กล่องเสียง และทางเดินหายใจส่วนต้น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32315579","locator":"Section 4, Pathogenesis","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The natural portal of entry of ILTV is respiratory and ocular routes. The initial replication takes place in the epithelium of the conjunctiva, respiratory sinuses, larynx and upper respiratory tract to a greater extent"}},{"id":"avian-medicine--avian-lt--พยาธิกำเนิด-pathogenesis-และวงจรการแพร่เชื้อ--v2","statement":"ไก่ที่ติดเชื้อขับเชื้อออกทาง respiratory secretions นานถึง 10 วันหลังติดเชื้อ และเชื้อเข้าสู่ตัวไก่ทางระบบหายใจ ทางตา และทางปากในสัดส่วนที่น้อยกว่า ตรงตามที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32315579","locator":"Section 2.6, Transmission","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Infected birds shed the virus in their respiratory secretions for 10 days post-infection. ILTV enters into the host through the respiratory tract, ocular and to a lesser extent through oral routes"}},{"id":"avian-medicine--avian-lt--พยาธิกำเนิด-pathogenesis-และวงจรการแพร่เชื้อ--v3","statement":"ไก่ที่กำลังติดเชื้อระยะเฉียบพลันแพร่เชื้อได้ง่ายกว่าไก่ที่หายจากโรคแล้วหรือไก่พาหะที่มีเชื้อแฝง สนับสนุนข้อความในสไลด์ที่ว่า direct transmission จากไก่ป่วยรุนแรงกว่าการแพร่จาก carrier","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32315579","locator":"Section 2.6, Transmission","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The infected birds readily transmit the disease through the oral secretion as compared to clinically recovered birds or latent carriers"}},{"id":"avian-medicine--avian-lt--พยาธิกำเนิด-pathogenesis-และวงจรการแพร่เชื้อ--v4","statement":"การแพร่เชื้อเข้าฝูงเกิดได้ทั้งจากการสัมผัสสารคัดหลั่งทางเดินหายใจโดยตรง และจากการแพร่แบบ indirect หรือ mechanical ผ่านอุปกรณ์ สิ่งปูรอง กระสอบอาหาร ขนไก่ ยานพาหนะ ฝุ่น รองเท้า เสื้อผ้า และการเคลื่อนย้ายของคน ตรงตามรายการในสไลด์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32315579","locator":"Section 2.6, Transmission","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The virus usually gets introduced into a flock by direct contact with respiratory exudates or indirect/mechanical transmission of contaminated equipment, litter, feed bags, feathers, vehicles, dust, footwear, clothes, and movement of people"}}]},"avian-medicine--avian-lt--อาการ-clinical-signs":{"claims":[{"id":"avian-medicine--avian-lt--อาการ-clinical-signs--v1","statement":"รูปแบบ severe epizootic ของ ILT มีอัตราการป่วย (morbidity) สูง 90-100% ตรงตามที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32315579","locator":"Section 3, Epidemiology","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The severe epizootic form is characterized by a rapid spread with a high morbidity (90-100%)"}},{"id":"avian-medicine--avian-lt--อาการ-clinical-signs--v2","statement":"ในรูปแบบ acute พบเยื่อบุตาอักเสบเป็นหนองร่วมกับ frothy exudate ที่หัวตาด้านใน ร่วมกับ sinusitis และน้ำมูกไหล ตรงกับที่สไลด์ระบุว่า conjunctivitis with frothy ocular secretion","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32315579","locator":"Section 5.1.2, Acute form","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The affected birds may also show purulent conjunctivitis with frothy exudates in the inner canthus of the eye, sinusitis and nasal discharge"}},{"id":"avian-medicine--avian-lt--อาการ-clinical-signs--v3","statement":"อาการบวมของ infraorbital sinus (almond-shaped eyes) ร่วมกับไข่ลดได้ถึง 10% และน้ำหนักตัวลด เป็นลักษณะของ ILT รูปแบบ chronic หรือ mild ไม่ใช่รูปแบบเฉียบพลันรุนแรง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32315579","locator":"Section 5.1.3, Chronic form","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"swelling of the infraorbital sinuses (almond-shaped eyes), drop in egg production (up to 10%), and reduced body weight"}}]},"avian-medicine--avian-lt--รอยโรค-lesions":{"claims":[{"id":"avian-medicine--avian-lt--รอยโรค-lesions--v1","statement":"รอยโรคหลังการตายจำกัดอยู่ที่ทางเดินหายใจส่วนต้น ประกอบด้วย haemorrhagic tracheitis ที่มีลิ่มเลือด mucoid rhinitis และเมือกปนเลือดตลอดความยาวของหลอดลม สอดคล้องกับรอยโรคระยะท้ายที่สไลด์ระบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section A, Introduction (peracute form)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Post-mortem changes are confined to the upper respiratory tract and are also characteristic, consisting of haemorrhagic tracheitis with blood clots, mucoid rhinitis, and blood-stained mucus along the length of the trachea."}},{"id":"avian-medicine--avian-lt--รอยโรค-lesions--v2","statement":"แผ่น diphtheritic สีเหลืองลักษณะ caseous เกาะติดกับกล่องเสียงและเยื่อบุหลอดลมส่วนต้น เป็นรอยโรคของ ILT รูปแบบ subacute ตรงตามที่สไลด์ระบุว่าพบ diphtheritic ในหลอดลม","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section A, Introduction (subacute form)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Yellow caseous diphtheritic membranes may be found adherent to the larynx and upper tracheal mucosa."}},{"id":"avian-medicine--avian-lt--รอยโรค-lesions--v3","statement":"แผ่นเยื่อที่เกิดขึ้นสามารถกลายเป็น obstructive plug อุดกั้นบริเวณกล่องเสียงและ syrinx ทำให้ไก่ขาดอากาศหายใจและตาย ยืนยันกลไกที่สไลด์อธิบายว่า mucoid plug อุดทางเดินหายใจ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32315579","locator":"Section 5.2, Gross lesions","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The membrane also forms obstructive plugs in the larynx and syrinx regions leading to suffocation and death."}}]},"avian-medicine--avian-lt--การวินิจฉัย-diagnosis":{"claims":[{"id":"avian-medicine--avian-lt--การวินิจฉัย-diagnosis--v1","statement":"PCR มีความไวสูงกว่าการแยกเชื้อ (virus isolation) สำหรับตรวจตัวอย่างทางคลินิก และปัจจุบันใช้กันแพร่หลาย โดย histopathology ร่วมกับ real-time PCR เป็นคู่ทดสอบเร็วที่ใช้บ่อยที่สุดในการตรวจ ILTV","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Summary, Detection of the agent","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Polymerase chain reaction (PCR) methodology has been shown to be more sensitive than virus isolation for the examination of clinical material and is now widely used."}},{"id":"avian-medicine--avian-lt--การวินิจฉัย-diagnosis--v2","statement":"ELISA เป็นวิธีที่เลือกใช้ (method of choice) สำหรับตรวจแอนติบอดีต่อ ILTV ในซีรั่มไก่ และเหมาะกับการคัดกรองระดับฝูง ส่วน AGID และ indirect immunofluorescence แทบไม่ใช้แล้วในปัจจุบัน","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section B.2, Serological tests","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The method of choice for detection of antibodies to ILTV in chicken serum is ELISA. Virus neutralisation (VN) can also be used. AGID and indirect immunofluorescence tests are little used nowadays."}},{"id":"avian-medicine--avian-lt--การวินิจฉัย-diagnosis--v3","statement":"ต้องวินิจฉัยแยก ILT จากโรคระบบหายใจอื่นโดยเฉพาะ Newcastle disease ซึ่งทำให้เกิด tracheitis รุนแรงได้เช่นกัน และต้องแยกรอยโรค diphtheritic ในช่องปากออกจาก fowlpox รูปแบบ wet form ตรงกับรายการวินิจฉัยแยกในสไลด์","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section A, Introduction","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Differential diagnosis of ILT from other respiratory diseases, especially Newcastle disease, which may also cause severe tracheitis, is important. Also, diphtheritic oral lesions should be differentiated from the wet form of fowlpox."}}]},"avian-medicine--avian-lt--การควบคุมและป้องกันโรค-ภาพรวม":{"claims":[{"id":"avian-medicine--avian-lt--การควบคุมและป้องกันโรค-ภาพรวม--v1","statement":"การควบคุม ILT ในทางปฏิบัติอาศัยสองเสาหลักคือ biosecurity ที่ดีร่วมกับการทำวัคซีน ตรงตามที่สไลด์แบ่งไว้ และเหตุผลสำคัญคือ ILT ไม่มีการรักษาที่ได้ผล","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32315579","locator":"Section 8, Vaccination","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Good biosecurity practices combined with vaccination are the practical methods to control ILTV in the absence of any effective treatment."}}]},"avian-medicine--avian-lt--วัคซีนเชื้อเป็น-ceo-และ-tco":{"claims":[{"id":"avian-medicine--avian-lt--วัคซีนเชื้อเป็น-ceo-และ-tco--v1","statement":"วัคซีน CEO ให้ประสิทธิภาพในการป้องกันโรคดีกว่าวัคซีน TCO ตรงตามที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32315579","locator":"Section 8, Vaccination","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The protective efficacy of CEO vaccines is better when compared to TCO vaccines"}},{"id":"avian-medicine--avian-lt--วัคซีนเชื้อเป็น-ceo-และ-tco--v2","statement":"ในโปรแกรมวัคซีนของไก่อายุยืน วัคซีนเชื้อเป็น CEO ให้ทางน้ำดื่ม ส่วน TCO ให้โดยการหยอดตา สนับสนุนการแบ่ง route ตามที่สไลด์ระบุว่า TCO ให้แบบ eye drop เท่านั้น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-37556293","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"live attenuated vaccines administered via drinking water (chicken embryo origin [CEO]) or eye drop (tissue culture origin [TCO])"}},{"id":"avian-medicine--avian-lt--วัคซีนเชื้อเป็น-ceo-และ-tco--v3","statement":"โปรแกรมป้องกันมาตรฐานให้วัคซีน ILT เข็มแรกที่อายุ 6-8 สัปดาห์ แล้วกระตุ้นซ้ำที่ 12-15 สัปดาห์ในไก่ไข่และไก่พันธุ์ ซึ่งอยู่ในกรอบเดียวกับช่วงอายุที่สไลด์ระบุ และยืนยันว่าการทำวัคซีนนี้มุ่งไปที่ไก่ไข่และไก่พันธุ์เป็นหลัก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32315579","locator":"Section 8, Vaccination","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Preventive vaccination of ILTV is given at 6 to 8 weeks of age, followed by the booster at 12 to 15 weeks for layers and breeders"}}]},"avian-medicine--avian-lt--ข้อควรระวังในการใช้วัคซีนเชื้อเป็น":{"claims":[{"id":"avian-medicine--avian-lt--ข้อควรระวังในการใช้วัคซีนเชื้อเป็น--v1","statement":"วัคซีนเชื้อเป็น ILT มีความรุนแรงตกค้าง (residual virulence) ที่ก่อให้เกิดอาการป่วยได้จริง โดยความเสี่ยงสูงเป็นพิเศษเมื่อให้ด้วยวิธีพ่นละออง จุดที่ต้องระวังคือขนาดละอองที่เล็กเกินไปแล้วถูกสูดลงลึก ซึ่งเป็นเหตุผลที่การพ่นแบบ coarse spray ใช้ละอองหยาบเพื่อลดปัญหานี้","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section C.1, Background","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"live attenuated ILT vaccines may have residual virulence that can cause clinical disease, especially if administered by spray and a small droplet size is produced and inhaled"}},{"id":"avian-medicine--avian-lt--ข้อควรระวังในการใช้วัคซีนเชื้อเป็น--v2","statement":"วัคซีนเชื้อเป็น ILT กลับมามีความรุนแรงสูงขึ้นได้เมื่อผ่านจากไก่ตัวหนึ่งไปยังอีกตัวหนึ่ง และคงอยู่ในฟาร์มได้ อีกทั้งไก่ที่ทำวัคซีนแล้วติดเชื้อผสมแบบไม่แสดงอาการสามารถทำให้ไก่ที่ไม่ได้ทำวัคซีนซึ่งอยู่ร่วมฝูงป่วยรุนแรงได้ สนับสนุนกลไก rolling infection เมื่อทำวัคซีนไม่ทั่วทั้งฝูง","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section C.1, Background","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Live attenuated ILT vaccines may also revert to higher levels of virulence following bird-to-bird passage and persist in the field. Subclinical mixed infections of vaccine and field virus, in vaccinated birds, can cause severe disease in un"}}]},"avian-medicine--avian-lt--recombinant-vaccine-virus-vector-vaccine":{"claims":[{"id":"avian-medicine--avian-lt--recombinant-vaccine-virus-vector-vaccine--v1","statement":"วัคซีน recombinant ที่ใช้ fowlpox virus เป็น vector แสดงออก glycoprotein B และยีน UL32 ของ ILTV ตรงตามที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32315579","locator":"Section 8, Vaccination","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"recombinant vaccines such as FPV vector vaccine expressing glycoprotein B and UL32 genes of ILTV"}},{"id":"avian-medicine--avian-lt--recombinant-vaccine-virus-vector-vaccine--v2","statement":"วัคซีน recombinant ให้ได้สามทางคือ wing-web puncture, ฉีดใต้ผิวหนัง และ in ovo ตรงตามเส้นทางการให้ที่สไลด์ระบุสำหรับ FPV-ILT และ HVT-ILT","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section C.1, Background","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Recombinant vaccines may be delivered by wing-web puncture, subcutaneous injection or in-ovo inoculation."}}]},"avian-medicine--avian-lt--ตัวอย่างโปรแกรมวัคซีน-ไก่พันธุ์":{"claims":[{"id":"avian-medicine--avian-lt--ตัวอย่างโปรแกรมวัคซีน-ไก่พันธุ์--v1","statement":"โปรแกรมวัคซีน ILT ของไก่อายุยืน ซึ่งรวมไก่พันธุ์เนื้อและไก่ไข่การค้า ใช้ได้ทั้ง HVT recombinant vector vaccine ที่โรงฟัก หรือวัคซีนเชื้อเป็น CEO ทางน้ำดื่ม หรือ TCO โดยการหยอดตา ตรงกับกรอบโปรแกรมที่สไลด์ยกตัวอย่าง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-37556293","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"vaccination programs of long-lived birds (broiler breeders and commercial layers) against ILT include immunizations with either HVT recombinant vector vaccines, or at hatch, or live attenuated vaccines administered via drinking water (chick"}}]},"avian-medicine--avian-lt--ตัวอย่างโปรแกรมวัคซีน-ไก่ไข่":{"claims":[{"id":"avian-medicine--avian-lt--ตัวอย่างโปรแกรมวัคซีน-ไก่ไข่--v1","statement":"การให้วัคซีน rHVT-LT ที่โรงฟักแล้วตามด้วยวัคซีนเชื้อเป็น CEO ทางน้ำดื่มหรือหยอดตาในภายหลัง ให้ความคุ้มโรคที่แข็งแรงกว่าการให้ rHVT-LT เพียงอย่างเดียว สนับสนุนโปรแกรมไก่ไข่ที่สไลด์เสนอคือ recombinant ที่ 1 วัน แล้วตามด้วย CEO หรือ TCO","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-37556293","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The efficacy of bivalent rHVT-LT at hatch followed by drinking water or eye-drop CEO vaccination has been shown to provide more robust protection than rHVT-LT alone."}}]},"avian-medicine--avian-lt--ตัวอย่างโปรแกรมวัคซีน-ไก่เนื้อ":{"claims":[{"id":"avian-medicine--avian-lt--ตัวอย่างโปรแกรมวัคซีน-ไก่เนื้อ--v1","statement":"เหตุผลที่ไก่เนื้อเลือกใช้ recombinant vector vaccine เป็นหลักคือวัคซีนเชื้อเป็นโดยเฉพาะ CEO มีความรุนแรงตกค้างในตัวเอง การใช้ viral vector recombinant vaccine จึงขยายตัวไปทั่วโลกในฐานะกลยุทธ์ที่ปลอดภัยกว่า ตรงกับที่สไลด์ระบุว่าให้เพื่อลดความเสี่ยงในการแพ้วัคซีน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-31251537","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Due to the inherent virulence of live attenuated vaccines, in particular that of the chicken embryo origin (CEO) vaccines, the use of ILT viral vector recombinant vaccines has significantly expanded worldwide as a safer vaccination strategy"}}]},"avian-medicine--avian-lt--ข้อสรุปเรื่องวัคซีน-และการให้วัคซีนตอนเกิดการระบาด":{"claims":[{"id":"avian-medicine--avian-lt--ข้อสรุปเรื่องวัคซีน-และการให้วัคซีนตอนเกิดการระบาด--v1","statement":"ในไก่เนื้อ วัคซีน rHVT-LT ลดอาการทางคลินิก รักษาน้ำหนักตัวหลัง challenge และลดการเพิ่มจำนวนของเชื้อในหลอดลมได้ 52-65% แต่ไม่สามารถป้องกันการแพร่เชื้อไปยังไก่ naive ที่เลี้ยงร่วมกันได้ ตรงตามข้อสรุปในสไลด์ที่ว่าวัคซีน recombinant ลดอาการป่วยและการตายได้ แต่ลดการแพร่เชื้อได้ไม่เท่า CEO","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-31251537","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"vaccinated chickens showed reduction in clinical signs, maintained body weight gain after challenge, and lessened the challenge virus replication in the trachea at a rate of 52%-65%. However, in spite of this reduction, transmission of chal"}},{"id":"avian-medicine--avian-lt--ข้อสรุปเรื่องวัคซีน-และการให้วัคซีนตอนเกิดการระบาด--v2","statement":"การให้วัคซีนขณะเกิดการระบาด (therapeutic vaccination) ช่วยลดการแพร่กระจายของเชื้อและย่นระยะเวลาของการระบาดลงได้จริง ตรงตามที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32315579","locator":"Section 9, Control and eradication","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the virus spread and length of an outbreak can be reduced by therapeutic vaccination"}}]},"avian-medicine--avian-lt--biosecurity-และการจัดการ":{"claims":[{"id":"avian-medicine--avian-lt--biosecurity-และการจัดการ--v1","statement":"การเลี้ยงไก่หลายอายุในพื้นที่เดียวกัน ความหนาแน่นของฝูงที่สูง และรอบการผลิตที่สั้นลง เป็นปัจจัยที่ทำให้การระบาดของ ILT เพิ่มขึ้นทั่วโลก สนับสนุนคำแนะนำในสไลด์ให้เลี้ยงไก่อายุเดียวกันแบบ all in all out","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32315579","locator":"Section 3, Epidemiology","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The trend toward high flock density, shorter production cycles, raising of multi-age and multipurpose chicken within same geographical area, and improper vaccination and breach in the biosecurity have contributed to the increased ILT outbre"}},{"id":"avian-medicine--avian-lt--biosecurity-และการจัดการ--v2","statement":"ต้องทำความสะอาดและฆ่าเชื้อโรงเรือนอย่างเหมาะสม และยืดระยะพักเล้า (downtime) ระหว่างรุ่นการเลี้ยงให้นานขึ้น ตรงตามที่สไลด์แนะนำ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32315579","locator":"Section 9, Control and eradication","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Proper cleaning and disinfection of poultry houses should be carried out and the downtime should be extended between subsequent batches."}},{"id":"avian-medicine--avian-lt--biosecurity-และการจัดการ--v3","statement":"ILTV อยู่รอดใน deep litter ได้ 3-20 วันที่อุณหภูมิ 11-24.5 องศาเซลเซียส และอยู่ในซากที่ฝังกลบได้อย่างน้อย 3 สัปดาห์ อธิบายว่าทำไมความสะอาดของพื้นและสิ่งปูรองจึงสำคัญตามที่สไลด์เน้น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32315579","locator":"Section 2.4, Physico-chemical properties","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In deep litter, the ILTV survives for 3-20 days at 11-24.5 C, in the droppings of battery cages for 3 days at 11-19.5 C and at least for 3 weeks in buried carcasses."}},{"id":"avian-medicine--avian-lt--biosecurity-และการจัดการ--v4","statement":"ILTV คงอยู่ใน biofilm ของท่อและรางน้ำดื่มแล้วแพร่ไปยังไก่ที่ไวรับได้ สนับสนุนที่สไลด์ให้ความสำคัญกับความสะอาดของรางน้ำ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32315579","locator":"Section 2.6, Transmission","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Recent studies demonstrated that ILTV can persist in the biofilm of drinking water lines and spread to susceptible birds"}}]},"avian-medicine--avian-lt--เชื้อ-โฮสต์-และการติดต่อ":{"claims":[{"id":"avian-medicine--avian-lt--เชื้อ-โฮสต์-และการติดต่อ--v1","statement":"Trigeminal ganglion (TRG) คือตำแหน่งหลักของการแฝงตัว (latency) ของ ILTV และไก่ที่เป็นพาหะแบบแฝงหรือถูกกระตุ้นให้เชื้อกลับมา เป็นแหล่งแพร่เชื้อสำคัญ โดยปัจจัยกระตุ้นได้แก่ การทำวัคซีน การเริ่มให้ไข่ และการย้ายฝูง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-39861016","locator":"Section 3, The Clinical Manifestations of ILTV and aMPV","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The trigeminal ganglion (TRG) is identified as the primary site for viral latency during the lytic phase of ILTV infection... More problematically, latent or reactivated ILTV carriers are also well-known transmission sources"}}]},"avian-medicine--avian-lt--วัคซีน-ceo-กับ-tco-และ-recombinant":{"claims":[{"id":"avian-medicine--avian-lt--วัคซีน-ceo-กับ-tco-และ-recombinant--v1","statement":"วิธีให้วัคซีนตรงกับที่เอกสารบรรยายระบุ คือวัคซีน chicken embryo origin (CEO) ให้ได้ทางน้ำดื่ม coarse spray และหยอดตา ส่วนวัคซีน tissue culture origin (TCO) ให้ทางหยอดตาเท่านั้น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-39861016","locator":"Section 5, Vaccine Development for ILTV and aMPV","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Administration methods for CEO vaccines include drinking water, coarse spray, and eye drops, while TCO vaccines are administered explicitly via eye drops."}},{"id":"avian-medicine--avian-lt--วัคซีน-ceo-กับ-tco-และ-recombinant--v2","statement":"CEO ให้การป้องกันดีกว่า TCO จริง แต่ CEO ก็มี residual virulence ที่อาจรุนแรงขึ้นเมื่อผ่านตัวไก่ต่อ ๆ กัน จนแพร่จากไก่ที่ทำวัคซีนไปยังไก่ที่ยังไม่ได้ทำและกลับมามีความรุนแรง ซึ่งเป็นกลไกของ rolling infection ที่เอกสารบรรยายเตือนไว้ ขณะที่การระบาดจากสายพันธุ์ TCO พบได้น้อยกว่ามาก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-39861016","locator":"Section 5, Vaccine Development for ILTV and aMPV","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"This residual virulence may even escalate through animal passage, posing a risk of transmission from vaccinated to unvaccinated birds and the possibility of reverting to more virulent forms after multiple passages within a flock... Converse"}},{"id":"avian-medicine--avian-lt--วัคซีน-ceo-กับ-tco-และ-recombinant--v3","statement":"วัคซีน recombinant ที่ใช้ fowlpox virus (FPV) และ turkey herpesvirus (HVT) เป็น vector ถูกพัฒนาขึ้นเพื่อตอบสนองต่อการระบาดจากสายพันธุ์ที่มาจากวัคซีน CEO ข้อดีคือแพร่ในฝูงไม่ได้และเสี่ยงกลับมามีความรุนแรงต่ำ แต่โดยรวมยังด้อยกว่า CEO และ TCO ในการลดการปล่อยเชื้อ ตรงกับที่เอกสารบรรยายระบุว่าไม่ดีเท่า CEO","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-39861016","locator":"Section 5, Vaccine Development for ILTV and aMPV","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"While these viral vector vaccines have shown efficacy in reducing the clinical signs of infection, they are generally less effective than traditional live attenuated CEO/TCO vaccines in minimizing virus shedding."}}]},"avian-medicine--avian-lt--อาการและรอยโรค":{"claims":[{"id":"avian-medicine--avian-lt--อาการและรอยโรค--v1","statement":"การทบทวนเคส ILT ที่ยืนยันแล้ว 31 submission (ไก่ 246 ตัว) พบรอยโรคมหภาคในทางเดินหายใจเรียงจากเมือกเพิ่มขึ้น 55.6% ไปจนถึง fibrinonecrotic exudate 20.3% และเลือดออกที่กล่องเสียงกับหลอดลม 13.0% สนับสนุนลำดับรอยโรคที่สรุประบุว่าระยะแรกเป็น mucoid tracheitis แล้วระยะหลังจึงมี hemorrhage และ necrosis โดยเลือดออกอยู่ที่ larynx และหลอดลมส่วนต้น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34463177","locator":"เล่ม 59 ฉบับ 1 หน้า 112-119, Abstract ส่วนผลการตรวจ","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Macroscopic findings in the respiratory tract varied from increased mucus (55.6%) to fibrinonecrotic exudate (20.3%) and hemorrhages in the larynx and trachea (13.0%)."}},{"id":"avian-medicine--avian-lt--อาการและรอยโรค--v2","statement":"รอยโรคทางจุลพยาธิที่จำเพาะของ ILT คือ syncytia ที่มี intranuclear inclusion body ในเซลล์เยื่อบุทางเดินหายใจ โดยจะพบร่วมกับเลือดออกหรือไม่ก็ได้ และในกรณีที่อ่านจุลพยาธิแล้วยังไม่ชัด immunohistochemistry ช่วยยืนยันได้ (พบ antigen บวกใน 8 จาก 34 ชิ้นเนื้อที่มองไม่เห็น syncytia หรือ inclusion body)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34463177","locator":"เล่ม 59 ฉบับ 1 หน้า 112-119, Abstract ส่วนจุลพยาธิและ IHC","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Syncytia with intranuclear inclusion bodies were present in the respiratory tract epithelium with or without hemorrhages. ... Of the 34 tissues with no visible syncytia or inclusion bodies, 8 were positive by IHC."}},{"id":"avian-medicine--avian-lt--อาการและรอยโรค--v3","statement":"รายงานการแยกเชื้อ ILTV จากไก่เนื้อในอิหร่านยืนยันว่า inclusion body ของ ILT ติดสีชมพู (eosinophilic) และอยู่ในนิวเคลียส พบร่วมกับการเกิด syncytial cell ในเนื้อเยื่อหลอดลม และพบเยื่อ diphtheritic แบบ caseous ติดแน่นที่กล่องเสียงและหลอดลมตอนผ่าซาก ตรงกับที่สรุประบุว่าเป็น eosinophilic intranuclear inclusion body และมี diphtheritic in trachea","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34345396","locator":"เล่ม 12 ฉบับ 2 หน้า 259-262, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"At necropsy, caseous diphtheritic membrane adherent to the larynx and trachea was observed. Microscopically, syncytial cells formation with dense eosinophilic intranuclear inclusion bodies were main histopathological findings in tracheal ti"}}]}},"avian-medicine--avian-mpv":{"avian-medicine--avian-mpv--โรคหัวบวมคืออะไร-ภาพรวม":{"claims":[{"id":"avian-medicine--avian-mpv--โรคหัวบวมคืออะไร-ภาพรวม--v1","statement":"aMPV ทำให้เกิด acute highly contagious upper respiratory tract infection ที่บางครั้งมาพร้อม reproductive disorder โดยเกิดหลักในไก่งวง ไก่ และเป็ด เรียกว่า turkey rhinotracheitis (TRT) ในไก่งวง และเป็นเชื้อกระตุ้นของ swollen head syndrome (SHS) ในไก่","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2022","locator":"Summary, page 1","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Avian metapneumovirus (aMPV) principally causes an acute highly contagious upper respiratory tract infection sometimes combined with reproductive disorders, primarily of turkeys, chickens and ducks."}},{"id":"avian-medicine--avian-mpv--โรคหัวบวมคืออะไร-ภาพรวม--v2","statement":"นกธรรมชาติเกี่ยวข้องกับการแพร่ของเชื้อจริง มีการแยกเชื้อ APV ได้จากนกน้ำ sentinel ที่วางไว้ใกล้ฟาร์มไก่งวงที่ติดเชื้อ และจาก wild Canada geese ที่จับได้ในรัฐ Minnesota","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12665110","locator":"Abstract; Anim Health Res Rev 3(2):107-17","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Infectious APV was isolated from sentinel waterfowls placed close to an infected commercial turkey farm and from wild Canada geese captured in Minnesota, suggesting that free-ranging birds may be involved in the spread of APV."}}]},"avian-medicine--avian-mpv--ประวัติช่วงแรกของโรคหัวบวม":{"claims":[{"id":"avian-medicine--avian-mpv--ประวัติช่วงแรกของโรคหัวบวม--v1","statement":"การแยกเชื้อ aMPV ครั้งแรกเกิดขึ้นที่ประเทศแอฟริกาใต้ในช่วงปลายทศวรรษ 1970 โดยทำใน embryonated eggs","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2022","locator":"Section B.1.2 Culture and Identification, page 5","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The original isolation of aMPV in South Africa in the late 1970s and the more recent Colorado aMPV were carried out in embryonated eggs, however subgroup A and B aMPV isolations have routinely been made in tracheal organ cultures."}},{"id":"avian-medicine--avian-mpv--ประวัติช่วงแรกของโรคหัวบวม--v2","statement":"การแบ่ง avian pneumovirus ออกเป็น 2 subgroups ได้รับการยืนยันในปี 1994 จากการวิเคราะห์ลำดับนิวคลีโอไทด์ของยีน attachment (G) protein โดยกลุ่ม UK และฝรั่งเศสเป็นกลุ่มหนึ่ง ส่วนสเปน อิตาลี และฮังการีเป็นอีกกลุ่มหนึ่ง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-7964599","locator":"Abstract; J Gen Virol 75(Pt 11):2873-80","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The nucleotide sequences and the predicted amino acid sequences indicate that there are at least two distinct subgroups, similar to the grouping described for human respiratory syncytial (RS) virus. The U.K. and French isolates form one gro"}},{"id":"avian-medicine--avian-mpv--ประวัติช่วงแรกของโรคหัวบวม--v3","statement":"AMPV subtype C ถูกแยกได้ครั้งแรกในรัฐ Colorado สหรัฐอเมริกา ปี 1996 จากฟาร์มไก่งวงเชิงพาณิชย์ แล้วแพร่ต่อไปยังรัฐอื่นรวมทั้ง Minnesota, North Dakota, South Dakota, Iowa และ Wisconsin","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35458407","locator":"Section on AMPV subgroup C; Viruses 14(4):677","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"A novel subtype AMPV-C was isolated in the state of Colorado in the United States in 1996. This virus was found on a commercial turkey farm and although it appeared to be quickly eradicated in Colorado, it soon spread to many other states i"}}]},"avian-medicine--avian-mpv--เชื้อสาเหตุและการจัดจำแนก-classification":{"claims":[{"id":"avian-medicine--avian-mpv--เชื้อสาเหตุและการจัดจำแนก-classification--v1","statement":"aMPV เป็น single-stranded non-segmented negative-sense RNA virus ที่มีเปลือกหุ้ม จัดอยู่ใน family Pneumoviridae genus Metapneumovirus โดยจีโนมยาวประมาณ 14 กิโลเบส บรรจุใน nucleocapsid แบบ helical symmetry","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2022","locator":"Summary page 1 and Section A. Introduction page 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"aMPV is a single-stranded non-segmented negative-sense RNA virus belonging to the family Pneumoviridae, genus Metapneumovirus."}},{"id":"avian-medicine--avian-mpv--เชื้อสาเหตุและการจัดจำแนก-classification--v2","statement":"อนุภาคไวรัสเป็น pleomorphic spherical มีเปลือกหุ้ม ขนาดตั้งแต่ 50 nm ถึง 200 nm โดยทั่วไปประมาณ 150 nm ตรงกับตัวเลขที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-39861016","locator":"Section on aMPV general properties; Pathogens 14(1):55","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"sizes ranging from 50 nm to 200 nm, typically around 150 nm in diameter"}},{"id":"avian-medicine--avian-mpv--เชื้อสาเหตุและการจัดจำแนก-classification--v3","statement":"จีโนมของ metapneumovirus มี 8 ยีนเรียงลำดับ 3'-N-P-M-F-M2-SH-G-L และไม่มียีน non-structural NS1 และ NS2 ต่างจาก mammalian pneumovirus ซึ่งสอดคล้องกับโปรตีน N, P, M, F, SH, G และ L ที่แสดงในรูปสไลด์","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2022","locator":"Section A. Introduction, page 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Avian and human metapneumoviruses have no non-structural NS1 and NS2 proteins and their gene order (3'-N-P-M-F-M2-SH-G-L-5') is different from that of mammalian pneumoviruses (3'-NS1-NS2-N-P-M-SH-G-F-M2-L-5')"}}]},"avian-medicine--avian-mpv--subtypes-ของ-ampv":{"claims":[{"id":"avian-medicine--avian-mpv--subtypes-ของ-ampv--v1","statement":"aMPV แบ่งได้เป็น 4 subgroups คือ A, B, C และ D โดยจำแนกด้วย monoclonal antibody neutralisation, ELISA และการวิเคราะห์ลำดับนิวคลีโอไทด์ของยีน G และมีข้อมูลลำดับพันธุกรรมล่าสุดชี้ว่าอาจมี subgroup เพิ่มเติมในนกนางนวลและนกแก้ว","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2022","locator":"Summary, page 1","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Four antigenically distinct subgroups, A, B, C and D, of aMPV have been identified by neutralisation with monoclonal antibodies, possible limited cross reactivity in enzyme-linked immunosorbent assay (ELISA), and sequence analysis of the at"}},{"id":"avian-medicine--avian-mpv--subtypes-ของ-ampv--v2","statement":"subgroup D ถูกระบุจากการทำ retrospective molecular analysis ของไวรัสที่แยกได้จากไก่งวงในประเทศฝรั่งเศสช่วงทศวรรษ 1980 ตรงกับที่สไลด์ระบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2022","locator":"Section A. Introduction, page 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Retrospective molecular analysis of viruses isolated in the 1980s from turkeys in France indicates the presence of a fourth subgroup of aMPV designated subgroup D."}}]},"avian-medicine--avian-mpv--เซลล์เป้าหมาย-การติดต่อ-และระยะฟักตัว":{"claims":[{"id":"avian-medicine--avian-mpv--เซลล์เป้าหมาย-การติดต่อ-และระยะฟักตัว--v1","statement":"การแพร่เชื้อจากตัวสู่ตัวต้องอาศัย direct contact ตามผลการศึกษาเชิงทดลอง และในสภาพฟาร์มเชิงพาณิชย์การติดเชื้อทาง aerogenous จาก airborne transmission ก็มีโอกาสเกิดได้เนื่องจากโรคจำกัดอยู่ที่ระบบหายใจ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2022","locator":"Section A. Introduction, page 3","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Other experimental studies suggest that direct contact is necessary for bird-to-bird spread of the disease (Alkhalaf et al., 2002). In commercial conditions aerogenous infection following airborne transmission is also likely as the disease "}},{"id":"avian-medicine--avian-mpv--เซลล์เป้าหมาย-การติดต่อ-และระยะฟักตัว--v2","statement":"ระยะฟักตัวของ aMPV ที่รายงานในวารสารคือ 3 ถึง 7 วัน ซึ่งครอบคลุมช่วง 3 ถึง 5 วันที่สไลด์ระบุ แต่กว้างกว่า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-39861016","locator":"Section on aMPV clinical disease; Pathogens 14(1):55","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"incubation period of 3–7 days"}},{"id":"avian-medicine--avian-mpv--เซลล์เป้าหมาย-การติดต่อ-และระยะฟักตัว--v3","statement":"ในกรณีที่ไม่มีการติดเชื้อแทรกซ้อน สัตว์จะฟื้นตัวเร็วและกลับมาปกติภายในประมาณ 14 วัน สอดคล้องกับ recovery within 10 ถึง 14 วันที่สไลด์ระบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2022","locator":"Section A. Introduction, page 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In an uncomplicated infection, recovery is rapid and the birds appear normal in approximately 14 days."}}]},"avian-medicine--avian-mpv--พยาธิกำเนิดในทางเดินหายใจ-respiratory-tract":{"claims":[{"id":"avian-medicine--avian-mpv--พยาธิกำเนิดในทางเดินหายใจ-respiratory-tract--v1","statement":"ในไก่งวงระยะเจริญเติบโต การเพิ่มจำนวนของไวรัสจำกัดอยู่ที่ upper respiratory tract โดยมี viraemia สั้น ๆ และเกิด serous rhinitis ที่ turbinates พร้อม epithelial exfoliation และ focal loss of cilia ตั้งแต่ 2 วันหลังติดเชื้อ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2022","locator":"Section A. Introduction, page 3","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Sequential histopathological and immunocytochemical studies have shown viral replication in the turbinates causing a serous rhinitis with increased glandular activity, epithelial exfoliation, focal loss of cilia, hyperaemia and mild mononuc"}},{"id":"avian-medicine--avian-mpv--พยาธิกำเนิดในทางเดินหายใจ-respiratory-tract--v2","statement":"การศึกษาเชิงทดลองในไก่งวงเก็บตัวอย่างจาก nasal turbinates, trachea, conjunctiva, Harderian gland, infraorbital sinus และ lungs โดยพบรอยโรค multifocal loss of cilia เด่นชัดที่ nasal turbinate ระหว่างวันที่ 3 ถึง 11 หลังการให้เชื้อ ยืนยันว่าพบเชื้อได้ในอวัยวะที่สไลด์ระบุรวมถึง Harderian gland","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16404993","locator":"Abstract; Avian Dis 49(4):520-6","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Samples from nasal turbinates, trachea, conjunctiva, Harderian gland, infraorbital sinus, lungs, liver, and spleen were collected at 1, 3, 5, 7, 9, 11, and 14 days PI. Histopathologic lesions such as a multifocal loss of cilia were prominen"}}]},"avian-medicine--avian-mpv--อาการทางคลินิก-clinical-signs":{"claims":[{"id":"avian-medicine--avian-mpv--อาการทางคลินิก-clinical-signs--v1","statement":"ในไก่ mortality โดยทั่วไปไม่เกิน 1 ถึง 2% และ morbidity อาจถึง 10% แม้ว่าฝูงทั้งฝูงอาจได้รับผลกระทบถึง 100% ซึ่งสอดคล้องกับตัวเลข morbidity 4 ถึง 10% และ mortality 0.4 ถึง 2% ในสไลด์","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2022","locator":"Section A. Introduction, page 3","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Although mortality does not usually exceed 1–2%, morbidity may reach 10%, although 100% of the flock may be affected."}},{"id":"avian-medicine--avian-mpv--อาการทางคลินิก-clinical-signs--v2","statement":"อาการของ aMPV ประกอบด้วย snicking, rales, sneezing, nasal discharge, foaming conjunctivitis, swelling ของ infraorbital sinuses และ submandibular oedema ตรงกับรายการอาการในสไลด์","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2022","locator":"Section A. Introduction, page 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Infection with aMPV can occur from a very young age in turkeys and is characterised by snicking, rales, sneezing, nasal discharge, foaming conjunctivitis, swelling of the infraorbital sinuses and submandibular oedema (Pringle, 1998)."}},{"id":"avian-medicine--avian-mpv--อาการทางคลินิก-clinical-signs--v3","statement":"ใน swollen head syndrome ของไก่ อาการบวมของ infraorbital sinuses และ periorbital กับใบหน้ามักตามมาด้วย cerebral disorientation, torticollis และ opisthotonos","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2022","locator":"Section A. Introduction, page 3","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The syndrome is characterised by respiratory disease, apathy, swelling of infraorbital sinuses and unilateral or bilateral periorbital and facial swelling, extending over the head. These signs are frequently followed by cerebral disorientat"}}]},"avian-medicine--avian-mpv--secondary-infection-และผลต่อการให้ไข่":{"claims":[{"id":"avian-medicine--avian-mpv--secondary-infection-และผลต่อการให้ไข่--v1","statement":"อาการเด่นของ swollen head syndrome ในไก่เกิดจากการติดเชื้อแบคทีเรียแทรกซ้อน เช่น Escherichia coli ไม่ใช่จากไวรัสโดยตรง ซึ่งสนับสนุนการที่สไลด์โยง E. coli เข้ากับอาการรุนแรง","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2022","locator":"Section B.1.1 Collection and selection of diagnostic specimens, page 5","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"This certainly applies to SHS of chickens in which the characteristic signs appear to be due to secondary (e.g. Escherichia coli) bacterial infection."}},{"id":"avian-medicine--avian-mpv--secondary-infection-และผลต่อการให้ไข่--v2","statement":"เชื้อแทรกซ้อนที่ทำให้โรครุนแรงและยืดเยื้อได้แก่ Bordetella avium, Pasteurella-like organisms, Mycoplasma gallisepticum, Chlamydophila และ Ornithobacterium rhinotracheale รวมถึงการติดเชื้อร่วมกับไวรัส infectious laryngotracheitis, infectious bronchitis และ paramyxovirus-1 หรือ avian orthoavulavirus-1","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2022","locator":"Section A. Introduction, page 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Among secondary agents that have been shown to exacerbate and prolong clinical disease are Bordetella avium, Pasteurella-like organisms, Mycoplasma gallisepticum, Chlamydophila and Ornithobacterium rhinotracheale"}},{"id":"avian-medicine--avian-mpv--secondary-infection-และผลต่อการให้ไข่--v3","statement":"aMPV ทำให้ผลผลิตไข่ลดลง 10 ถึง 40% ซึ่งครอบคลุมช่วง 15 ถึง 30% ที่สไลด์ระบุ พร้อมกับคุณภาพไข่ที่ลดลง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-39861016","locator":"Section on aMPV economic impact; Pathogens 14(1):55","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"decline of 10–40% in egg production, causing massive economic losses"}}]},"avian-medicine--avian-mpv--รอยโรค-lesions":{"claims":[{"id":"avian-medicine--avian-mpv--รอยโรค-lesions--v1","statement":"รอยโรคทางเดินหายใจส่วนต้นเริ่มจาก serous rhinitis แล้วเปลี่ยนเป็น catarrhal rhinitis ที่มี mucopurulent exudate พร้อมความเสียหายของชั้นเยื่อบุผิวและการแทรกของเซลล์อักเสบชนิด mononuclear ในชั้น submucosa ที่ 3 ถึง 4 วันหลังติดเชื้อ ตรงกับ watery to mucoid exudate ใน turbinates ที่สไลด์ระบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2022","locator":"Section A. Introduction, page 3","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"A catarrhal rhinitis with mucopurulent exudate, damage to the epithelial layer and a copious mononuclear inflammatory infiltration in the submucosa was seen 3–4 dpi."}},{"id":"avian-medicine--avian-mpv--รอยโรค-lesions--v2","statement":"ในไก่งวงที่กำลังให้ไข่ อาจมีผลผลิตไข่ลดลงถึง 70% และคุณภาพไข่ในช่วงฟื้นตัวซึ่งกินเวลาถึง 3 สัปดาห์อาจไม่ดี สนับสนุนรอยโรคระบบสืบพันธุ์แบบ misshapen eggs, thin shell และ discoloured eggs ที่สไลด์ระบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2022","locator":"Section A. Introduction, page 3","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Respiratory infection is less severe in laying turkeys; however, there may be a drop in egg production of up to 70% (Stuart, 1989) and the quality of eggs during the recovery period, up to 3 weeks, may be poor."}},{"id":"avian-medicine--avian-mpv--รอยโรค-lesions--v3","statement":"ในไก่งวงพ่อแม่พันธุ์ ไก่เนื้อพ่อแม่พันธุ์ และไก่ไข่ aMPV ทำให้ผลผลิตไข่ลดลง ซึ่งในไก่งวงพ่อแม่พันธุ์อาจกลายเป็นความเสียหายถาวร และมีผลต่อคุณภาพเปลือกไข่","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-41739607","locator":"Abstract; Avian Dis 69(S1):505-515","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In turkey breeders, broiler breeders, and laying hens, aMPV causes a decrease in egg production, which may become permanent in turkey breeders and may affect eggshell quality causing significant economic impact."}}]},"avian-medicine--avian-mpv--การวินิจฉัย-diagnosis":{"claims":[{"id":"avian-medicine--avian-mpv--การวินิจฉัย-diagnosis--v1","statement":"การเพาะแยกเชื้อทำได้ใน cell cultures, embryonated chicken eggs และ tracheal organ cultures แต่โดยทั่วไปไม่นิยมทำเป็นงานประจำเพราะเชื้อแยกยากและวิธีการใช้แรงงานมาก ตรงกับที่สไลด์ระบุว่าเพาะเชื้อได้ยาก","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2022","locator":"Section B. Diagnostic techniques, page 3","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Isolation and identification of the agent provide the most certain diagnosis of aMPV, but are not usually attempted for routine diagnostic purposes as the virus may prove difficult to isolate and these tests are labour intensive."}},{"id":"avian-medicine--avian-mpv--การวินิจฉัย-diagnosis--v2","statement":"RT-PCR มีความไวและรวดเร็วกว่าการเพาะแยกเชื้อแบบมาตรฐานอย่างมีนัยสำคัญ เนื่องจาก aMPV เป็นเชื้อที่เพาะยาก","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2022","locator":"Section B.1.3 Molecular identification, page 6","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Reverse-transcription PCR (RT-PCR) is a significantly more sensitive and rapid method for the detection of aMPV than standard virus isolation methods because of the fastidious nature of aMPV."}},{"id":"avian-medicine--avian-mpv--การวินิจฉัย-diagnosis--v3","statement":"การตรวจทางซีรัมวิทยาที่ใช้บ่อยที่สุดคือ ELISA ส่วนวิธีอื่นที่ใช้ได้คือ virus neutralisation, immunofluorescence และ immunodiffusion tests ตรงกับที่สไลด์ระบุว่าใช้ ELISA และ VN","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2022","locator":"Summary, page 1 and Section B.2 Serological tests, page 7","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The most commonly employed method is the ELISA. Other methods that have been used are virus neutralisation (VN), immunofluorescence and immunodiffusion tests."}},{"id":"avian-medicine--avian-mpv--การวินิจฉัย-diagnosis--v4","statement":"เนื่องจากอาการทางคลินิกของ aMPV คล้ายกับเชื้อก่อโรคทางเดินหายใจชนิดอื่น การวินิจฉัยยืนยันจึงต้องอาศัยการตรวจหาตัวไวรัสด้วย isolation, RT-PCR หรือ RT-qPCR, immunohistochemistry หรือ hybridization ซึ่งเป็นเหตุผลที่ต้องทำ differential diagnosis","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-41739607","locator":"Abstract; Avian Dis 69(S1):505-515","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Given its similar clinical appearance to other respiratory pathogens, definitive diagnosis requires identification of the virus by isolation, RT-PCR/RT-qPCR, immunohistochemical staining, orhybridization."}}]},"avian-medicine--avian-mpv--การเก็บตัวอย่าง-ชนิดตัวอย่างและจังหวะเวลา":{"claims":[{"id":"avian-medicine--avian-mpv--การเก็บตัวอย่าง-ชนิดตัวอย่างและจังหวะเวลา--v1","statement":"ตัวอย่างที่ควรเลือกคือ nasal exudates, choanal cleft swabs และ turbinate specimens ที่เก็บในช่วง 2 ถึง 7 วันหลังสัมผัสเชื้อ ตรงกับที่สไลด์ระบุทั้งชนิดตัวอย่างและกรอบเวลาสั้น ๆ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2022","locator":"Section B.1.3 Molecular identification, page 6","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Nasal exudates, choanal cleft swabs, and turbinate specimens collected 2–7 days post-exposure are the preferred specimen (Cook et al., 1993b; Pedersen et al., 2001; Stuart, 1989)."}},{"id":"avian-medicine--avian-mpv--การเก็บตัวอย่าง-ชนิดตัวอย่างและจังหวะเวลา--v2","statement":"ต้องเก็บตัวอย่างในระยะแรกของการติดเชื้อ เพราะไวรัสอาจอยู่ใน sinuses และ turbinates เพียงช่วงสั้น ๆ และควรเก็บจากทางเดินหายใจส่วนต้นของสัตว์เป็นในระยะเฉียบพลันด้วย sterile swabs","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2022","locator":"Section B.1.1 Collection and selection of diagnostic specimens, page 4","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"It is very important to take samples for attempted virus isolation in the early stages of infection as the virus may be present only in the sinuses and turbinates for a short period."}}]},"avian-medicine--avian-mpv--การเก็บตัวอย่าง-จากสัตว์เป็นและจากการผ่าซาก":{"claims":[{"id":"avian-medicine--avian-mpv--การเก็บตัวอย่าง-จากสัตว์เป็นและจากการผ่าซาก--v1","statement":"ตัวอย่างที่ให้ผลสำเร็จสูงสุดคือ nasal exudates, choanal cleft swabs และการขูด sinus กับ turbinate tissue ส่วนไวรัสยังแยกได้จากหลอดลมและปอด และบางครั้งจากอวัยวะภายในของลูกไก่งวงที่ป่วย ตรงกับรายการตัวอย่างจากสัตว์เป็นและจากการผ่าซากในสไลด์","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2022","locator":"Section B.1.1 Collection and selection of diagnostic specimens, page 4","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The most successful samples have been nasal exudates, choanal cleft swabs and scrapings of sinus and turbinate tissue. The virus has also been isolated from trachea and lungs, and occasionally viscera of affected turkey poults."}}]},"avian-medicine--avian-mpv--การควบคุมโรค":{"claims":[{"id":"avian-medicine--avian-mpv--การควบคุมโรค--v1","statement":"การควบคุมเชื้อแบคทีเรียแทรกซ้อนมีเหตุผลรองรับ เพราะเมื่อการจัดการไม่ดีหรือมีการติดเชื้อแบคทีเรียแทรกซ้อน จะเกิด airsacculitis, pericarditis, pneumonia และ perihepatitis ทำให้โรคยืดเยื้อและเพิ่มทั้ง morbidity และ mortality","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2022","locator":"Section A. Introduction, page 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"When husbandry is poor or secondary bacterial infection occurs, airsacculitis, pericarditis, pneumonia, and perihepatitis may prolong the disease and there may be an increase in morbidity and mortality."}},{"id":"avian-medicine--avian-mpv--การควบคุมโรค--v2","statement":"การทดลองในลูกไก่เนื้อแสดงว่า APV ร่วมกับ Escherichia coli ก่อโรคแบบ synergistic โดยเมื่อให้เชื้อพร้อมกันอาการทางคลินิกรุนแรงกว่าให้ไวรัสอย่างเดียวอย่างมีนัยสำคัญ และแยก E. coli ได้จากเกือบ 100% ของนกที่ติดเชื้อร่วม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-19184908","locator":"Abstract; Avian Pathol 30(3):257-67","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"When the agents were given together, the clinical disease was significantly more severe than that caused by the virus alone ... E. coli was isolated from almost 100% of birds with mixed infections"}}]},"avian-medicine--avian-mpv--การป้องกันโรค-2-เสาหลัก":{"claims":[{"id":"avian-medicine--avian-mpv--การป้องกันโรค-2-เสาหลัก--v1","statement":"การควบคุม aMPV ต้องอาศัย biosecurity ที่เข้มงวดร่วมกับโปรแกรมวัคซีน พร้อมการวินิจฉัยที่แม่นยำและการเฝ้าระวังทางระบาดวิทยา สอดคล้องกับ 2 เสาหลักที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-41739607","locator":"Abstract; Avian Dis 69(S1):505-515","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Stringent biosecurity and vaccination protocols along with accurate diagnosis and epidemiological surveillance are required for control of aMPV."}}]},"avian-medicine--avian-mpv--biosecurity":{"claims":[{"id":"avian-medicine--avian-mpv--biosecurity--v1","statement":"ไวรัสอยู่รอดในตัวสัตว์และในสิ่งแวดล้อมได้เพียงช่วงสั้น ๆ และไม่มีหลักฐานการถ่ายทอดผ่านไข่ ดังนั้น biosecurity ที่ดีร่วมกับการใช้วัคซีนอย่างระมัดระวังจึงเพียงพอที่จะควบคุมและจำกัดการแพร่ของเชื้อได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10935282","locator":"Abstract; Rev Sci Tech 19(2):602-13","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The virus persists for only a short time both in the host and in the environment and is not known to be transmitted via the egg. Highly effective vaccines are available to control APV infections, and hence good biosecurity and careful use o"}},{"id":"avian-medicine--avian-mpv--biosecurity--v2","statement":"การกันนกธรรมชาติออกจากโรงเรือนมีเหตุผลรองรับ เพราะแยกเชื้อ APV ได้จากนกน้ำ sentinel ใกล้ฟาร์มที่ติดเชื้อและจาก wild Canada geese ชี้ว่านกอิสระอาจมีบทบาทในการแพร่เชื้อ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12665110","locator":"Abstract; Anim Health Res Rev 3(2):107-17","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Infectious APV was isolated from sentinel waterfowls placed close to an infected commercial turkey farm and from wild Canada geese captured in Minnesota, suggesting that free-ranging birds may be involved in the spread of APV."}}]},"avian-medicine--avian-mpv--management":{"claims":[{"id":"avian-medicine--avian-mpv--management--v1","statement":"การจัดการฟาร์มที่ไม่ดีเป็นปัจจัยที่ทำให้โรคยืดเยื้อและเพิ่ม morbidity กับ mortality เช่นเดียวกับการติดเชื้อแบคทีเรียแทรกซ้อน สนับสนุนการเน้นเรื่องการจัดการและการระวัง secondary infection","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2022","locator":"Section A. Introduction, page 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"When husbandry is poor or secondary bacterial infection occurs, airsacculitis, pericarditis, pneumonia, and perihepatitis may prolong the disease and there may be an increase in morbidity and mortality."}}]},"avian-medicine--avian-mpv--วัคซีน-ชนิดและคุณสมบัติ":{"claims":[{"id":"avian-medicine--avian-mpv--วัคซีน-ชนิดและคุณสมบัติ--v1","statement":"วัคซีนที่มีจำหน่ายเชิงพาณิชย์สำหรับควบคุม TRT และ SHS มี 2 ชนิด คือ live attenuated vaccines และ inactivated oil-emulsion adjuvanted vaccines ตรงกับการแบ่งวัคซีนเชื้อเป็นและเชื้อตายในสไลด์","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2022","locator":"Section C. Requirements for vaccines, page 8","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Two types of vaccine are commercially available for the control of TRT and SHS: live attenuated vaccines, or inactivated oil-emulsion adjuvanted vaccines."}},{"id":"avian-medicine--avian-mpv--วัคซีน-ชนิดและคุณสมบัติ--v2","statement":"เชื้อ aMPV รวมถึงสายพันธุ์วัคซีนชนิดเชื้อเป็นกระตุ้น virus neutralizing antibodies ทั้งเฉพาะที่ในหลอดลมซึ่งตรวจจาก tracheal washes และแบบทั่วร่างกายในซีรัม ยืนยันว่าวัคซีนเชื้อเป็นกระตุ้นทั้ง local และ systemic immunity","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17207537","locator":"Abstract; Vet Immunol Immunopathol 115(3-4):273-85","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Virus neutralizing antibodies were detected locally in tracheal washes and systemically in serum as soon as 5-7 days post aMPV infection (PI) independent of the strain used."}},{"id":"avian-medicine--avian-mpv--วัคซีน-ชนิดและคุณสมบัติ--v3","statement":"มี cross-protection ระหว่าง subtype A และ B ในไก่งวงจริง โดยหลัง challenge แบบ heterologous ไม่พบอาการทางคลินิกในทุกกลุ่ม แต่การป้องกันเชิงไวรัสวิทยาของสายพันธุ์เชื้อเป็นไม่สมบูรณ์ เพราะยังแยกเชื้อ virulent ได้จากนกที่ challenge ที่ 5 และ 11 สัปดาห์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10958535","locator":"Abstract; Vet Rec 147(5):132-4","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"After challenge, no clinical signs were observed in any of the groups, and no virus was isolated from the turkeys that had been initially inoculated with a virulent strain. Virulent virus was recovered from the birds that had been initially"}},{"id":"avian-medicine--avian-mpv--วัคซีน-ชนิดและคุณสมบัติ--v4","statement":"การให้วัคซีนเชื้อเป็น aMPV subtype B ทั้งทาง coarse spray และทางน้ำดื่มให้การป้องกันอาการทางคลินิกได้ใกล้เคียงกัน สนับสนุนการที่สไลด์ระบุ route แบบ spray และ drinking water","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-41739616","locator":"Abstract; Avian Dis 69(S1):603-612","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Both spray and drinking water methods provided similar protection against clinical signs of infection."}}]},"avian-medicine--avian-mpv--คำแนะนำการทำวัคซีน-และการรบกวนจากวัคซีน-ib-กับ-ndv":{"claims":[{"id":"avian-medicine--avian-mpv--คำแนะนำการทำวัคซีน-และการรบกวนจากวัคซีน-ib-กับ-ndv--v1","statement":"การให้วัคซีนเชื้อเป็น APV พร้อมกับวัคซีนเชื้อเป็น NDV ในลูกไก่ทำให้การเพิ่มจำนวนของไวรัสวัคซีน APV ถูกกดชั่วคราวและลดการตอบสนองของ humoral antibody ต่อ APV ตรงกับที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16147565","locator":"Abstract; Avian Pathol 34(4):297-302","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"It appears that simultaneous vaccination of chicks with live APV and NDV vaccines causes temporary suppression of APV vaccine proliferation and reduces humoral antibody responses to it, although the antibody response to NDV is enhanced."}},{"id":"avian-medicine--avian-mpv--คำแนะนำการทำวัคซีน-และการรบกวนจากวัคซีน-ib-กับ-ndv--v2","statement":"เมื่อให้วัคซีน aMPV พร้อมวัคซีนเชื้อเป็นตัวอื่นรวมทั้ง IBV และ NDV ระดับ ELISA antibody ต่อ aMPV ถูกกดลงจริง แต่ผู้วิจัยพบว่าการให้พร้อมกันไม่ได้ลดการป้องกันโรคที่เกิดขึ้นจริงต่อ aMPV หรือ IBV","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-25482324","locator":"Abstract; Res Vet Sci 98:127-33","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"aMPV vaccine when given with other live vaccines suppressed levels of aMPV enzyme-linked immunosorbent assay (ELISA) antibodies. ... Simultaneous vaccination with live NDV, aMPV and IBV did not affect the protection conferred against aMPV o"}}]},"avian-medicine--avian-mpv--ตัวอย่างโปรแกรมวัคซีนในประเทศไทย":{"claims":[{"id":"avian-medicine--avian-mpv--ตัวอย่างโปรแกรมวัคซีนในประเทศไทย--v1","statement":"aMPV subtype B แพร่กระจายอยู่ในฟาร์มสัตว์ปีกเชิงพาณิชย์ของไทยจริง โดยตรวจพบ 34.13% หรือ 57 จาก 167 ตัวอย่าง และพบ 2 lineage โดย lineage หนึ่งใกล้เคียงกับสายพันธุ์วัคซีน แสดงว่ามีการใช้วัคซีนในไทย และคณะผู้วิจัยเสนอให้ปรับกลยุทธ์วัคซีนให้เหมาะกับพื้นที่","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-40733582","locator":"Abstract; Viruses 17(7):965","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Nested RT-PCR targeting the G gene revealed a positivity rate of 34.13% (57/167). Phylogenetic and Median-joining network analyses of sequenced amplicons identified two distinct Thai lineages: one genetically similar to vaccine strains and "}}]},"avian-medicine--avian-mpv--disinfectant-ที่ใช้ได้":{"claims":[{"id":"avian-medicine--avian-mpv--disinfectant-ที่ใช้ได้--v1","statement":"ตำราอ้างอิงทางสัตวแพทย์ระบุว่า disinfectant กลุ่ม quaternary ammonia (Quats), ethanol, iodophor, phenol derivative และ bleach (sodium hypochlorite) ลด viability ของ AMPV ได้ ตรงกับรายการทั้ง 4 ชนิดในสไลด์ โดยแหล่งอ้างอิงเพิ่ม ethanol เข้ามาด้วย และก็เขียนไว้เป็นระดับกลุ่มสารเช่นกัน ไม่ได้ระบุความเข้มข้นหรือ contact time","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-msd-veterinary-manual--2024","locator":"หัวข้อ Prevention and Treatment of Avian Metapneumovirus (ฉบับทบทวน/แก้ไข Nov 2024)","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The use of disinfectants such as quaternary ammonia, ethanol, iodophors, phenol derivatives, and bleach can decrease the viability of AMPV."}},{"id":"avian-medicine--avian-mpv--disinfectant-ที่ใช้ได้--v2","statement":"งานทดลองกับ avian pneumovirus (AMPV) ที่แยกจาก nasoturbinate ของไก่งวงในรัฐ Minnesota พบว่า quaternary ammonia, ethanol, iodophor, phenol derivative, biguanide และ bleach ลด viability ของไวรัสได้ทั้งหมด เป็นหลักฐานเชิงทดลองที่รองรับน้ำยาฆ่าเชื้อทั้ง 4 ชนิดในสไลด์ โดย bleach คือ sodium hypochlorite และงานนี้เพิ่ม ethanol กับ biguanide เข้ามาด้วย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10879914","locator":"เล่ม 44 ฉบับ 2 หน้า 336-342 (บทคัดย่อ)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Several disinfectants, including quaternary ammonia, ethanol, iodophor, a phenol derivative, a biguanide, and bleach, were all effective in reducing the viability of the virus."}},{"id":"avian-medicine--avian-mpv--disinfectant-ที่ใช้ได้--v3","statement":"การทดสอบน้ำยาฆ่าเชื้อ 9 ชนิดบนพื้นผิว non-porous ที่ปนเปื้อน aMPV พบว่า phenolic compounds และ glutaraldehyde มีประสิทธิภาพสูงสุด ส่วน quaternary ammonium compounds ได้ผลกับ aMPV แต่ไม่ได้ผลกับ avian influenza virus และ Newcastle disease virus ผลนี้รองรับ Phenol และ Quats ที่สไลด์ระบุ และเพิ่มข้อมูลว่า glutaraldehyde ซึ่งสไลด์ไม่ได้ระบุก็ใช้ได้ พร้อมข้อควรระวังว่า Quats ครอบคลุมไวรัสทางเดินหายใจของสัตว์ปีกตัวอื่นได้ไม่ดี","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-18646446","locator":"เล่ม 52 ฉบับ 2 หน้า 199-202 (บทคัดย่อ)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Phenolic compounds and glutaraldehyde were found to be the most effective against all three viruses. Quaternary ammonium compounds were effective against aMPV but not against the other two viruses."}}]},"avian-medicine--avian-mpv--เชื้อและโฮสต์":{"claims":[{"id":"avian-medicine--avian-mpv--เชื้อและโฮสต์--v1","statement":"ตัวเลขในไก่ตรงกับเอกสารบรรยาย คืออัตราตายจาก AMPV ในไก่แทบไม่เกิน 2% ขณะที่อัตราป่วยกระทบได้ถึง 10% ของฝูง และโรคยังทำให้ผลผลิตไข่และคุณภาพไข่ลดลงด้วย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-39861016","locator":"Section 1, Introduction","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Although mortality rates rarely exceed 2% in chickens, morbidity can affect up to 10% of the population."}},{"id":"avian-medicine--avian-mpv--เชื้อและโฮสต์--v2","statement":"นกป่าเป็นแหล่งรังโรคของ AMPV จริง มีหลักฐานการติดเชื้อในห่านป่า ไก่ฟ้า ไก่ต๊อก นกน้ำ เป็ดแมลลาร์ด อีกา และนกอื่นอีกหลายชนิด ซึ่งบ่งชี้ว่าเป็น reservoir และตัวพาเชื้อข้ามภูมิภาคเข้าสู่สัตว์ปีกเลี้ยง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-39861016","locator":"Section 3, The Clinical Manifestations of ILTV and aMPV","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Increasing evidence of the prevalence of aMPV in wild birds suggests a strong possibility of them being reservoirs and inter-regional carriers of this virus, capable of being introduced into domestic poultry."}}]},"avian-medicine--avian-mpv--การเก็บตัวอย่าง-วัคซีน-และการทำลายเชื้อ":{"claims":[{"id":"avian-medicine--avian-mpv--การเก็บตัวอย่าง-วัคซีน-และการทำลายเชื้อ--v1","statement":"หลักการเก็บตัวอย่างที่เอกสารบรรยายเน้นคือต้องเก็บระหว่างที่เชื้อยังเพิ่มจำนวนอยู่ที่ทางเดินหายใจส่วนต้น ซึ่งสอดคล้องกับข้อมูลที่ว่า AMPV เพิ่มจำนวนในเนื้อเยื่อจมูกและไซนัสได้อย่างมากนานถึง 10 วันหลังได้รับเชื้อโดยไม่กระจายไปเนื้อเยื่ออื่น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-39861016","locator":"Section 1, Introduction","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Studies have demonstrated that the virus can replicate significantly in turkeys in nasal and sinus tissues for up to 10 days post-inoculation without spreading to other tissues."}},{"id":"avian-medicine--avian-mpv--การเก็บตัวอย่าง-วัคซีน-และการทำลายเชื้อ--v2","statement":"เป้าหมายหลักของการทำวัคซีน AMPV คือการลดการปล่อยเชื้ออย่างต่อเนื่องจากฝูงที่ติดเชื้อ เพราะการปล่อยเชื้อทำให้สายพันธุ์ในสนามกลายพันธุ์ และมีงานวิจัยชี้ว่าสายพันธุ์วัคซีนเชื้อเป็นที่คงอยู่ในสิ่งแวดล้อมสามารถกลับมามีความรุนแรงได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-39861016","locator":"Section 5, Vaccine Development for ILTV and aMPV","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Vaccination to reduce consistent virus shedding from aMPV-infected flocks is considered a primary objective, as virus shedding can contribute to mutating aMPV field strains. Research indicates that when live aMPV vaccine strains persist in "}}]},"avian-medicine--avian-mpv--อาการและรอยโรค":{"claims":[{"id":"avian-medicine--avian-mpv--อาการและรอยโรค--v1","statement":"รอยโรคทางจุลพยาธิวิทยาหลักของ ILT ในเนื้อเยื่อท่อลมคือการเกิด syncytial cell ร่วมกับ intranuclear inclusion body ที่ติดสี eosinophilic เข้ม ตรงกับที่สไลด์ระบุว่า HP พบ Eosinophilic ICIB ใน epithelial cell","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34345396","locator":"Abstract, histopathology","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Microscopically, syncytial cells formation with dense eosinophilic intranuclear inclusion bodies were main histopathological findings in tracheal tissues."}},{"id":"avian-medicine--avian-mpv--อาการและรอยโรค--v2","statement":"การผ่าซากไก่ที่ติด ILT พบแผ่นเยื่อ diphtheritic แบบ caseous ติดแน่นอยู่ที่กล่องเสียงและท่อลม สอดคล้องกับ diphtheritic in trachea และ plug ใน trachea lumen ที่สไลด์ระบุ โดยฝูงที่รายงานมีอาการอ้าปากหายใจร่วมกับอัตราการตายสูง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34345396","locator":"Abstract, necropsy findings","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"At necropsy, caseous diphtheritic membrane adherent to the larynx and trachea was observed."}},{"id":"avian-medicine--avian-mpv--อาการและรอยโรค--v3","statement":"โรคหัวบวม (Swollen Head Syndrome) ในไก่มีสาเหตุจากไวรัส avian metapneumovirus และเป็นโรคที่มีความสำคัญทางเศรษฐกิจ โดยไวรัสแบ่งเป็น 6 subtype (A, B, C, D, New-1 และ New-2) ตรงกับชื่อโรคที่สไลด์ใช้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-36455491","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Swollen Head Syndrome (SHS) is an economically important viral disease of chickens caused by avian metapneumovirus (aMPV)."}},{"id":"avian-medicine--avian-mpv--อาการและรอยโรค--v4","statement":"การทดลองฉีดไวรัส aMPV สายพันธุ์ PLE8T1 ที่แยกได้จากไก่ที่เป็นโรคหัวบวม เข้าแม่ไก่ไข่ SPF อายุ 173 วัน ทำให้ผลผลิตไข่ลดลงและไข่ผิดปกติจากเปลือกไข่ผิดรูปเพิ่มขึ้น ยืนยันรอยโรคระบบสืบพันธุ์ที่สไลด์ระบุคือ misshapen, thin shell, discolor, rough egg","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16953076","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Decreases in egg production and increased incidence of abnormal eggs due to malformation of egg shells were observed in specific pathogen free (SPF) 173-day-old laying hens inoculated intravenously with an avian metapneumovirus (aMPV) strai"}}]}},"avian-medicine--avian-nd":{"avian-medicine--avian-nd--โรคนิวคาสเซิลคืออะไร-และทำไมต้องสนใจ":{"claims":[{"id":"avian-medicine--avian-nd--โรคนิวคาสเซิลคืออะไร-และทำไมต้องสนใจ--v1","statement":"APMV-1 (NDV) ติดเชื้อในนกได้มากกว่า 200 ชนิด แต่ความรุนแรงของโรคขึ้นกับทั้งชนิดของ host และสายพันธุ์ของไวรัส","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Summary, Description of the disease, p. 1","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"APMV-1 has been shown to be able to infect over 200 species of birds, but the severity of disease produced varies with both host and strain of virus."}},{"id":"avian-medicine--avian-nd--โรคนิวคาสเซิลคืออะไร-และทำไมต้องสนใจ--v2","statement":"อัตราการป่วยและการตายสูงถึง 100% มีรายงานในฝูงไก่ที่ไม่ได้รับวัคซีน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-29911151","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Morbidity and mortality rates up to 100% have been reported in cases of unvaccinated flocks."}},{"id":"avian-medicine--avian-nd--โรคนิวคาสเซิลคืออะไร-และทำไมต้องสนใจ--v3","statement":"APMV-1 ติดเชื้อในคนได้ อาการที่พบบ่อยที่สุดคือ conjunctivitis ซึ่งเกิดภายใน 24 ชั่วโมงหลังเชื้อรุนแรงเข้าตา และไม่มีหลักฐานการติดต่อจากคนสู่คน","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section A. Introduction, p. 3","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"APMV-1 may infect humans where the most common sign of infection is conjunctivitis that develops within 24 hours of virulent APMV-1 exposure to the eye."}}]},"avian-medicine--avian-nd--ประวัติช่วงแรก-100-ปีของโรคนิวคาสเซิล-อินโดนีเซีย":{"claims":[{"id":"avian-medicine--avian-nd--ประวัติช่วงแรก-100-ปีของโรคนิวคาสเซิล-อินโดนีเซีย--v1","statement":"โรคนิวคาสเซิลเชื่อว่ามีรายงานครั้งแรกในปี ค.ศ. 1926 ทั้งที่เกาะชวา (ปัจจุบันคืออินโดนีเซีย) และที่ Newcastle-on-Tyne ประเทศอังกฤษ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-29073919","locator":"Geographical distribution","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Newcastle disease is believed to have first been reported in 1926 in both Newcastle-on-Tyne, England and the island of Java, which is part of current day Indonesia."}}]},"avian-medicine--avian-nd--ประวัติช่วงแรก-อังกฤษ-และที่มาของชื่อ-newcastle":{"claims":[{"id":"avian-medicine--avian-nd--ประวัติช่วงแรก-อังกฤษ-และที่มาของชื่อ-newcastle--v1","statement":"รายงานครั้งแรกในปี ค.ศ. 1926 เกิดขึ้นทั้งที่ Java และที่ Newcastle upon Tyne ประเทศอังกฤษ ตรงตามที่สไลด์สรุป","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-29073919","locator":"Geographical distribution","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Newcastle disease is believed to have first been reported in 1926 in both Newcastle-on-Tyne, England and the island of Java, which is part of current day Indonesia."}}]},"avian-medicine--avian-nd--การระบาดทั่วโลกและความเสียหายทางเศรษฐกิจ":{"claims":[{"id":"avian-medicine--avian-nd--การระบาดทั่วโลกและความเสียหายทางเศรษฐกิจ--v1","statement":"การระบาดใหญ่ของ virulent ND ในรัฐแคลิฟอร์เนียเกิดเป็นระยะ ๆ ในปี 1971-1974 และ 2002-2003 (และล่าสุด 2018-2020) ตรงกับปีที่สไลด์ยกมา","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35891488","locator":"Introduction","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The vND virus has periodically had large outbreaks in California in 1971-1974, 2002-2003, and most recently in 2018-2020."}}]},"avian-medicine--avian-nd--เชื้อก่อโรค-ชื่อเรียก-การจัดจำแนก-และโครงสร้างไวรัส":{"claims":[{"id":"avian-medicine--avian-nd--เชื้อก่อโรค-ชื่อเรียก-การจัดจำแนก-และโครงสร้างไวรัส--v1","statement":"ND เกิดจาก virulent strains ของ avian paramyxovirus type 1 (APMV-1) ซึ่งอยู่ใน genus Orthoavulavirus, subfamily Avulavirinae, family Paramyxoviridae","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section A. Introduction, p. 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Newcastle disease (ND) is caused by virulent strains of avian paramyxovirus type 1 (APMV-1) of the genus Orthoavulavirus belonging to the subfamily Avulavirinae, family Paramyxoviridae."}},{"id":"avian-medicine--avian-nd--เชื้อก่อโรค-ชื่อเรียก-การจัดจำแนก-และโครงสร้างไวรัส--v2","statement":"จีโนมของ NDV เป็น RNA สายเดี่ยว สายลบ ไม่แบ่งท่อน และมี 6 ยีนหลักที่สร้างโปรตีน N, M, P, F, HN และ L","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-24589707","locator":"Section 3, Newcastle disease virus","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The genome of NDV is a non-segmented, negative sense, single stranded RNA... six essential genes encoding nucleocapsid (N), matrix protein (M), phosphoprotein (P), fusion protein (F), haemagglutinin-neuraminidase protein (HN), and large pol"}}]},"avian-medicine--avian-nd--serotype-กับ-genotype-ของ-ndv":{"claims":[{"id":"avian-medicine--avian-nd--serotype-กับ-genotype-ของ-ndv--v1","statement":"ปัจจุบันมี avian paramyxovirus 21 serotypes คือ APMV-1 ถึง APMV-21 และ ND จำกัดอยู่ที่ APMV-1 serotype เดียว","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Summary, Description of the disease, p. 1","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"At present, there are 21 serotypes of avian paramyxoviruses designated APMV-1 to APMV-21."}},{"id":"avian-medicine--avian-nd--serotype-กับ-genotype-ของ-ndv--v2","statement":"วัคซีนเชื้อตายที่ทำจาก genotype I, II, V, VI, VII และ XII ป้องกันการป่วยและการตายได้ 90-100% เมื่อ challenge ด้วยเชื้อรุนแรงต่าง genotype ซึ่งสนับสนุนแนวคิด cross protection ข้าม genotype","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28024856","locator":"Antigenically matched vaccines","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"found, under optimal conditions, to prevent 90 to 100% of the birds from having morbidity and mortality against all the virulent NDV strains used no matter their genotype"}}]},"avian-medicine--avian-nd--genotype-ที่สำคัญ-วัคซีน-และสายพันธุ์ของเอเชียตะวันออกเฉียงใต้":{"claims":[{"id":"avian-medicine--avian-nd--genotype-ที่สำคัญ-วัคซีน-และสายพันธุ์ของเอเชียตะวันออกเฉียงใต้--v1","statement":"สายพันธุ์วัคซีน LaSota, B1 และ VG/GA จัดอยู่ใน genotype II ส่วนวัคซีนอีกกลุ่มที่ใช้กันแพร่หลายคือสายพันธุ์ class II genotype I ตรงกับที่สไลด์ระบุว่า genotype I และ II เป็นกลุ่มวัคซีน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28024856","locator":"Section 3.1, Traditional vaccines","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Viruses circulating in poultry were the source of the LaSota, B1, and VG/GA vaccines. All of those viruses belong to genotype II"}},{"id":"avian-medicine--avian-nd--genotype-ที่สำคัญ-วัคซีน-และสายพันธุ์ของเอเชียตะวันออกเฉียงใต้--v2","statement":"เชื้อรุนแรงใน sub-genotype ใหม่ของ genotype VII กำลังแพร่กระจายในเอเชียและตะวันออกกลาง โดย VIIh แยกได้จากอินโดนีเซีย มาเลเซีย จีน และกัมพูชา ยืนยันความสำคัญของ genotype VII ในเอเชียตะวันออกเฉียงใต้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-25445644","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Viruses from sub-genotype VIIh were isolated in Indonesia (2009-2010), Malaysia (2011), China (2011), and Cambodia (2011-2012)"}}]},"avian-medicine--avian-nd--ndv-มี-5-pathotypes":{"claims":[{"id":"avian-medicine--avian-nd--ndv-มี-5-pathotypes--v1","statement":"APMV-1 ถูกแบ่งเป็น 5 pathotypes ตามอาการทางคลินิกในไก่ ได้แก่ viscerotropic velogenic, neurotropic velogenic, mesogenic, lentogenic (respiratory) และ subclinical (enteric)","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section A. Introduction, p. 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Strains of APMV-1 have been grouped into five pathotypes on the basis of the clinical signs observed in infected chickens"}}]},"avian-medicine--avian-nd--การแบ่ง-pathotypes-ตาม-oie-woah-วิธีที่-1-mean-dead-time-mdt":{"claims":[{"id":"avian-medicine--avian-nd--การแบ่ง-pathotypes-ตาม-oie-woah-วิธีที่-1-mean-dead-time-mdt--v1","statement":"เกณฑ์ MDT ในไข่ฟักคือ velogenic ทำให้ตัวอ่อนตายภายในน้อยกว่า 60 ชั่วโมง mesogenic ตายระหว่าง 60-90 ชั่วโมง และ lentogenic ฆ่าตัวอ่อนไม่ได้แม้เกิน 90 ชั่วโมง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-29911151","locator":"Discussion","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Velogenic strains cause the chicken embryos to die in less than 60 h, lentogenic strain fails to kill the embryos even after 90 h, and the strains that cause embryo mortality between 60 and 90 h are mesogenic."}},{"id":"avian-medicine--avian-nd--การแบ่ง-pathotypes-ตาม-oie-woah-วิธีที่-1-mean-dead-time-mdt--v2","statement":"วิธีทำ MDT คือเจือจางน้ำไข่ฟักแบบ tenfold serial dilution แล้วฉีดแต่ละ dilution เข้า allantoic sac ของไข่ไก่ฟักอายุ 9-11 วัน ตรงกับที่สไลด์ระบุว่าทดสอบใน chicken embryo ทาง allantoic sac","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22577610","locator":"Section 12.5, Characterization","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"tenfold serial dilutions of clean AAF are prepared and each dilution is inoculated into five 9-to-11-day-old embryonating chicken eggs via the allantoic sac route"}}]},"avian-medicine--avian-nd--วิธีที่-2-intracerebral-pathogenicity-index-icpi":{"claims":[{"id":"avian-medicine--avian-nd--วิธีที่-2-intracerebral-pathogenicity-index-icpi--v1","statement":"วิธีทำ ICPI ตาม WOAH คือใช้น้ำไข่ฟักที่มี HA titre มากกว่า 2 ยกกำลัง 4 (มากกว่า 1/16) เจือจาง 1/10 ฉีดเข้าสมอง 0.05 มล. ในลูกไก่ SPF 10 ตัว อายุมากกว่า 24 และน้อยกว่า 40 ชั่วโมง ตรวจทุก 24 ชั่วโมงนาน 8 วัน ให้คะแนน 0 ปกติ 1 ป่วย 2 ตาย","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section B.1.4.1, Intracerebral pathogenicity index, p. 6","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"0.05 ml of the diluted virus is injected intracerebrally into each of ten chicks hatched from eggs from an SPF flock. These chicks must be over 24-hours and under 40-hours old... The birds are examined every 24 hours for 8 days."}},{"id":"avian-medicine--avian-nd--วิธีที่-2-intracerebral-pathogenicity-index-icpi--v2","statement":"APMV-1 ที่มีค่า ICPI ตั้งแต่ 0.7 ขึ้นไป (หรือมี multiple basic amino acids ที่ปลาย C ของ F2 ร่วมกับ phenylalanine ที่ตำแหน่ง 117 ของ F1) ถือเป็นเชื้อรุนแรงที่ต้องรายงาน","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Summary, Detection of the agent, p. 1","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Any APMV-1 with an ICPI of 0.7, or with multiple basic amino acids at the C-terminus of the F2 protein and phenylalanine at residue 117 of its F protein, is considered virulent."}},{"id":"avian-medicine--avian-nd--วิธีที่-2-intracerebral-pathogenicity-index-icpi--v3","statement":"ค่า ICPI สูงสุดคือ 2.0 โดยเชื้อรุนแรงที่สุดจะเข้าใกล้ 2.0 ส่วน lentogenic และ asymptomatic enteric จะได้ค่าใกล้ 0.0 และค่าที่เกิน 0.7 จัดอยู่ในช่วง mesogenic ถึง virulent","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22577610","locator":"Section 12.5, Characterization","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Any ICPI value above 0.7 is classified in the mesogenic to virulent range"}}]},"avian-medicine--avian-nd--วิธีที่-3-intravenous-pathogenicity-index-ivpi":{"claims":[{"id":"avian-medicine--avian-nd--วิธีที่-3-intravenous-pathogenicity-index-ivpi--v1","statement":"IVPI ตาม WOAH ใช้ไก่ SAN หรือ SPF อายุ 4-8 สัปดาห์ 10 ตัว ฉีดไวรัสเจือจาง 1/10 ปริมาณ 0.1 มล. เข้าเส้นเลือดดำ ตรวจทุก 24 ชั่วโมง เป็นเวลา 10 วัน ให้คะแนน 0 ปกติ 1 ป่วย 2 ป่วยรุนแรง 3 ตาย โดยค่า 3.00 คือไก่ตายทั้งหมดภายใน 24 ชั่วโมง และ 0.00 คือไม่มีตัวใดแสดงอาการเลย","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section B.1.4, IVPI procedure, p. 7","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The IVPI is the mean score per bird per observation over the 10-day period. An index of 3.00 means that all birds died within 24 hours, and an index of 0.00 means that no bird showed any clinical sign during the 10-day observation period."}},{"id":"avian-medicine--avian-nd--วิธีที่-3-intravenous-pathogenicity-index-ivpi--v2","statement":"ไวรัสไข้หวัดใหญ่ชนิดเอที่มีค่า IVPI มากกว่า 1.2 จัดเป็น high pathogenicity avian influenza virus ตามเกณฑ์ของ WOAH","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section B.1.4, criteria for determining pathogenicity, p. 7","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"any influenza A virus that has an intravenous pathogenicity index (IVPI) greater than 1.2"}}]},"avian-medicine--avian-nd--รายละเอียดของ-pathotype-ที่รุนแรง-vvndv-nvndv-mesogenic":{"claims":[{"id":"avian-medicine--avian-nd--รายละเอียดของ-pathotype-ที่รุนแรง-vvndv-nvndv-mesogenic--v1","statement":"Viscerotropic velogenic คือรูปแบบรุนแรงมากที่พบรอยโรคเลือดออกในลำไส้บ่อย ๆ neurotropic velogenic คือรูปแบบที่ตายสูงตามหลังอาการทางระบบหายใจและระบบประสาท ส่วน mesogenic แสดงอาการทางระบบหายใจ มีอาการทางประสาทเป็นครั้งคราว แต่อัตราการตายต่ำ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section A. Introduction, pathotypes 1-3, p. 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Viscerotropic velogenic: a highly pathogenic form in which haemorrhagic intestinal lesions are frequently seen; Neurotropic velogenic: a form that presents with high mortality, usually following respiratory and nervous signs; Mesogenic: a f"}}]},"avian-medicine--avian-nd--รายละเอียดของ-pathotype-ที่ไม่รุนแรง-lentogenic-asymtomatic-ente":{"claims":[{"id":"avian-medicine--avian-nd--รายละเอียดของ-pathotype-ที่ไม่รุนแรง-lentogenic-asymtomatic-ente--v1","statement":"Lentogenic หรือ respiratory คือรูปแบบที่ติดเชื้อทางเดินหายใจแบบอ่อนหรือไม่แสดงอาการ ส่วน subclinical คือรูปแบบที่มักเป็นการติดเชื้อในลำไส้แบบไม่แสดงอาการ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section A. Introduction, pathotypes 4-5, p. 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Lentogenic or respiratory: a form that presents with mild or subclinical respiratory infection; Subclinical: a form that usually consists of a subclinical enteric infection."}},{"id":"avian-medicine--avian-nd--รายละเอียดของ-pathotype-ที่ไม่รุนแรง-lentogenic-asymtomatic-ente--v2","statement":"วัคซีนเชื้อเป็นทำจากไวรัสที่มีความรุนแรงต่ำ (lentogenic) หรือปานกลาง (mesogenic) และการใช้สายพันธุ์ LaSota ก่อปัญหาในไก่เล็กที่ยังไวต่อโรคมากกว่าสายพันธุ์ Hitchner-B1 หรือวัคซีนที่ใช้ Ulster เป็นฐาน ซึ่งสอดคล้องกับคำเตือนเรื่อง vaccine reaction ในไก่เล็ก","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section C.2.1.1, Biological characteristics, p. 14","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"vaccination with the LaSota strain will cause considerably greater problems in young susceptible birds than the Hitchner-B1 strain, the Ulster based vaccines, or specific LaSota clones"}}]},"avian-medicine--avian-nd--เซลล์และอวัยวะเป้าหมาย-การติดต่อ-และระยะฟักตัว":{"claims":[{"id":"avian-medicine--avian-nd--เซลล์และอวัยวะเป้าหมาย-การติดต่อ-และระยะฟักตัว--v1","statement":"ไวรัสความรุนแรงต่ำถูกจำกัดการตัด F0 ด้วย host protease บางชนิด จึงเพิ่มจำนวนได้เฉพาะบางชนิดเซลล์ เช่น epithelial cells ของทางเดินหายใจและทางเดินอาหาร","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section B.1.5, Molecular basis for pathogenicity, pp. 6-7","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"restriction of these viruses to growth only in certain host-cell types, such as epithelial cells of the respiratory and gastrointestinal tracts"}},{"id":"avian-medicine--avian-nd--เซลล์และอวัยวะเป้าหมาย-การติดต่อ-และระยะฟักตัว--v2","statement":"เส้นทางการติดต่อหลักคือการกินสิ่งปนเปื้อนอุจจาระ หรือการหายใจเอาละอองที่มีเชื้อเข้าไป","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22577610","locator":"Section 8, Transmission","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The primary route of transmission is either by ingestion of fecal contaminated material or inhalation of droplets containing the organism"}},{"id":"avian-medicine--avian-nd--เซลล์และอวัยวะเป้าหมาย-การติดต่อ-และระยะฟักตัว--v3","statement":"ระยะฟักตัวในสัตว์ปีกเลี้ยงอยู่ที่ 2-15 วัน แต่ในนกชนิดอื่นอาจนานเกิน 28 วัน","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2019","locator":"Diagnosis","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In domestic poultry, the incubation period ranges from 2-15 days, but may exceed 28 days in other species."}}]},"avian-medicine--avian-nd--อาการทั่วไปและปัจจัยที่กำหนดความรุนแรง":{"claims":[{"id":"avian-medicine--avian-nd--อาการทั่วไปและปัจจัยที่กำหนดความรุนแรง--v1","statement":"อาการทางคลินิกแตกต่างกันมากและขึ้นกับปัจจัยหลายอย่าง ได้แก่ ตัวไวรัส ชนิดของ host อายุของ host การติดเชื้อร่วมกับเชื้ออื่น ความเครียดจากสิ่งแวดล้อม และสถานะภูมิคุ้มกัน","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section B.1.6, Description of Newcastle disease, p. 7","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the clinical signs seen in infected birds vary widely and are dependent on factors such as: the virus, host species, age of host, infection with other organisms, environmental stress and immune status"}},{"id":"avian-medicine--avian-nd--อาการทั่วไปและปัจจัยที่กำหนดความรุนแรง--v2","statement":"ไข่อาจมีเปลือกบาง รูปร่างหรือสีผิดปกติ หรือไข่ขาวเหลว และไก่อาจหยุดไข่ไปเลย","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2019","locator":"Diagnosis, Clinical diagnosis","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Eggs may have thin shells, an abnormal shape or colour, or watery albumin."}}]},"avian-medicine--avian-nd--อาการและรอยโรค-ระบบหายใจ":{"claims":[{"id":"avian-medicine--avian-nd--อาการและรอยโรค-ระบบหายใจ--v1","statement":"อาการภายนอกช่วงต้นของโรคได้แก่ ขนหยอง ซึม บวมน้ำหรือเขียวคล้ำที่หัวและคอ ตาแดงอักเสบ และไม่กินอาหาร","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2019","locator":"Diagnosis, Clinical diagnosis","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"animals present with ruffled feathers, lethargy, oedema and/or cyanosis of the head and neck, conjunctival reddening, and inappetence"}},{"id":"avian-medicine--avian-nd--อาการและรอยโรค-ระบบหายใจ--v2","statement":"รอยโรคระบบหายใจจากการผ่าซากอาจพบเลือดออกที่เยื่อบุทางเดินหายใจ ถุงลมอักเสบ และหลอดลมคั่งเลือด แต่ไม่พบเสมอไป และการติดเชื้อแบคทีเรียแทรกซ้อนทำให้ถุงลมหนาตัวมีสารคัดหลั่ง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22577610","locator":"Pathology","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Gross lesions of the respiratory tract may include hemorrhage of the respiratory mucosa, airsacculitis and congestion of the trachea but are not always seen."}}]},"avian-medicine--avian-nd--อาการและรอยโรค-ระบบทางเดินอาหาร":{"claims":[{"id":"avian-medicine--avian-nd--อาการและรอยโรค-ระบบทางเดินอาหาร--v1","statement":"ไก่ที่ติดเชื้ออาจถ่ายเหลวเป็นน้ำสีขาวหรือเขียว","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2019","locator":"Diagnosis, Clinical diagnosis","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Birds may also develop watery, white or green diarrhoea."}},{"id":"avian-medicine--avian-nd--อาการและรอยโรค-ระบบทางเดินอาหาร--v2","statement":"การติดเชื้อ vvND มักสัมพันธ์กับการตายของผนังลำไส้หรือเนื้อเยื่อน้ำเหลือง ทำให้เกิดรอยโรคเลือดออกที่เยื่อบุ proventriculus, ซีคัม, ดูโอดีนัม, เจจูนัม และไอเลียม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22577610","locator":"Pathology","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Infection with panzootic vvND is commonly associated with necrosis of the intestinal wall or lymphoid tissues resulting in hemorrhagic lesions in the mucosa of the proventriculus, ceca, duodenum, jejunum, and ileum"}},{"id":"avian-medicine--avian-nd--อาการและรอยโรค-ระบบทางเดินอาหาร--v3","statement":"รอยโรคที่รายงานไว้รวมถึงจุดเลือดออกและจ้ำเลือดที่เยื่อบุ proventriculus มักอยู่ใกล้ต่อมเมือก และการตายของเยื่อบุลำไส้ Peyer patches เนื้อเยื่อน้ำเหลืองอื่น และ caecal tonsils ซึ่งตรงกับ necrotic hemorrhagic GALT ในสไลด์","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2019","locator":"Diagnosis, Lesions","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Petechiae and ecchymoses on the proventricular mucosa, often near mucous glands; Necrosis of the intestinal mucosa, Peyer's patches and other lymphoid tissue, and caecal tonsils"}}]},"avian-medicine--avian-nd--อาการและรอยโรค-ระบบประสาท":{"claims":[{"id":"avian-medicine--avian-nd--อาการและรอยโรค-ระบบประสาท--v1","statement":"อาการทางระบบประสาทส่วนกลางที่พบทั่วไปได้แก่ tremors, clonic spasms, อัมพาตหรืออ่อนแรงของขา, เดินวน และ torticollis","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2019","locator":"Diagnosis, Clinical diagnosis","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Typical central nervous system (CNS) signs include tremors, clonic spasms, limb paralysis or paresis, circling, and torticollis."}},{"id":"avian-medicine--avian-nd--อาการและรอยโรค-ระบบประสาท--v2","statement":"ไก่ที่แสดงอาการทางประสาทไม่พบรอยโรคทางพยาธิวิทยาในระบบประสาทส่วนกลาง ซึ่งตรงกับที่สไลด์ระบุว่าไม่เห็นรอยโรคจาก gross lesion","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22577610","locator":"Pathology","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Birds displaying neurologic symptoms do not have pathologic lesions in the central nervous system."}}]},"avian-medicine--avian-nd--การวินิจฉัยและการวินิจฉัยแยกแยะ":{"claims":[{"id":"avian-medicine--avian-nd--การวินิจฉัยและการวินิจฉัยแยกแยะ--v1","statement":"โรคที่ต้องวินิจฉัยแยกจาก ND ได้แก่ highly pathogenic avian influenza, laryngotracheitis, fowl cholera, mycoplasmosis และ infectious bronchitis ตรงกับรายการในสไลด์","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2019","locator":"Diagnosis, Differential diagnoses","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Highly pathogenic avian influenza; Laryngotracheitis; Fowl cholera; Fowl pox (diphtheritic form)... Mycoplasmosis; Infectious bronchitis"}},{"id":"avian-medicine--avian-nd--การวินิจฉัยและการวินิจฉัยแยกแยะ--v2","statement":"วิธีวินิจฉัยที่แนะนำคือ validated RT-PCR และการหาลำดับเบส แต่การเพาะแยกเชื้อยังคงเป็นเครื่องมือสำคัญ ส่วนทางซีรัมวิทยาใช้ HI มากที่สุด และ ELISA ก็มีบทบาทเช่นกัน","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Summary, Description of the disease and Serological tests, pp. 1-2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The preferred method of diagnosis is validated reverse transcription polymerase chain reaction (RT-PCR) and sequencing, but virus isolation still remains an important laboratory tool."}}]},"avian-medicine--avian-nd--ตัวอย่างที่เก็บ-สัตว์เป็น-และตอนผ่าซาก":{"claims":[{"id":"avian-medicine--avian-nd--ตัวอย่างที่เก็บ-สัตว์เป็น-และตอนผ่าซาก--v1","statement":"ในสัตว์เป็นควรเก็บทั้ง tracheal หรือ oropharyngeal swab และ cloacal swab ส่วนจากซากควรเก็บลำไส้หรือ cloacal swab ร่วมกับ oropharyngeal หรือ tracheal swab และอวัยวะ ได้แก่ ปอด ถุงลม ลำไส้ ม้าม ไต caecal tonsils สมอง ตับ และหัวใจ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section B.1.1, Samples for virus isolation, p. 4","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Samples from lungs, air sacs, intestine, spleen, kidneys, caecal tonsils, brain, liver and heart should also be collected... Samples from live birds should include both tracheal or oropharyngeal and cloacal swabs"}}]},"avian-medicine--avian-nd--เทคนิคการเก็บ-swab-oropharyngeal-tracheal-cloacal":{"claims":[{"id":"avian-medicine--avian-nd--เทคนิคการเก็บ-swab-oropharyngeal-tracheal-cloacal--v1","statement":"Tracheal หรือ oropharyngeal swab มักเป็นตัวอย่างที่เลือกใช้ เพราะจัดการง่ายและมีสารอินทรีย์ปนเปื้อนน้อยที่จะรบกวนการสกัด RNA และการเพิ่มปริมาณด้วย PCR ซึ่งสนับสนุนข้อความที่ว่า oropharyngeal swab เพียงพอสำหรับการตรวจหาเชื้อ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section B.1.9, Molecular techniques in diagnosis, p. 8","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Tracheal or oropharyngeal swabs are often used as the specimens of choice, because they are easy to process and usually contain little extraneous organic material that can interfere with RNA recovery and amplification by PCR."}},{"id":"avian-medicine--avian-nd--เทคนิคการเก็บ-swab-oropharyngeal-tracheal-cloacal--v2","statement":"Cloacal swab ควรมีอุจจาระเคลือบให้เห็นได้ชัด และการ swab นกตัวเล็กบอบบางควรใช้ swab ขนาดเล็กชนิดที่ใช้ในเด็ก หรือเก็บอุจจาระสดแทน","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section B.1.1, Samples for virus isolation, p. 4","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the latter should be visibly coated with faecal material. To avoid harming them, swabbing of small delicate birds should be done with the use of especially small swabs"}}]},"avian-medicine--avian-nd--containment-การบรรจุตัวอย่างอย่างน้อย-3-ชั้น":{"claims":[{"id":"avian-medicine--avian-nd--containment-การบรรจุตัวอย่างอย่างน้อย-3-ชั้น--v1","statement":"FTA card ใช้เก็บและขนส่งตัวอย่างที่เป็นบวกต่อ NDV ได้จริง โดยให้ RNA ที่เชื่อถือได้สำหรับการตรวจระดับโมเลกุล ไวรัสคงตัวบนการ์ดได้ 15 วัน และไวรัสถูกทำให้หมดฤทธิ์เมื่อสัมผัสการ์ด จึงเป็นตัวอย่างที่ปลอดภัย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16595299","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The FTA cards are suitable for collecting and transporting NDV-positive samples, providing a reliable source of RNA for molecular characterization and a hazard-free sample."}}]},"avian-medicine--avian-nd--hemagglutination-inhibition-test-hi":{"claims":[{"id":"avian-medicine--avian-nd--hemagglutination-inhibition-test-hi--v1","statement":"ค่า HI titre คือระดับการเจือจางซีรัมสูงสุดที่ยับยั้ง 4 HAU ของแอนติเจนได้อย่างสมบูรณ์ ตรงกับหลักการอ่านผลแผ่น microtiter ในสไลด์","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section B.2.3.2, Haemagglutination inhibition test, p. 13","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The HI titre is the highest dilution of serum causing complete inhibition of 4 HAU of antigen."}},{"id":"avian-medicine--avian-nd--hemagglutination-inhibition-test-hi--v2","statement":"HI test ใช้ตรวจแอนติบอดีต่อ Avibacterium (Haemophilus) paragallinarum ซึ่งเป็นเชื้อก่อโรค infectious coryza ได้จริง สนับสนุนรายการโรคที่สไลด์ระบุว่าใช้ HI ได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17656110","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The ability of blocking ELISAs and haemagglutination-inhibition (HI) tests to detect antibodies in sera from chickens challenged with either Avibacterium (Haemophilus) paragallinarum isolate Hp8 (serovar A) or H668 (serovar C) was compared."}}]},"avian-medicine--avian-nd--หลักการควบคุมและป้องกันโรค-และ-epidemiology-triad":{"claims":[{"id":"avian-medicine--avian-nd--หลักการควบคุมและป้องกันโรค-และ-epidemiology-triad--v1","statement":"การควบคุม ND ต้องประกอบด้วย biosecurity ที่เข้มงวดเพื่อกันไม่ให้เชื้อรุนแรงสัมผัสสัตว์ปีก ร่วมกับการให้วัคซีนที่มีประสิทธิภาพอย่างถูกวิธี","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28024856","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The control of ND must include strict biosecurity that prevents virulent NDV from contacting poultry, and also proper administration of efficacious vaccines."}}]},"avian-medicine--avian-nd--flock-immunity-ภูมิคุ้มกันระดับฝูง":{"claims":[{"id":"avian-medicine--avian-nd--flock-immunity-ภูมิคุ้มกันระดับฝูง--v1","statement":"การแพร่ของ NDV ในพื้นที่หนึ่งอาจถูกตัดวงจรได้ก็ต่อเมื่อสัตว์ที่ไวต่อโรคในพื้นที่นั้นมากกว่า 80% ได้รับภูมิคุ้มกันเพียงพอ โดยมี antibody titre ตั้งแต่ 1:8 ขึ้นไป","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section C.2.3.2, For control and eradication, p. 18","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Transmission of the ND virus in an area might be interrupted only if a very high percentage of the resident susceptible population (> 80%) is sufficiently immunised showing an Ab titre 1:8."}}]},"avian-medicine--avian-nd--biosecurity-และสารฆ่าเชื้อ":{"claims":[{"id":"avian-medicine--avian-nd--biosecurity-และสารฆ่าเชื้อ--v1","statement":"NDV ถูกทำลายด้วย sodium hypochlorite, phenols, glutaraldehyde, chlorhexidine และสารออกซิไดซ์ รวมถึง ethers และ formalin ส่วนความร้อนที่ 56 องศาเซลเซียส 3 ชั่วโมง หรือ 60 องศาเซลเซียส 30 นาที ก็ทำลายเชื้อได้","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2019","locator":"Aetiology, resistance table","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Sodium hypochlorite, phenols, glutaraldehyde, chlorhexidine, and oxidising agents; quaternary ammonium compounds must be used in conjunction with sodium carbonate; ethers and formalin also deactivate the virus."}},{"id":"avian-medicine--avian-nd--biosecurity-และสารฆ่าเชื้อ--v2","statement":"มาตรการ sanitary prophylaxis ที่แนะนำได้แก่ การกำจัดซากอย่างเหมาะสม การฆ่าเชื้ออุปกรณ์เครื่องมือและยานพาหนะก่อนเคลื่อนย้าย การใช้ PPE และเปลี่ยนรองเท้าเสื้อผ้าก่อนออกจากพื้นที่ การจำกัดการเดินเข้าออก และการกันนกธรรมชาติกับควบคุมสัตว์พาหะ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2019","locator":"Prevention and Control, Sanitary prophylaxis","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Proper carcass disposal... all tools, instruments, and vehicles should be properly disinfected before moving locations... Bird-proofing and pest control of domestic bird housing in endemic areas."}}]},"avian-medicine--avian-nd--management-ที่ช่วยควบคุมโรค":{"claims":[{"id":"avian-medicine--avian-nd--management-ที่ช่วยควบคุมโรค--v1","statement":"แหล่งน้ำในฟาร์มต้องสะอาด และไม่ควรใช้น้ำผิวดินที่นกอพยพมีโอกาสปนเปื้อนได้ สนับสนุนหัวข้อความสะอาดและคุณภาพน้ำในสไลด์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22577610","locator":"Biosecurity","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The water supply should be clean and should not come from surface water where migratory birds have the potential to contaminate the water source."}}]},"avian-medicine--avian-nd--วัคซีนชนิดที่-1-วัคซีนเชื้อเป็น":{"claims":[{"id":"avian-medicine--avian-nd--วัคซีนชนิดที่-1-วัคซีนเชื้อเป็น--v1","statement":"Master seed ของวัคซีนเชื้อเป็นต้องมีค่า ICPI น้อยกว่า 0.4 (หรือน้อยกว่า 0.5 เมื่อให้ปริมาณไวรัสสูงกว่า) ส่วน master seed ของวัคซีนเชื้อตายต้องมี ICPI น้อยกว่า 0.7 ดังนั้นเลข 0.7 เป็นเกณฑ์ของวัคซีนเชื้อตาย ไม่ใช่ทางเลือกสำหรับวัคซีนเชื้อเป็น","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-european-commission-of-1993","locator":"Article 1","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"intracerebral pathogenicity index (ICPI) of: (i) less than 0,4 if not less than 10^7 EID50... less than 0,5 if not less than 10^8 EID50 are administered to each bird"}},{"id":"avian-medicine--avian-nd--วัคซีนชนิดที่-1-วัคซีนเชื้อเป็น--v2","statement":"วัคซีนเชื้อเป็นกระตุ้นทั้งภูมิคุ้มกันระดับเยื่อเมือกและระดับฮิวมอรัล และให้ได้ด้วยวิธี mass application แต่ก็อาจทำให้เกิดอาการทางระบบหายใจ ไข่ลด และเสื่อมสภาพง่ายถ้าไม่เก็บที่อุณหภูมิที่กำหนด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28024856","locator":"Section 3.1, Traditional vaccines","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"While live vaccines provide both mucosal and humoral immunity and can be administered using mass application techniques, they may cause clinical respiratory disease, drop in egg production"}}]},"avian-medicine--avian-nd--ตาราง-vaccine-strain-pathotype-genotype-และ-icpi":{"claims":[{"id":"avian-medicine--avian-nd--ตาราง-vaccine-strain-pathotype-genotype-และ-icpi--v1","statement":"LaSota, B1 และ VG/GA ล้วนอยู่ใน genotype II และมีความเหมือนกันทางพันธุกรรมและแอนติเจนสูงมาก (nucleotide identity มากกว่า 98%) ตรงกับ genotype ในตารางของสไลด์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28024856","locator":"Section 3.1, Traditional vaccines","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"All of those viruses belong to genotype II and are genetically and antigenically highly related among themselves (>98% nucleotide identity)"}}]},"avian-medicine--avian-nd--วัคซีนชนิดที่-2-และ-3-เชื้อตาย-และ-recombinant":{"claims":[{"id":"avian-medicine--avian-nd--วัคซีนชนิดที่-2-และ-3-เชื้อตาย-และ-recombinant--v1","statement":"วัคซีนเชื้อตายต้องฉีดทีละตัวทาง subcutaneous หรือ intramuscular และไก่ที่ได้รับมักมีระดับ humoral antibody สูงกว่า แต่ไม่สร้าง cell mediated response ที่แรง และปล่อยเชื้อ challenge ออกมามากกว่าไก่ที่ได้วัคซีนเชื้อเป็น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28024856","locator":"Section 3.1, Traditional vaccines","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Even though birds vaccinated with inactivated vaccines tend to have higher humoral antibody levels, they do not develop a strong cell mediated response, and shed larger amounts of virulent challenge virus compared to birds vaccinated with l"}},{"id":"avian-medicine--avian-nd--วัคซีนชนิดที่-2-และ-3-เชื้อตาย-และ-recombinant--v2","statement":"วัคซีน recombinant ที่ใช้ viral vector เช่น turkey herpesvirus หรือ fowl poxvirus ที่แสดงยีน HN, F หรือทั้งสอง ได้รับการพัฒนาและขึ้นทะเบียนแล้ว ตรงกับ HVT-ND และ Fowl Pox-ND ในสไลด์","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Summary, Requirements for vaccines, p. 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Recombinant Newcastle disease vaccines using viral vectors such as turkey herpesvirus or fowl poxvirus in which the HN gene, F gene or both are expressed have recently been developed and approved."}}]},"avian-medicine--avian-nd--ตัวอย่างโปรแกรมวัคซีน-ไก่เนื้อ":{"claims":[{"id":"avian-medicine--avian-nd--ตัวอย่างโปรแกรมวัคซีน-ไก่เนื้อ--v1","statement":"ไก่อายุสั้นอย่างไก่เนื้อมักได้วัคซีนครั้งเดียว โดยให้แบบ in ovo หรือที่อายุ 1 วันในโรงฟัก ซึ่ง in ovo คือวัคซีน recombinant HVT-ND ส่วนที่ให้ลูกไก่อายุ 1 วันมักเป็นวัคซีน NDV เชื้อเป็น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-29073919","locator":"Domestic poultry, vaccination","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"shorter lived birds typically receive one vaccine, either in ovo or at 1 day of age in the hatchery... The in ovo vaccine is a recombinant herpesvirus of turkeys/Newcastle disease virus vaccine, whereas the vaccine administered to day-old b"}},{"id":"avian-medicine--avian-nd--ตัวอย่างโปรแกรมวัคซีน-ไก่เนื้อ--v2","statement":"โปรแกรมทั่วไปของไก่เนื้อคือให้วัคซีนวันแรกทางหยอดตา แล้วบูสเตอร์ที่อายุประมาณ 14 วันทางน้ำดื่ม ซึ่งใกล้เคียงกับช่วง 7-14 วันในสไลด์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-24589707","locator":"Section 1, Historical perspective","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In general, broiler chickens are vaccinated on day one through intraocular route followed by a booster on day 14 through drinking water."}}]},"avian-medicine--avian-nd--ตัวอย่างโปรแกรมวัคซีน-ไก่ไข่และไก่พ่อแม่พันธุ์":{"claims":[{"id":"avian-medicine--avian-nd--ตัวอย่างโปรแกรมวัคซีน-ไก่ไข่และไก่พ่อแม่พันธุ์--v1","statement":"ไก่ไข่ได้รับวัคซีนเชื้อเป็นก่อน แล้วตามด้วยวัคซีนเชื้อตายทาง intramuscular หรือ subcutaneous ตรงกับลำดับในโปรแกรมของสไลด์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-24589707","locator":"Section 1, Historical perspective","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Layers are vaccinated first with live vaccine followed by an inactivated vaccine via intramuscular or sub-cutaneous route."}},{"id":"avian-medicine--avian-nd--ตัวอย่างโปรแกรมวัคซีน-ไก่ไข่และไก่พ่อแม่พันธุ์--v2","statement":"ไก่ที่มีอายุการเลี้ยงยาว โดยเฉพาะไก่พ่อแม่พันธุ์เนื้อและไก่ไข่ มักได้รับวัคซีน ND หลายครั้ง สอดคล้องกับโปรแกรมหลายเข็มในสไลด์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-29073919","locator":"Domestic poultry, vaccination","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Long-lived birds, specifically broiler breeders and layers, are usually vaccinated multiple times for NDV"}}]},"avian-medicine--avian-nd--ถ้าเจอ-ndv-ในฟาร์มต้องทำอย่างไร":{"claims":[{"id":"avian-medicine--avian-nd--ถ้าเจอ-ndv-ในฟาร์มต้องทำอย่างไร--v1","statement":"มาตรการควบคุมเมื่อเกิดการระบาดรวมถึงการทำลายฝูงและการฆ่าเชื้อ ซึ่งเป็นส่วนสำคัญของต้นทุนความเสียหาย นอกเหนือจากการสูญเสียผลผลิตและข้อจำกัดทางการค้า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-29073919","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the cost of control measures such as depopulation and disinfection measures, and the trade restrictions that would likely be imposed as a result of an outbreak"}},{"id":"avian-medicine--avian-nd--ถ้าเจอ-ndv-ในฟาร์มต้องทำอย่างไร--v2","statement":"ND อยู่ภายใต้การควบคุมอย่างเป็นทางการในประเทศส่วนใหญ่ และประเทศที่ไม่มีห้องปฏิบัติการที่เหมาะสมควรส่งตัวอย่างไปยัง WOAH Reference Laboratory ซึ่งเป็นขั้นตอนที่สไลด์ไม่ได้กล่าวถึง","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section A. Introduction, p. 3","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"ND... is subject to official control in most countries... Countries lacking access to appropriate laboratory facilities should send specimens to a WOAH Reference Laboratory for the disease."}}]},"avian-medicine--avian-nd--please-keep-in-mind-ประเด็นที่อาจารย์ย้ำปิดท้าย":{"claims":[{"id":"avian-medicine--avian-nd--please-keep-in-mind-ประเด็นที่อาจารย์ย้ำปิดท้าย--v1","statement":"วัคซีนการค้าส่วนใหญ่ออกแบบมาเพื่อควบคุมอาการทางคลินิก แต่ไม่ได้ป้องกันการเพิ่มจำนวนของไวรัส จึงไม่เหมาะกับการกำจัดโรค ตรงกับที่สไลด์ย้ำว่าวัคซีนป้องกันอาการและการตายได้ แต่ป้องกันการติดเชื้อไม่ได้","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section C.2.3.2, For control and eradication, p. 18","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Most commercial vaccines have been designed to control clinical signs however they do not prevent viral replication and are not suitable for eradication."}},{"id":"avian-medicine--avian-nd--please-keep-in-mind-ประเด็นที่อาจารย์ย้ำปิดท้าย--v2","statement":"แอนติบอดีจากแม่รบกวนการสร้างภูมิคุ้มกันแบบ active เมื่อให้วัคซีนเชื้อเป็นทาง intramuscular, subcutaneous, intranasal, น้ำดื่ม และ aerosol โดยในไก่ที่มี maternal immunity การตอบสนองดีที่สุดได้จากการหยอดตาและหยอดจมูก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28024856","locator":"Discussion, maternal antibodies","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Presence of maternal antibodies interferes with the development of active immunity when live vaccines are administered via intramuscular, subcutaneous, intranasal route, in drinking water, and through aerosol."}},{"id":"avian-medicine--avian-nd--please-keep-in-mind-ประเด็นที่อาจารย์ย้ำปิดท้าย--v3","statement":"ลูกไก่ได้รับการปกป้องจากแอนติบอดีของแม่ประมาณ 3-4 สัปดาห์ ซึ่งยับยั้งการเกิด viraemia ที่รุนแรง แต่ลูกไก่ยังไวต่อการติดเชื้อในระบบหายใจ ซึ่งอธิบายช่วง protection gap ในกราฟของสไลด์","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2019","locator":"Prevention and Control, Medical prophylaxis","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Chicks are protected by maternal antibodies for 3-4 weeks, which inhibits the development of a robust viraemia, but they are still susceptible to respiratory infection."}}]},"avian-medicine--avian-nd--ชนิดของ-swab-และวิธีใช้":{"claims":[{"id":"avian-medicine--avian-nd--ชนิดของ-swab-และวิธีใช้--v1","statement":"WOAH ระบุว่าชนิดของ swab มีผลต่อ sensitivity และ validity ของการตรวจ และแนะนำให้ใช้ swab ที่มีก้าน (shaft) เป็นลวดบางหรือพลาสติกเป็นหลัก ดังนั้นก้านไม้ (wooden shaft) จึงไม่ใช่ชนิดที่แนะนำ สอดคล้องกับที่สไลด์ให้จัดการก้านไม้ต่างจาก Rayon หรือ Dacron","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section B.1.1 Samples for virus isolation, p. 4","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Further the type of swabs used may affect test sensitivity or validity with thin wire or plastic shafted swabs preferred."}}]},"avian-medicine--avian-nd--การเก็บรักษาตัวอย่างตามวิธีตรวจ-virus-culture-vs-molecular":{"claims":[{"id":"avian-medicine--avian-nd--การเก็บรักษาตัวอย่างตามวิธีตรวจ-virus-culture-vs-molecular--v1","statement":"WOAH ระบุว่าน้ำยาที่ใช้ขนส่ง swab สำหรับการแยกเชื้อ (virus isolation) ต้องมีโปรตีนเพื่อ stabilise ตัวไวรัส เช่น brain-heart infusion, cattle serum ไม่เกิน 5% (v/v), bovine albumen 0.5% (w/v) หรือ transport media เชิงพาณิชย์ ตรงกับที่สไลด์ให้ใส่ตัวอย่างใน Viral Transport Media (VTM)","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section B.1.1 Samples for virus isolation, p. 4","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"It is recommended that a solution for transport of the swabs should contain protein to stabilise the virus (e.g. brain-heart infusion, up to 5% [v/v] cattle serum, 0.5% [w/v] bovine albumen or similar commercially available transport media)"}},{"id":"avian-medicine--avian-nd--การเก็บรักษาตัวอย่างตามวิธีตรวจ-virus-culture-vs-molecular--v2","statement":"WOAH ระบุว่าการเก็บระยะยาวสำหรับตัวอย่างวินิจฉัยและ isolate ต้องเก็บที่ ลบ 80 องศาเซลเซียส และขนส่งด้วย dry ice (ไม่เกิน ลบ 50 องศาเซลเซียส) พร้อมทั้งต้องเลี่ยงการ freeze-thaw ซ้ำ ซึ่งสนับสนุนที่สไลด์บอกว่าไม่แนะนำให้เก็บตัวอย่างสำหรับ virus culture ไว้ในช่องแช่แข็งธรรมดา (ลบ 20 องศาเซลเซียส)","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section B.1.1 Samples for virus isolation, p. 4","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"For prolonged storage, diagnostic samples and isolates should be kept at -80°C but for transport on dry ice (≤-50°C) is widely used. Repeated freezing and thawing should be avoided."}}]},"avian-medicine--avian-nd--เชื้อ-และเกณฑ์แบ่ง-pathotype-ตาม-woah":{"claims":[{"id":"avian-medicine--avian-nd--เชื้อ-และเกณฑ์แบ่ง-pathotype-ตาม-woah--v1","statement":"ตัวย่อสากลของเชื้อโรคนิวคาสเซิลคือ APMV-1 (avian paramyxovirus type 1) จัดอยู่ใน genus Orthoavulavirus วงศ์ Paramyxoviridae ซึ่งยืนยันคำเตือนของสรุปว่าตัวย่อที่พิมพ์ผิดเป็น AMPV-1 นั้นชนกับ avian metapneumovirus","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Summary, Description of the disease, p. 1","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Newcastle disease (ND) is caused by virulent strains of avian paramyxovirus type 1 (APMV-1), also known as Newcastle disease virus (NDV), of the genus Orthoavulavirus."}},{"id":"avian-medicine--avian-nd--เชื้อ-และเกณฑ์แบ่ง-pathotype-ตาม-woah--v2","statement":"ไวรัสนิวคาสเซิลเป็น paramyxovirus ที่มีเปลือกหุ้ม (enveloped) และมีจีโนมเป็น negative-sense single-stranded RNA ตรงกับที่สรุประบุว่าเป็น enveloped ssRNA virus","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Aetiology, Classification of the causative agent","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Newcastle Disease (ND) virus is a paramyxovirus in the genus Avulavirus (pleomorphic, enveloped, negative-sense single-stranded RNA)."}},{"id":"avian-medicine--avian-nd--เชื้อ-และเกณฑ์แบ่ง-pathotype-ตาม-woah--v3","statement":"ในอดีตเคยใช้ mean death time ในไข่และ intravenous pathogenicity test แต่ตามข้อตกลงระหว่างประเทศ การประเมินความรุนแรงของไวรัสอย่างเป็นทางการอาศัย intracerebral pathogenicity index (ICPI) ซึ่งยืนยันว่าปัจจุบันใช้ ICPI ตามที่สรุประบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section B.1.4 Pathogenicity index, p. 6","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In the past, tests including the mean death time in eggs, the intravenous pathogenicity test... have been used, but by international agreement, a definitive assessment of virus virulence is based on the intracerebral pathogenicity test (ICP"}},{"id":"avian-medicine--avian-nd--เชื้อ-และเกณฑ์แบ่ง-pathotype-ตาม-woah--v4","statement":"การทำ ICPI ฉีดไวรัสเข้าสมองลูกไก่ SPF อายุมากกว่า 24 ชั่วโมงแต่ไม่เกิน 40 ชั่วโมง จำนวน 10 ตัว สังเกต 8 วัน และเชื้อที่มีค่า ICPI ตั้งแต่ 0.7 ขึ้นไปถือว่ารุนแรง","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section B.1.4.1 Intracerebral pathogenicity index, p. 6","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"These chicks must be over 24-hours and under 40-hours old at the time of inoculation... Any score of 0.7 or above is considered virulent."}},{"id":"avian-medicine--avian-nd--เชื้อ-และเกณฑ์แบ่ง-pathotype-ตาม-woah--v5","statement":"IVPI ถูกใช้เป็นเกณฑ์กำหนดความรุนแรงของเชื้อไข้หวัดนกจริงตามที่สรุประบุ โดย WOAH ใช้ IVPI มากกว่า 1.2 ในไก่ที่ไวรับ แต่ระบุช่วงอายุไก่ไว้ที่ 4 ถึง 8 สัปดาห์ ไม่ใช่ 6 สัปดาห์เจาะจงอย่างที่สรุปเขียน","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Summary, Detection of the agent, p. 1","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"inoculation of 10 susceptible 4- to 8-week-old chickens resulting in an intravenous pathogenicity index (IVPI) of greater than 1.2."}}]},"avian-medicine--avian-nd--โฮสต์และการติดต่อ":{"claims":[{"id":"avian-medicine--avian-nd--โฮสต์และการติดต่อ--v1","statement":"APMV-1 มีช่วงโฮสต์กว้างมาก โดยพบว่าติดเชื้อได้ในนกมากกว่า 200 ชนิด (เอกสารเทคนิคของ WOAH ระบุมากกว่า 250 ชนิดใน 27 อันดับ) ตรงกับที่สรุประบุว่าพบได้ในนกหลายชนิด","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Summary, Description of the disease, p. 1","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"APMV-1 has been shown to be able to infect over 200 species of birds, but the severity of disease produced varies with both host and strain of virus."}},{"id":"avian-medicine--avian-nd--โฮสต์และการติดต่อ--v2","statement":"APMV-1 ติดคนได้ โดยอาการที่พบบ่อยที่สุดคือเยื่อบุตาอักเสบ ซึ่งเกิดภายใน 24 ชั่วโมงหลังเชื้อรุนแรงเข้าตา อาการไม่รุนแรงถึงชีวิตและไม่มีหลักฐานการติดจากคนสู่คน","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section A, zoonotic aspects, p. 3","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"APMV-1 may infect humans where the most common sign of infection is conjunctivitis that develops within 24 hours of virulent APMV-1 exposure to the eye."}},{"id":"avian-medicine--avian-nd--โฮสต์และการติดต่อ--v3","statement":"เชื้อสายพันธุ์ velogenic มีอัตราการตายอยู่ในช่วง 50 ถึง 100 เปอร์เซ็นต์ ขึ้นกับ tropism ของไวรัส ชนิดโฮสต์ และสถานะการทำวัคซีน จึงสอดคล้องกับที่สรุประบุว่าสูงถึง 100 เปอร์เซ็นต์ในฝูงที่ไม่ได้ทำวัคซีน","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Diagnosis, Clinical diagnosis","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Velogenic strains have mortality rates ranging from 50-100% depending on virus tropism, host species, and vaccination status."}},{"id":"avian-medicine--avian-nd--โฮสต์และการติดต่อ--v4","statement":"การติดต่อของ NDV เกิดจากการสัมผัสโดยตรงระหว่างนกผ่านการหายใจเอาละอองฝอยเข้าไป และผ่านสิ่งปนเปื้อน โดยนกที่รอดชีวิตขับเชื้อออกทางสารคัดหลั่งระบบหายใจและอุจจาระได้นานเป็นสัปดาห์ถึงเป็นเดือน","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Epidemiology, Transmission and Sources","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Direct contact between birds via inhalation of aerosols... Birds that survive infection secrete and excrete virus in respiratory secretions and faeces for weeks to months."}},{"id":"avian-medicine--avian-nd--โฮสต์และการติดต่อ--v5","statement":"ไวรัสความรุนแรงต่ำถูกจำกัดให้เพิ่มจำนวนได้เฉพาะในเซลล์บางชนิด โดยเฉพาะเซลล์เยื่อบุผิวของทางเดินหายใจและทางเดินอาหาร ซึ่งสนับสนุนว่า target cell ของ NDV คือ epithelial cell ของสองระบบนี้","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section B.1.5 Molecular basis for pathogenicity, p. 7","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"restriction of these viruses to growth only in certain host-cell types, such as epithelial cells of the respiratory and gastrointestinal tracts."}}]},"avian-medicine--avian-nd--การวินิจฉัยและการเก็บตัวอย่าง":{"claims":[{"id":"avian-medicine--avian-nd--การวินิจฉัยและการเก็บตัวอย่าง--v1","statement":"ในสัตว์มีชีวิตควรเก็บทั้ง tracheal หรือ oropharyngeal swab และ cloacal swab เนื่องจากเชื้อ APMV-1 แต่ละสายพันธุ์มี tropism ต่างกัน จึงแนะนำให้เก็บทั้งสองแบบ ไม่ใช่เลือกอย่างใดอย่างหนึ่ง","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Sections B.1.1 and B.1.9, pp. 4 and 9","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Strains of APMV-1 can have differential tropisms so it is recommended to collect and test both oropharyngeal and cloacal swabs when using this sample type."}},{"id":"avian-medicine--avian-nd--การวินิจฉัยและการเก็บตัวอย่าง--v2","statement":"ตัวอย่างจากซากควรเก็บ caecal tonsil ร่วมกับปอด ถุงลม ลำไส้ ม้าม ไต สมอง ตับและหัวใจ โดยเมื่อทำ pooled sample ต้องเก็บและตรวจสมองแยกต่างหากเพื่อเลี่ยงการปนเปื้อนข้ามเนื้อเยื่อ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section B.1.1 Samples for virus isolation, p. 4","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Samples from lungs, air sacs, intestine, spleen, kidneys, caecal tonsils, brain, liver and heart should also be collected and processed either separately or as a pool."}},{"id":"avian-medicine--avian-nd--การวินิจฉัยและการเก็บตัวอย่าง--v3","statement":"การวินิจฉัยแยกโรคของ ND ได้แก่ ไข้หวัดนกชนิดรุนแรง (HPAI), laryngotracheitis (ILT) และ fowl cholera ตรงกับรายการที่สรุประบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Diagnosis, Differential diagnoses","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Highly pathogenic avian influenza; Laryngotracheitis; Fowl cholera."}},{"id":"avian-medicine--avian-nd--การวินิจฉัยและการเก็บตัวอย่าง--v4","statement":"ในการตรวจทางซีรัมวิทยาของ ND การทดสอบ haemagglutination inhibition (HI) ถูกใช้แพร่หลายที่สุด และ ELISA ก็มีที่ใช้เช่นกัน โดยมีชุดตรวจเชิงพาณิชย์หลายชนิด","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Summary, Serological tests, p. 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The haemagglutination inhibition (HI) test is used most widely in ND serology... Enzyme-linked immunosorbent assays also have a place."}}]},"avian-medicine--avian-nd--การทำลายเชื้อ-วัคซีน-และโปรแกรม":{"claims":[{"id":"avian-medicine--avian-nd--การทำลายเชื้อ-วัคซีน-และโปรแกรม--v1","statement":"สารเคมีที่ทำลายเชื้อ NDV ได้แก่ sodium hypochlorite, phenols, glutaraldehyde, chlorhexidine และสารออกซิไดซ์ ส่วน quaternary ammonium ต้องใช้ร่วมกับ sodium carbonate และ ether กับ formalin ก็ทำลายไวรัสได้","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Aetiology, Chemicals/Disinfectants","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Sodium hypochlorite, phenols, glutaraldehyde, chlorhexidine, and oxidising agents; quaternary ammonium compounds must be used in conjunction with sodium carbonate; ethers and formalin also deactivate the virus."}},{"id":"avian-medicine--avian-nd--การทำลายเชื้อ-วัคซีน-และโปรแกรม--v2","statement":"วัคซีน ND เชื้อเป็นใช้ไวรัสความรุนแรงต่ำ (lentogenic) หรือปานกลาง (mesogenic) และให้ได้หลายเส้นทาง ส่วนวัคซีนเชื้อตายให้โดยฉีดเข้ากล้ามหรือใต้ผิวหนัง และมักผลิตโดย emulsify กับน้ำมันแร่หรือน้ำมันพืช","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Summary, Requirements for vaccines, p. 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Inactivated vaccines are given intramuscularly or subcutaneously... Most inactivated vaccines are prepared for use by emulsification with a mineral or vegetable oil."}},{"id":"avian-medicine--avian-nd--การทำลายเชื้อ-วัคซีน-และโปรแกรม--v3","statement":"วัคซีน ND ชนิด recombinant ที่ได้รับการอนุมัติแล้วใช้ viral vector เช่น turkey herpesvirus (HVT) หรือ fowl poxvirus โดยแสดงออกยีน HN, ยีน F หรือทั้งสองยีน ตรงกับ HVT-ND และ Fowl Pox-ND ที่สรุประบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Summary, Requirements for vaccines, p. 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Recombinant Newcastle disease vaccines using viral vectors such as turkey herpesvirus or fowl poxvirus in which the HN gene, F gene or both are expressed have recently been developed and approved."}}]},"avian-medicine--avian-nd--อาการและรอยโรค-แยกตาม-3-ระบบ":{"claims":[{"id":"avian-medicine--avian-nd--อาการและรอยโรค-แยกตาม-3-ระบบ--v1","statement":"IBV ทำให้เยื่อบุจมูกและหลอดลมสูญเสียเซลล์ที่มี cilia อย่างรวดเร็ว การกวาดเมือกด้วย cilia จึงเสียไป และไก่ถูกเปิดช่องให้ติดเชื้อแบคทีเรียแทรกซ้อน ตรงกับที่สไลด์ระบุว่า cilia หรือ epithelial ของหลอดลมตายจึงเกิด secondary infection ได้ง่าย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35068104","locator":"Abstract, respiratory tract section","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Infection of the nasal and tracheal mucosa causes a rapid loss of ciliated epithelium and impaired mucociliary clearance that predispose chickens to secondary bacterial infections."}},{"id":"avian-medicine--avian-nd--อาการและรอยโรค-แยกตาม-3-ระบบ--v2","statement":"การติดเชื้อ IBV ที่ระบบสืบพันธุ์ในช่วง 2 สัปดาห์แรกของชีวิตทำให้เยื่อบุท่อนำไข่เนื้อตายและเกิดพังผืด กลายเป็นท่อนำไข่ที่เป็นถุงน้ำเรื้อรัง ทำให้สร้างไข่ไม่ได้เมื่อไก่โตเต็มวัย (false layer) ตรงกับที่สไลด์ระบุว่ามักเป็นเมื่อติดเชื้ออายุน้อยกว่า 2 สัปดาห์ ส่วนการติดเชื้อในแม่ไก่ที่โตแล้วทำให้คุณภาพไข่แย่ลงและไข่หยุดชั่วคราวเท่านั้น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35068104","locator":"Abstract, reproductive tract section","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Viral infection of the female reproductive tract in the first 2 weeks of life causes necrosis and scarring of the oviduct mucosa, resulting in a chronic cystic oviduct that precludes egg formation when the hen matures."}},{"id":"avian-medicine--avian-nd--อาการและรอยโรค-แยกตาม-3-ระบบ--v3","statement":"IBV สายพันธุ์ nephrotropic ทำให้ไตเกิดโรครุนแรง มีเนื้อตายของเซลล์เยื่อบุท่อไต การอักเสบ และไตวาย ซึ่งเป็นที่มาของภาพไตบวมซีดและ urate คั่งในท่อไตตามที่สไลด์บรรยาย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35068104","locator":"Abstract, kidney section","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Nephrotropic IBV causes severe disease in the kidney with necrosis of tubular epithelial cells, inflammation, and renal failure."}}]},"avian-medicine--avian-nd--ndv-มี-5-pathotypes-สรุปรุ่นพี่-85":{"claims":[{"id":"avian-medicine--avian-nd--ndv-มี-5-pathotypes-สรุปรุ่นพี่-85--v1","statement":"การแบ่ง NDV ตามอาการทางคลินิกเป็น 5 pathotype คือ viscerotropic velogenic, neurotropic velogenic, mesogenic, lentogenic และ asymptomatic enteric เป็นการจำแนกที่ใช้กันจริง โดย viscerotropic velogenic ก่อรอยโรคเลือดออกในทางเดินอาหาร ส่วน lentogenic และ asymptomatic enteric เป็นกลุ่มที่นำมาใช้ทำวัคซีนเชื้อเป็น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-24589707","locator":"Section on pathotypes","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"NDV strains are grouped into five pathotypes based on clinical signs in infected chickens: viscerotropic velogenic, neurotropic velogenic, mesogenic, lentogenic and asymptomatic enteric."}}]}},"avian-medicine--avian-pox":{"avian-medicine--avian-pox--ภาพรวมโรคฝีดาษไก่-fowlpox":{"claims":[{"id":"avian-medicine--avian-pox--ภาพรวมโรคฝีดาษไก่-fowlpox--v1","statement":"Fowlpox เป็นโรคของไก่และไก่งวง เกิดจาก DNA virus ใน genus Avipoxvirus family Poxviridae กระจายทั่วโลก และมีลักษณะเด่นคือ slow-spreading (แพร่ระบาดช้า) มีรอยโรคแบบ proliferative และสะเก็ดที่ผิวหนัง ร่วมกับ diphtheritic lesion ที่ทางเดินอาหารและทางเดินหายใจส่วนต้น","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Summary, Description of the disease, p. 1","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Fowlpox is a disease of chickens and turkeys caused by a DNA virus of the genus Avipoxvirus of the family Poxviridae. Its distribution is world-wide. It is slow-spreading and characterised by the formation of proliferative lesions and scabs"}},{"id":"avian-medicine--avian-pox--ภาพรวมโรคฝีดาษไก่-fowlpox--v2","statement":"Avipoxvirus ไม่ได้จำกัดที่ไก่และไก่งวงเท่านั้น แต่ก่อโรค pox ในนกอย่างน้อย 232 ชนิด ครอบคลุม 23 อันดับ (orders) ซึ่งรวมนกสวยงามหลายชนิดตามที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35458503","locator":"Introduction, paragraph 2","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"APV strains are known to cause pox disease in at least 232 bird species and 23 orders."}},{"id":"avian-medicine--avian-pox--ภาพรวมโรคฝีดาษไก่-fowlpox--v3","statement":"เชื้อทนต่อสภาพแวดล้อมและอยู่รอดในสะเก็ดแห้ง (dried scabs) ได้นาน ซึ่งเป็นเหตุผลที่ต้องพักเล้าและทำความสะอาดให้นานพอ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-merck-co-inc-merck-vet-2025","locator":"Etiology and Epidemiology of Fowlpox in Chickens and Turkeys","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The large DNA virus present in fowlpox lesions ... is resistant to normal environment and may survive for extended periods in dried scabs."}},{"id":"avian-medicine--avian-pox--ภาพรวมโรคฝีดาษไก่-fowlpox--v4","statement":"โรคคงอยู่ในฟาร์มที่เลี้ยงไก่หลายอายุ (multiple-age complexes) ได้นาน เพราะเชื้อแพร่ช้า จึงเป็นเหตุผลที่แนะนำให้เลี้ยงไก่อายุเดียวกันแบบ all in - all out","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-merck-co-inc-merck-vet-2025","locator":"Etiology and Epidemiology of Fowlpox in Chickens and Turkeys","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The disease tends to persist for extended periods in multiple-age poultry complexes because of slow spread of the virus."}}]},"avian-medicine--avian-pox--ประวัติช่วงแรกของโรคฝีดาษไก่":{"claims":[{"id":"avian-medicine--avian-pox--ประวัติช่วงแรกของโรคฝีดาษไก่--v1","statement":"Bollinger bodies คือ intracytoplasmic inclusion body ขนาดใหญ่ที่เกิดใน cytoplasm ของ epithelial cell และภายในบรรจุ elementary bodies ขนาดเล็กกว่าคือ Borrel bodies ซึ่งตรงกับที่สไลด์สอนว่า Borrel(l) bodies คืออนุภาคไวรัส ส่วน Bollinger bodies คือ inclusion body ที่ห่อไว้ (สะกดตามต้นฉบับคือ Borrel มีตัว l เดียว)","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Section B.1 Detection of the agent, p. 3","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"FPV multiplies in the cytoplasm of epithelial cells with the formation of large intracytoplasmic inclusion bodies (Bollinger bodies) that contain smaller elementary bodies (Borrel bodies)."}}]},"avian-medicine--avian-pox--เชื้อก่อโรคและการจัดจำแนก-fowlpox-virus":{"claims":[{"id":"avian-medicine--avian-pox--เชื้อก่อโรคและการจัดจำแนก-fowlpox-virus--v1","statement":"Fowlpox virus (FWPV) จัดอยู่ใน genus Avipoxvirus, subfamily Chordopoxvirinae, family Poxviridae ตรงตามลำดับ taxonomy ที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38801571","locator":"Abstract, opening sentence; Adv Exp Med Biol 1451:55-74","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The complex cytoplasmic DNA virus known as the fowlpox virus (FWPV) is a member of the avipoxvirus genus, Subfamily Chordopoxvirinae, and Family Poxviridae."}},{"id":"avian-medicine--avian-pox--เชื้อก่อโรคและการจัดจำแนก-fowlpox-virus--v2","statement":"Avipoxvirus มีจีโนมเป็น double-stranded DNA ขนาดใหญ่ อยู่ในเปลือกหุ้ม (envelope) รูปทรงรีหรือทรงอิฐ (brick-shaped) ตรงตามคุณสมบัติ Poxvirus ที่สไลด์ระบุว่าเป็นดีเอ็นเอสายคู่ มีเปลือกหุ้ม และเป็น brick-shape","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35458503","locator":"Introduction, paragraph 1","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"It is characterized by a large double-stranded DNA genome in an oval or brick-shaped envelope."}},{"id":"avian-medicine--avian-pox--เชื้อก่อโรคและการจัดจำแนก-fowlpox-virus--v3","statement":"Mature virion (elementary body) ของ fowlpox virus เป็นรูปทรงอิฐ ขนาดประมาณ 330 x 280 x 200 nm ประกอบด้วย biconcave core ที่มี lateral body สองข้าง ล้อมรอบด้วย envelope ซึ่งเป็นโครงสร้างเดียวกับที่ภาพ virion ในสไลด์แสดง","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Section A. Introduction, p. 1","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The mature virus (elementary body) is brick shaped and measures about 330 x 280 x 200 nm. ... The virion consists of an electron-dense centrally located biconcave core or nucleoid with two lateral bodies in each concavity and surrounded by "}}]},"avian-medicine--avian-pox--เซลล์เป้าหมาย-อวัยวะเป้าหมาย-การติดต่อ-และระยะฟักตัว":{"claims":[{"id":"avian-medicine--avian-pox--เซลล์เป้าหมาย-อวัยวะเป้าหมาย-การติดต่อ-และระยะฟักตัว--v1","statement":"เซลล์เป้าหมายของ fowlpox virus คือ epithelial cell โดยไวรัสเพิ่มจำนวนใน cytoplasm ของเซลล์เยื่อบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Section B.1 Detection of the agent, p. 3","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"FPV multiplies in the cytoplasm of epithelial cells with the formation of large intracytoplasmic inclusion bodies (Bollinger bodies)."}},{"id":"avian-medicine--avian-pox--เซลล์เป้าหมาย-อวัยวะเป้าหมาย-การติดต่อ-และระยะฟักตัว--v2","statement":"ทางติดต่อของ fowlpox ครบทั้งสามทางตามสไลด์ คือ ติดผ่านบาดแผล/รอยถลอกที่ผิวหนัง สะเก็ดที่หลุดจากไก่ที่กำลังหายกลายเป็นแหล่ง aerosol ให้ไก่ตัวอื่นหายใจเข้าไป และยุงกับแมลงดูดเลือดอื่นทำหน้าที่เป็น mechanical vector","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-merck-co-inc-merck-vet-2025","locator":"Etiology and Epidemiology of Fowlpox in Chickens and Turkeys","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The virus is usually transmitted by contact through abrasions of the skin. Skin lesions (scabs) shed from recovering birds in poultry houses can become a source of aerosol exposure for susceptible birds. Mosquitoes and other biting insects "}},{"id":"avian-medicine--avian-pox--เซลล์เป้าหมาย-อวัยวะเป้าหมาย-การติดต่อ-และระยะฟักตัว--v3","statement":"ระยะฟักตัวของ fowlpox ในไก่และไก่งวงอยู่ที่ 4-10 วัน ตรงกับตัวเลขที่สไลด์ระบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-merck-co-inc-merck-vet-2025","locator":"Clinical Findings and Lesions of Fowlpox in Chickens and Turkeys","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The incubation period for fowlpox in chickens and turkeys is typically 4-10 days."}}]},"avian-medicine--avian-pox--รูปแบบของโรค-2-forms":{"claims":[{"id":"avian-medicine--avian-pox--รูปแบบของโรค-2-forms--v1","statement":"การติดเชื้อ Avipoxvirus แบ่งได้เป็น cutaneous form (dry pox) ที่มี nodular proliferative lesion บนผิวหนังส่วนที่ไม่มีขน กับ diphtheritic form (wet pox) ที่มี fibrino-necrotic proliferative lesion ที่เยื่อเมือกทางเดินหายใจส่วนต้น ปาก หลอดอาหาร กล่องเสียง และท่อลม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35458503","locator":"Introduction, paragraph 3","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Infections can be classified as the cutaneous form (dry pox) with nodular proliferative lesions in nonfeathered areas of the body ... or the diphtheritic form (wet pox) with fibronecrotic proliferative lesions in the mucous membrane of the "}},{"id":"avian-medicine--avian-pox--รูปแบบของโรค-2-forms--v2","statement":"ไก่ตัวเดียวสามารถแสดงโรคได้มากกว่าหนึ่งรูปแบบพร้อมกัน ตรงกับที่สไลด์ระบุว่าอาจพบทั้ง 2 ฟอร์มในไก่ 1 ตัว โดยแหล่งอ้างอิงเพิ่ม systemic form เข้ามาเป็นรูปแบบที่สามด้วย","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-merck-co-inc-merck-vet-2025","locator":"Clinical Findings and Lesions of Fowlpox in Chickens and Turkeys","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"More than one form of the disease (cutaneous, diphtheritic, or systemic) may occur in a single bird."}}]},"avian-medicine--avian-pox--พยาธิกำเนิด-pathogenesis-เทียบ-2-form-ตาม-dpi":{"claims":[{"id":"avian-medicine--avian-pox--พยาธิกำเนิด-pathogenesis-เทียบ-2-form-ตาม-dpi--v1","statement":"ในไก่ที่ได้รับเชื้อทางผิวหนัง (intradermal) ตรวจพบไวรัสที่ผิวหนังตำแหน่งฉีดวันที่ 2 ที่ปอดวันที่ 4 แล้วเกิด viraemia วันที่ 5 post-infection ส่วนไก่ที่ได้รับเชื้อทางท่อลม (intratracheal) ตรวจพบไวรัสที่ปอดตั้งแต่วันที่ 2 และเกิด viraemia เร็วกว่าคือวันที่ 4 ตรงกับไทม์ไลน์ DPI ที่สไลด์วางไว้ทุกจุด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-2891281","locator":"Abstract; Acta Virol 31(5):417-423","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In intradermally infected chickens, the virus in titrable amounts was first detected in the skin at the inoculation site on day 2 and in lungs on day 4 followed by viraemia on the day 5 post-infection (p.i.). ... The chickens infected by i."}},{"id":"avian-medicine--avian-pox--พยาธิกำเนิด-pathogenesis-เทียบ-2-form-ตาม-dpi--v2","statement":"หลังเกิด viraemia สามารถแยกเชื้อไวรัสได้จาก ตับ ม้าม ไต และสมอง ตรงกับ 4 อวัยวะที่สไลด์สรุปไว้ในกรอบท้ายภาพ โดยแยกไม่ได้จากหัวใจ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-2891281","locator":"Abstract; Acta Virol 31(5):417-423","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Subsequently the virus was recovered from liver, spleen, kidney and brain, but not from the heart."}}]},"avian-medicine--avian-pox--อาการของ-cutaneous-form-dry-form":{"claims":[{"id":"avian-medicine--avian-pox--อาการของ-cutaneous-form-dry-form--v1","statement":"Cutaneous form มีอัตราการตายต่ำ และไก่ที่ป่วยมีโอกาสหายมากกว่า diphtheritic form ยกเว้นกรณีที่รอยโรคขึ้นรอบดวงตา ซึ่งจะทำให้อัตราการตายสูงขึ้น","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Summary, Description of the disease, p. 1; Section A. Introduction, p. 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In the case of the cutaneous form, the mortality rate is usually low, unless lesions develop around the eyes, and affected birds are more likely to recover than those with the diphtheritic form."}},{"id":"avian-medicine--avian-pox--อาการของ-cutaneous-form-dry-form--v2","statement":"Fowlpox ทำให้ผลผลิตไข่ลดลงชั่วคราว และอัตราการเจริญเติบโตในไก่เล็กลดลง ตรงกับที่สไลด์ระบุว่าไก่โตช้าและไข่ลด","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Summary, Description of the disease, p. 1","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Fowlpox causes a transient drop in egg production and a reduced growth rate in young birds."}},{"id":"avian-medicine--avian-pox--อาการของ-cutaneous-form-dry-form--v3","statement":"รอยโรคที่เปลือกตา จะงอยปาก และมุมปาก สัมพันธ์กับอัตราการตายที่สูงขึ้น เพราะรอยโรคเหล่านี้จำกัดการมองเห็นและความสามารถในการกินอาหาร ตรงกับที่สไลด์อธิบายว่าถ้ารอยโรคใกล้ตา ไก่จะมองไม่เห็นและกินน้ำกินอาหารลำบาก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35458503","locator":"Discussion, paragraph 3","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"a higher frequency of fatal cases has been seen with lesions in the eyelids, beaks, and mouth commissures in chickens ... These lesions limit vision and feeding ability."}}]},"avian-medicine--avian-pox--รอยโรคของ-cutaneous-form-dry-form":{"claims":[{"id":"avian-medicine--avian-pox--รอยโรคของ-cutaneous-form-dry-form--v1","statement":"รอยโรคของ cutaneous form คือ proliferative lesion ตั้งแต่ตุ่มเล็กจนถึงก้อนคล้ายหูดทรงกลม บนผิวหนังของหงอน เหนียง และส่วนที่ไม่มีขนอื่นๆ และการตรวจ histopathology พบ epithelial hyperplasia ตรงกับที่สไลด์เขียนว่า Discrete nodular proliferative lesion: epithelial hyperplasia","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Section A. Introduction, p. 2; Summary, Detection of the agent, p. 1","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"characterised in the cutaneous form (dry pox) by the development of proliferative lesions, ranging from small nodules to spherical wart-like masses on the skin of the comb, wattle and other unfeathered areas ... Histological examination of "}},{"id":"avian-medicine--avian-pox--รอยโรคของ-cutaneous-form-dry-form--v2","statement":"การดำเนินโรคตามธรรมชาติของ cutaneous form ชนิดไม่รุนแรงกินเวลา 3-4 สัปดาห์ ซึ่งสอดคล้องกับที่สไลด์ระบุว่ารอยโรคใช้เวลาประมาณ 2 สัปดาห์ แล้วสะเก็ดจึงค่อยลอกหลุดอีก 1-2 สัปดาห์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35458503","locator":"Discussion, paragraph 2","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The natural course of mild cutaneous infections in chickens persists three to four weeks."}},{"id":"avian-medicine--avian-pox--รอยโรคของ-cutaneous-form-dry-form--v3","statement":"ลำดับการเปลี่ยนแปลงของรอยโรคผิวหนังคือ เริ่มจากตุ่มนูนสีซีด แล้วขยายขนาด เปลี่ยนเป็นสีเหลือง และกลายเป็นสะเก็ดหนาสีเข้ม ตรงตามลำดับที่สไลด์ไล่ไว้ (ตุ่มขาวเล็ก เปลี่ยนเป็นสีเหลือง แล้วเปลี่ยนเป็นสีดำมีสะเก็ด)","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-merck-co-inc-merck-vet-2025","locator":"Clinical Findings and Lesions of Fowlpox in Chickens and Turkeys","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The lesion is initially a raised, blanched, nodular area that enlarges, becomes yellowish, and progresses to a thick, dark scab."}}]},"avian-medicine--avian-pox--อาการของ-diphtheritic-form-wet-form":{"claims":[{"id":"avian-medicine--avian-pox--อาการของ-diphtheritic-form-wet-form--v1","statement":"อัตราการตายของ diphtheritic form สูงกว่า cutaneous form และบางครั้งเข้าใกล้ 50 เปอร์เซ็นต์ โดยเฉพาะในไก่เล็ก (สไลด์เทียบเชิงเปรียบเทียบเท่านั้น แหล่งอ้างอิงให้ตัวเลขเพิ่ม)","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Section A. Introduction, p. 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The mortality rate is higher in the diphtheritic form than in the cutaneous form, sometimes nearing 50% particularly in young birds."}},{"id":"avian-medicine--avian-pox--อาการของ-diphtheritic-form-wet-form--v2","statement":"ใน diphtheritic form รอยโรค proliferative ที่โพรงจมูก ลิ้น กล่องเสียง หรือท่อลม ทำให้เกิดภาวะหายใจลำบาก (respiratory distress) และตายจากการขาดอากาศ (suffocation)","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Summary, Description of the disease, p. 1","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In the diphtheritic form, proliferative lesions involving the nasal passages, tongue, larynx or trachea can result in respiratory distress and death from suffocation."}}]},"avian-medicine--avian-pox--รอยโรคของ-diphtheritic-form-wet-form":{"claims":[{"id":"avian-medicine--avian-pox--รอยโรคของ-diphtheritic-form-wet-form--v1","statement":"รอยโรคของ diphtheritic form เริ่มจากตุ่มนูนเล็กสีขาวขุ่นบนเยื่อเมือก แล้วขยายขนาดอย่างรวดเร็วจนกลายเป็นแผ่นเยื่อสีเหลือง (yellowish diphtheritic membrane) ที่เยื่อเมือกของปาก ลิ้น หลอดอาหาร กล่องเสียง หรือท่อลม ตรงตามลำดับที่สไลด์ไล่ไว้","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Section A. Introduction, p. 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In the diphtheritic form (wet pox), slightly elevated white opaque nodules develop on the mucous membranes. They rapidly increase in size to become a yellowish diphtheritic membrane. Lesions occur on the mucous membranes of the mouth, tongu"}},{"id":"avian-medicine--avian-pox--รอยโรคของ-diphtheritic-form-wet-form--v2","statement":"รอยโรคของ diphtheritic form มีลักษณะ fibrino-necrotic ร่วมกับ proliferative ที่เยื่อเมือกของทางเดินหายใจส่วนต้น ปาก หลอดอาหาร กล่องเสียง และท่อลม ตรงตามคำนิยามรอยโรคหลักที่สไลด์เขียนไว้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35458503","locator":"Introduction, paragraph 3","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the diphtheritic form (wet pox) with fibronecrotic proliferative lesions in the mucous membrane of the upper respiratory tract, such as the mouth, esophagus, larynx, and trachea"}}]},"avian-medicine--avian-pox--การวินิจฉัย-diagnosis":{"claims":[{"id":"avian-medicine--avian-pox--การวินิจฉัย-diagnosis--v1","statement":"จุดชี้ขาดทาง histopathology คือ eosinophilic intracytoplasmic inclusion body (Bollinger bodies) ใน epithelial cell ซึ่งพบได้ทั้งในรอยโรคของสัตว์ป่วยและในรอยโรคบน chorioallantoic membrane หลังการเพาะแยกเชื้อ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Section B.1.2 Virus isolation, p. 3","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Histopathological examination of the CAM lesions will reveal eosinophilic intracytoplasmic inclusion bodies following staining with H&E."}},{"id":"avian-medicine--avian-pox--การวินิจฉัย-diagnosis--v2","statement":"การเพาะแยกเชื้อทำโดย inoculate ลงบน chorioallantoic membrane ของไข่ไก่ฟักอายุ 9-12 วัน หรือใน avian cell culture และไข่ที่ใช้ควรมาจากฝูงปลอดเชื้อ (specific pathogen free) ตรงกับที่สไลด์ระบุว่าเพาะแยกเชื้อในไก่ปลอดเชื้อ ไข่ไก่ฟัก และเซลล์เพาะเลี้ยง","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Summary, Detection of the agent, p. 1","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Virus isolation is done by inoculation on to chorioallantoic membranes of 9- to 12-day-old developing chicken embryos or avian cell cultures. Eggs from specific pathogen free flocks should be used for virus isolation."}},{"id":"avian-medicine--avian-pox--การวินิจฉัย-diagnosis--v3","statement":"Diphtheritic form ที่มีรอยโรคในท่อลมต้องวินิจฉัยแยกจาก infectious laryngotracheitis (ILT) ซึ่งเกิดจาก gallid herpesvirus-1 และแยกได้ด้วย inclusion body ที่อยู่ในนิวเคลียส (intranuclear) ต่างจาก fowlpox ที่อยู่ใน cytoplasm","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Summary, Detection of the agent, p. 1","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The diphtheritic form of fowlpox involving the trachea must be differentiated from infectious laryngotracheitis, which is caused by gallid herpesvirus-1 and is characterised by the presence of intranuclear inclusion bodies."}},{"id":"avian-medicine--avian-pox--การวินิจฉัย-diagnosis--v4","statement":"T-2 toxin สมควรเป็น differential diagnosis ของ diphtheritic form จริง เพราะไก่ที่ได้รับ T-2 toxin เกิดรอยโรคในช่องปากเป็นแผ่นสีเหลืองนูนแบบ caseous ที่ขอบจะงอยปาก เยื่อบุเพดานแข็ง มุมปาก และลิ้น ซึ่งหน้าตาคล้าย pseudodiphtheritic membrane ของฝีดาษไก่","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-605040","locator":"Abstract; Poult Sci 56(2):628-637","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Most hens fed T-2 toxin developed oral lesions: circumscribed proliferative yellow caseous plaques at the margin of the beak, mucosa of the hard palate and angle of the mouth, and tongue."}},{"id":"avian-medicine--avian-pox--การวินิจฉัย-diagnosis--v5","statement":"การขาด pantothenic acid หรือ biotin ในลูกไก่ทำให้เกิด dermatitis ที่มุมปาก ใต้จะงอยปาก รอบตา และที่เท้า โดยรายที่รุนแรงผิวหนังเท้าจะแข็งและเกิดก้อนคล้ายหูด ซึ่งเป็นเหตุผลที่ต้องวินิจฉัยแยกจาก cutaneous form ของฝีดาษไก่","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-merck-co-inc-merck-vet-2025","locator":"Pantothenic Acid Deficiency in Poultry; Biotin Deficiency in Poultry","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The corners of the beak and the area below the beak are usually the worst affected regions for dermatitis, but the condition is also noted on the feet. In severe cases, the skin of the feet may cornify, and wart-like lumps occur on the ball"}}]},"avian-medicine--avian-pox--การควบคุมและป้องกันโรค-ภาพรวม":{"claims":[{"id":"avian-medicine--avian-pox--การควบคุมและป้องกันโรค-ภาพรวม--v1","statement":"การควบคุมโรคฝีดาษไก่อาศัยสองเสาหลักคือการทำวัคซีนด้วยเชื้อ FPV สายพันธุ์ที่ทำให้อ่อนฤทธิ์ (หรือวัคซีน pigeon pox ที่มี antigen ใกล้เคียง) ร่วมกับการสุขาภิบาลที่เข้มงวด สอดคล้องกับที่สไลด์ไม่ได้กล่าวถึงการรักษาเลย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38801571","locator":"Abstract; Adv Exp Med Biol 1451:55-74","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"To control the illness, strict hygiene practices and immunization with FWPV attenuated strains or antigenically similar pigeon pox virus vaccines are employed."}},{"id":"avian-medicine--avian-pox--การควบคุมและป้องกันโรค-ภาพรวม--v2","statement":"การป้องกันโรคฝีดาษในสัตว์ปีกเชิงพาณิชย์ทำได้หลักๆ ด้วยวัคซีนป้องกันร่วมกับมาตรการสุขาภิบาลที่เข้มงวด เพื่อหลีกเลี่ยงพาหะทางชีวภาพและแหล่งปนเปื้อน ตรงกับสองหัวข้อ Vaccine และ Biosecurity ที่สไลด์วางไว้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35458503","locator":"Introduction, paragraph 5","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Prevention of pox disease in commercial birds is mainly achieved via prophylactic vaccines and strict sanitary measures to avoid biological vectors and contaminated sources."}}]},"avian-medicine--avian-pox--วัคซีนเชื้อเป็นและวิธีการให้วัคซีน":{"claims":[{"id":"avian-medicine--avian-pox--วัคซีนเชื้อเป็นและวิธีการให้วัคซีน--v1","statement":"วัคซีนเชื้อเป็นสำหรับฝีดาษไก่มีทั้งชนิดที่ผลิตจากไข่ไก่ฟัก (chicken embryo origin) และจากเซลล์เพาะเลี้ยง (cell culture origin) ตรงกับสองชนิดที่สไลด์ระบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Section C.1 Background, p. 5","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Fowlpox and pigeonpox virus vaccines (Winterfield & Hitchner, 1965) of chicken embryo or cell culture origin are available from the majority of biological companies that produce poultry vaccines."}},{"id":"avian-medicine--avian-pox--วัคซีนเชื้อเป็นและวิธีการให้วัคซีน--v2","statement":"วิธีให้วัคซีนที่เป็นมาตรฐานคือ wing web stab (แทงปีก) และวัคซีนต้องพิสูจน์ความปลอดภัยผ่านทางนี้ในไก่ทุกอายุที่ไวต่อโรค","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Section C.2.1.3 Validation as a vaccine, Safety, p. 6","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The vaccine must be shown to be safe by the recommended route of administration, which is wing web stab, in all ages of susceptible birds."}},{"id":"avian-medicine--avian-pox--วัคซีนเชื้อเป็นและวิธีการให้วัคซีน--v3","statement":"ไม่แนะนำให้ทำวัคซีนในไก่ที่กำลังให้ไข่ ตรงกับข้อห้ามที่สไลด์ระบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Section C.2.3.2 Precautions (hazards), p. 7","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"It is usually recommended not to vaccinate birds that are in lay."}},{"id":"avian-medicine--avian-pox--วัคซีนเชื้อเป็นและวิธีการให้วัคซีน--v4","statement":"โปรแกรมวัคซีนที่แนะนำในพื้นที่เสี่ยงสูงคือให้วัคซีนเชื้อเป็นชนิด cell-culture origin ในช่วงไม่กี่สัปดาห์แรกหลังฟัก แล้วให้ซ้ำที่อายุ 12-16 สัปดาห์ ซึ่งตรงกับช่วง 4-8 สัปดาห์ก่อนเริ่มไข่ตามที่สไลด์ระบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-merck-co-inc-merck-vet-2025","locator":"Prevention and Control of Fowlpox in Chickens and Turkeys","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In high-risk areas, vaccination with a live, attenuated virus vaccine of cell-culture origin in the first few weeks after hatching and revaccination at 12-16 weeks old is often sufficient."}}]},"avian-medicine--avian-pox--recombinant-vaccine":{"claims":[{"id":"avian-medicine--avian-pox--recombinant-vaccine--v1","statement":"Fowlpox virus ถูกใช้เป็น vector จริง โดยวัคซีน recombinant poxvirus ที่มีขายมี gene insert ของ ILTV, Mycoplasma gallisepticum, avian influenza H5 และ Newcastle disease virus และให้ความคุ้มโรคทั้งต่อ FPV ที่เป็น vector และต่อเชื้อเจ้าของยีนที่ใส่เข้าไป ตรงกับหลักการที่สไลด์อธิบาย","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Section C.1 Background, p. 5","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The recombinant poxvirus vaccines include gene inserts for pox-ILTV, Mycoplasma gallisepticum (pox-MG), avian influenza H5 (Pox-AIV), or Newcastle disease virus (pox-NDV) ... These recombinant vaccines provide protection against the FPV vec"}},{"id":"avian-medicine--avian-pox--recombinant-vaccine--v2","statement":"Recombinant fowlpox virus ที่แสดงออกยีน glycoprotein B (gB) ของ ILTV ป้องกันไก่จากการติดเชื้อ ILT ได้จริง โดย rFPV-gB ให้ความคุ้มโรค 100 เปอร์เซ็นต์ต่อสายพันธุ์ ILTV ที่ระบาดเด่น เทียบกับวัคซีน rFPV เชิงพาณิชย์ที่ให้ 83.3 เปอร์เซ็นต์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-33105740","locator":"Abstract, Results; Vaccines 8(4):623","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the rFPV-gB provided a 100% protection in immunized chickens against the challenge of predominant ILTV strains that were screened by pathogenicity assay when compared with the commercialized rFPV vaccine, which only provided 83.3%."}}]},"avian-medicine--avian-pox--การตรวจสอบผลการให้วัคซีนที่-wing-web":{"claims":[{"id":"avian-medicine--avian-pox--การตรวจสอบผลการให้วัคซีนที่-wing-web--v1","statement":"ลักษณะของ take ที่บ่งชี้ว่าวัคซีนได้ผลคือผิวหนังบวมนูนหรือมีสะเก็ดที่ตำแหน่งที่ให้วัคซีน ตรงกับตุ่มนูนแข็งบริเวณที่ให้วัคซีนตามที่สไลด์อธิบาย","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Section B.2 Serological tests, p. 4","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"A take consists of a swelling of the skin or a scab at the site where the vaccine was applied and its presence is evidence of successful immunisation."}},{"id":"avian-medicine--avian-pox--การตรวจสอบผลการให้วัคซีนที่-wing-web--v2","statement":"การเฝ้าติดตามผลวัคซีนด้วยการอ่าน take ที่ตำแหน่ง wing web เป็นวิธีที่ใช้ในฟาร์มพ่อแม่พันธุ์จริง และสัดส่วนของไก่ที่ขึ้น take มีรายงานว่าแปรผันตามระดับ antibody titer จึงใช้เป็นตัวชี้วัดความสำเร็จของการทำวัคซีนได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35458503","locator":"Results 3.1; Discussion","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Regarding the fowlpox virus vaccination, it was carried out using the wing web method. Evaluation of vaccination success was monitored by observing 'takes' at the site where the vaccine was inoculated. ... it has been reported that the perc"}}]},"avian-medicine--avian-pox--biosecurity-and-management":{"claims":[{"id":"avian-medicine--avian-pox--biosecurity-and-management--v1","statement":"ไวรัสฝีดาษไก่คงทนในสิ่งแวดล้อมของโรงเรือนสัตว์ปีกได้นานกว่าไวรัสชนิดอื่นหลายชนิด ซึ่งรองรับข้อกำหนดเรื่องทำความสะอาดและพักเล้าให้นานพอตามที่สไลด์ระบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Section A. Introduction, p. 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the virus tends to persist in the poultry environment for extended periods of time where other viruses may not survive"}},{"id":"avian-medicine--avian-pox--biosecurity-and-management--v2","statement":"การแพร่เชื้อภายในฝูงที่ไวต่อโรคจะเกิดอย่างรวดเร็วเมื่อมียุงชุกชุม จึงเป็นเหตุผลรองรับมาตรการกำจัดยุงและแหล่งเพาะพันธุ์ยุงตามที่สไลด์ระบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-merck-co-inc-merck-vet-2025","locator":"Etiology and Epidemiology of Fowlpox in Chickens and Turkeys","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Mosquitoes and other biting insects may serve as mechanical vectors. Transmission within a susceptible flock is rapid when mosquitoes are plentiful."}},{"id":"avian-medicine--avian-pox--biosecurity-and-management--v3","statement":"โรคคงอยู่นานในฟาร์มที่เลี้ยงไก่หลายอายุเพราะเชื้อแพร่ช้า ซึ่งเป็นเหตุผลเชิงระบาดวิทยาที่รองรับการเลี้ยงไก่อายุเดียวกันแบบ all in - all out ตามที่สไลด์ระบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-merck-co-inc-merck-vet-2025","locator":"Etiology and Epidemiology of Fowlpox in Chickens and Turkeys","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The disease tends to persist for extended periods in multiple-age poultry complexes because of slow spread of the virus."}}]},"avian-medicine--avian-pox--เชื้อและการติดต่อ":{"claims":[{"id":"avian-medicine--avian-pox--เชื้อและการติดต่อ--v1","statement":"Fowlpox เกิดจาก DNA virus ใน genus Avipoxvirus วงศ์ Poxviridae โดยไวรัสตัวเต็มวัย (elementary body) มีรูปร่างเหมือนก้อนอิฐ ขนาดราว 330 x 280 x 200 นาโนเมตร และมีเปลือกหุ้ม ตรงกับที่สรุประบุว่า enveloped dsDNA virus รูปร่าง brick-shape","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Section A. Introduction, p. 1","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The mature virus (elementary body) is brick shaped and measures about 330 x 280 x 200 nm... surrounded by an envelope."}},{"id":"avian-medicine--avian-pox--เชื้อและการติดต่อ--v2","statement":"การติดต่อของ fowlpox มักสัมพันธ์กับการปนเปื้อนของบาดแผลเปิดและจากแมลงดูดเลือด เช่น ยุงและไรแดง (Dermanyssus gallinae) ตรงกับที่สรุประบุว่าแมลงและยุงเป็นพาหะและติดเชื้อเข้าทางบาดแผล","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Section A. Introduction, p. 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Infection is generally associated with contamination of open wounds and via biting insects such as mosquitos and poultry red mites (Dermanyssus gallinae)."}},{"id":"avian-medicine--avian-pox--เชื้อและการติดต่อ--v3","statement":"Fowlpox เป็นโรคไวรัสที่แพร่ระบาดช้าในไก่และไก่งวง และไวรัสมีแนวโน้มคงอยู่ในสภาพแวดล้อมของฟาร์มสัตว์ปีกได้นานกว่าไวรัสอื่น ๆ ซึ่งสนับสนุนทั้งข้อที่ว่าแพร่ช้าและสะเก็ดอยู่ในโรงเรือนได้นาน","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Section A. Introduction, pp. 1-2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Fowlpox is a slow-spreading virus disease of chickens and turkeys... the virus tends to persist in the poultry environment for extended periods of time where other viruses may not survive."}},{"id":"avian-medicine--avian-pox--เชื้อและการติดต่อ--v4","statement":"ไวรัส fowlpox เพิ่มจำนวนใน cytoplasm ของเซลล์เยื่อบุผิว (epithelial cells) ซึ่งยืนยันว่าเซลล์เป้าหมายคือ epithelial cell ตามที่สรุประบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Section B.1 Detection of the agent, p. 3","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"FPV multiplies in the cytoplasm of epithelial cells with the formation of large intracytoplasmic inclusion bodies (Bollinger bodies)."}}]},"avian-medicine--avian-pox--สองรูปแบบของโรค":{"claims":[{"id":"avian-medicine--avian-pox--สองรูปแบบของโรค--v1","statement":"รูปแบบ cutaneous (dry pox) มีรอยโรคชนิด proliferative ตั้งแต่ตุ่มเล็กจนถึงก้อนคล้ายหูดทรงกลมบนผิวหนังของหงอน เหนียง และบริเวณที่ไม่มีขน โดยอัตราการตายมักต่ำ ยกเว้นเมื่อรอยโรคขึ้นรอบดวงตา","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Summary and Section A. Introduction, pp. 1-2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In the case of the cutaneous form, the mortality rate is usually low, unless lesions develop around the eyes."}},{"id":"avian-medicine--avian-pox--สองรูปแบบของโรค--v2","statement":"รูปแบบ diphtheritic (wet pox) เริ่มจากตุ่มนูนสีขาวขุ่นบนเยื่อเมือกแล้วขยายกลายเป็นเยื่อ diphtheritic สีเหลือง พบที่เยื่อเมือกของปาก ลิ้น หลอดอาหาร กล่องเสียงหรือหลอดลม และมีอัตราการตายสูงกว่ารูปแบบ cutaneous บางครั้งเกือบ 50 เปอร์เซ็นต์ โดยเฉพาะในสัตว์อายุน้อย","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Section A. Introduction, p. 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The mortality rate is higher in the diphtheritic form than in the cutaneous form, sometimes nearing 50% particularly in young birds."}}]},"avian-medicine--avian-pox--การวินิจฉัย-วัคซีน-และ-biosecurity":{"claims":[{"id":"avian-medicine--avian-pox--การวินิจฉัย-วัคซีน-และ-biosecurity--v1","statement":"การตรวจทางจุลพยาธิวิทยาของรอยโรคพบ eosinophilic intracytoplasmic inclusion bodies เมื่อย้อมด้วย H&E ซึ่งคือ Bollinger bodies ตรงกับที่สรุประบุว่าพบ eosinophilic ICIB ในเซลล์เยื่อบุผิว","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Section B.1.2 Virus isolation, p. 3","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Histopathological examination of the CAM lesions will reveal eosinophilic intracytoplasmic inclusion bodies following staining with H&E."}},{"id":"avian-medicine--avian-pox--การวินิจฉัย-วัคซีน-และ-biosecurity--v2","statement":"รูปแบบ diphtheritic ที่มีรอยโรคในหลอดลมต้องแยกจาก infectious laryngotracheitis ซึ่งเกิดจาก gallid herpesvirus-1 และมีลักษณะเด่นคือ intranuclear inclusion bodies ต่างจาก fowlpox ที่เป็น intracytoplasmic","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Summary, Detection of the agent, p. 1","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The diphtheritic form of fowlpox involving the trachea must be differentiated from infectious laryngotracheitis, which is caused by gallid herpesvirus-1 and is characterised by the presence of intranuclear inclusion bodies."}},{"id":"avian-medicine--avian-pox--การวินิจฉัย-วัคซีน-และ-biosecurity--v3","statement":"เส้นทางการให้วัคซีน fowlpox ที่แนะนำคือการแทงที่ wing web และใช้ได้ในสัตว์ปีกที่ไวรับทุกช่วงอายุ โดยประเมินความสำเร็จจากการเกิด take คือรอยบวมหรือสะเก็ดที่ตำแหน่งแทงภายใน 7 ถึง 10 วัน","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Section C.2.1.3 Validation as a vaccine, p. 6","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The vaccine must be shown to be safe by the recommended route of administration, which is wing web stab, in all ages of susceptible birds."}},{"id":"avian-medicine--avian-pox--การวินิจฉัย-วัคซีน-และ-biosecurity--v4","statement":"โดยทั่วไปไม่แนะนำให้ทำวัคซีน fowlpox ในไก่ที่กำลังไข่ ตรงกับที่สรุประบุว่าห้ามให้ตอนแม่ไก่กำลังไข่","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Section C.2.3.2 Precautions (hazards), p. 7","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"It is usually recommended not to vaccinate birds that are in lay."}},{"id":"avian-medicine--avian-pox--การวินิจฉัย-วัคซีน-และ-biosecurity--v5","statement":"วัคซีน recombinant ที่ใช้ poxvirus เป็น vector มียีนแทรกของ ILTV, Mycoplasma gallisepticum, avian influenza H5 และ NDV และให้ภูมิคุ้มกันต่อทั้ง FPV ที่เป็น vector และเชื้อของยีนที่แทรก ซึ่งยืนยันหลักการที่สรุประบุว่าไก่สร้างภูมิต่อไวรัสทั้งสอง","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Section C.1 Background, p. 5","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The recombinant poxvirus vaccines include gene inserts for pox-ILTV, Mycoplasma gallisepticum (pox-MG), avian influenza H5 (Pox-AIV), or Newcastle disease virus (pox-NDV). These recombinant vaccines provide protection against the FPV vector"}}]}},"avian-medicine--avian-ai":{"avian-medicine--avian-ai--สถานการณ์ในไทยและการทำลายเชื้อ":{"claims":[{"id":"avian-medicine--avian-ai--สถานการณ์ในไทยและการทำลายเชื้อ--v1","statement":"การยืนยันโรค HPAI H5N1 อย่างเป็นทางการครั้งแรกของไทยเกิดเมื่อ 23 มกราคม 2004 (พ.ศ. 2547) ในฟาร์มไก่ไข่ที่จังหวัดสุพรรณบุรี โดยห้องปฏิบัติการอ้างอิงแห่งชาติ (สถาบันสุขภาพสัตว์แห่งชาติ) ตรงกับที่สรุประบุทั้งปีและจังหวัด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16318716","locator":"vol 11(11):1664-72, section on the 2004 epidemic","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"On January 23, 2004, the Thai national reference laboratory (National Institute of Animal Health [NIAH]) officially confirmed the presence of an H5 HPAI virus in a layer chicken farm in Suphanburi Province."}},{"id":"avian-medicine--avian-ai--สถานการณ์ในไทยและการทำลายเชื้อ--v2","statement":"การระบาดของ H5N1 ครั้งสุดท้ายที่ไทยแจ้งต่อ WOAH (OIE) คือเดือนพฤศจิกายน 2008 (พ.ศ. 2551) สอดคล้องกับที่สรุประบุว่าหลังปี 2551 ไม่มีประกาศโรค AI ในไทยอีก โดยช่วง 2004-2008 ยืนยันในฝูงสัตว์ปีก 1,890 ฝูง มีผู้ป่วย 25 ราย เสียชีวิต 17 ราย และทำลายสัตว์ปีกมากกว่า 63 ล้านตัว","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-24413705","locator":"vol 11(1):934-51, Introduction","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The last occurrence of H5N1 HPAI outbreak in Thailand was declared to the World Organization for Animal Health (OIE) in November 2008"}},{"id":"avian-medicine--avian-ai--สถานการณ์ในไทยและการทำลายเชื้อ--v3","statement":"H5N1 ที่แยกได้จากไก่ในไทยถูกทำลายด้วยน้ำยาฆ่าเชื้อที่ใช้กันทั่วไป (glutaraldehyde ร่วมกับ QAC, chlorine และ phenol) และด้วยความร้อน (70 องศาเซลเซียส 60 นาที หรือ 75 องศาเซลเซียสอย่างน้อย 45 นาที) แต่การปรับ pH ทุกระดับที่ทดสอบไม่สามารถทำลายเชื้อได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-19632071","locator":"vol 140(1-2):43-8, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"AIV H5N1 reference viruses, 2004.1, CUK-2/04 and 2004.2, showed low or no resistance against Glu+QAC, chlorine and phenol at both tested temperatures. Incubations at 70 degrees C for 60 min or at least 75 degrees C for at least 45 min could"}}]},"avian-medicine--avian-ai--มาตรการควบคุมโรคและเขตเฝ้าระวัง":{"claims":[{"id":"avian-medicine--avian-ai--มาตรการควบคุมโรคและเขตเฝ้าระวัง--v1","statement":"มาตรการที่ไทยใช้จริงในการระบาดปี 2547 คือห้ามเคลื่อนย้ายสัตว์ปีกและผลิตภัณฑ์ในรัศมี 5 กิโลเมตรรอบฝูงที่ติดเชื้อ ร่วมกับการทำลายสัตว์ปีกฝูงข้างเคียงในรัศมี 5 กิโลเมตรโดยเร็วที่สุด ตรงกับตัวเลข 5 กิโลเมตรวงในของสรุป","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16318716","locator":"vol 11(11):1664-72, Control measures (January to May 2004)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"a restriction on moving poultry and their products within a 5-km radius around the infected flocks was enforced by DLD inspectors"}}]},"avian-medicine--avian-ai--วัคซีนและหลัก-h-ต้องตรง":{"claims":[{"id":"avian-medicine--avian-ai--วัคซีนและหลัก-h-ต้องตรง--v1","statement":"วัคซีนเชื้อตายชนิด whole virus ให้ความคุ้มโรคต่อไวรัสที่มี HA subtype ตรงกัน แต่คุ้มได้ไม่ดีเมื่อ HA ต่าง subtype จึงสนับสนุนหลักที่ว่า H ต้องตรงกับสายพันธุ์ที่ระบาด นอกจากนี้วัคซีน vector ชนิด recombinant fowlpox ที่แสดง H5 และ N1 ป้องกันไก่จากการพิสูจน์เชื้อ HPAI ขนาดถึงตายได้ 100%","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12745375","locator":"vol 32(1):25-32, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Inactivated whole avian influenza virus (AIV) vaccine provides protection against homologous haemagglutinin (HA) subtype virus, but poor protection against a heterologous HA virus."}},{"id":"avian-medicine--avian-ai--วัคซีนและหลัก-h-ต้องตรง--v2","statement":"หลักการ DIVA ที่ใช้จริงในภาคสนามคือใช้วัคซีนเชื้อตายที่มี HA subtype เดียวกับเชื้อที่ระบาดแต่มี NA ต่างชนิด แล้วตรวจหาแอนติบอดีต่อ NA ของเชื้อสนามเพื่อแยกตัวติดเชื้อออกจากตัวที่ฉีดวัคซีน การทดลองใช้วัคซีน H7N3 ป้องกันเชื้อ H7N1 ให้ clinical protection 93% ยืนยันว่า H ตรงแต่ N ต่างยังคุ้มโรคได้ตามที่สรุปเขียนเรื่อง H5N3 กับ H5N1","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12745380","locator":"vol 32(1):47-55, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The \"DIVA\" (Differentiating Infected from Vaccinated Animals) strategy is based on the use of an inactivated oil emulsion vaccine containing the same haemagglutinin (H) subtype as the challenge virus, but a different neuraminidase (N). ... "}},{"id":"avian-medicine--avian-ai--วัคซีนและหลัก-h-ต้องตรง--v3","statement":"ข้อจำกัดที่สรุปไม่ได้เขียนไว้คือวัคซีนที่ H ตรงกันแม้จะป้องกันอาการป่วยและป้องกันการเข้ากระแสเลือดกับการปนเปื้อนในกล้ามเนื้อได้ แต่ไม่สามารถหยุดการปล่อยเชื้อ (viral shedding) ของไก่ที่ถูกพิสูจน์เชื้อได้ ซึ่งเป็นเหตุผลสำคัญที่หลายประเทศไม่อนุญาตให้ใช้วัคซีน AI","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12745380","locator":"vol 32(1):47-55, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"was able to prevent viraemia and muscle colonization in the clinically healthy challenged birds. However, it was not able to prevent viral shedding."}}]},"avian-medicine--avian-ai--ข้อตกลง-woah-oie-เรื่องการส่งออกสัตว์ปีก":{"claims":[{"id":"avian-medicine--avian-ai--ข้อตกลง-woah-oie-เรื่องการส่งออกสัตว์ปีก--v1","statement":"การประกาศประเทศหรือเขตปลอด HPAI ตาม Terrestrial Animal Health Code ต้องแสดงว่าไม่มีการติดเชื้อในช่วง 12 เดือนที่ผ่านมา ตรงกับตัวเลข 12 เดือนที่สรุปเขียน","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2024","locator":"Article 10.4.3 Country or zone free from high pathogenicity avian influenza","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"absence of infection with high pathogenicity avian influenza viruses ... has been demonstrated in the country or zone for the past 12 months"}}]},"avian-medicine--avian-ai--เชื้อ-subtype-และการจำแนก-hpai-กับ-lpai":{"claims":[{"id":"avian-medicine--avian-ai--เชื้อ-subtype-และการจำแนก-hpai-กับ-lpai--v1","statement":"ฟีโนไทป์ HPAI ที่พบตามธรรมชาติจำกัดอยู่ที่ subtype H5 และ H7 เท่านั้น ตรงกับที่สไลด์ระบุว่า HPAI ต้องเป็น 5 หรือ 7 แต่งานนี้พิสูจน์ต่อว่าข้อจำกัดนี้ไม่ได้อยู่ที่ระดับโมเลกุล เพราะเมื่อใส่ multibasic cleavage site ของ H5 เข้าไปในไวรัส H6N1 ที่เป็น LPAI ก็ได้ฟีโนไทป์ HPAI เต็มรูปแบบ (IVPI 1.4)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-20519405","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The highly pathogenic avian influenza (HPAI) virus phenotype is restricted to influenza A viruses of the H5 and H7 hemagglutinin (HA) subtypes."}},{"id":"avian-medicine--avian-ai--เชื้อ-subtype-และการจำแนก-hpai-กับ-lpai--v2","statement":"HPAIV ของ subtype H5 และ H7 เกิดขึ้นหลังจากไวรัส LPAIV จากนกป่าเข้าสู่ฝูงสัตว์ปีกแล้ววนเวียนและวิวัฒน์ต่อ โดยตัวชี้วัดระดับโมเลกุลของความรุนแรงคือการได้กรดอะมิโนเบสหลายตัวที่ตำแหน่ง cleavage site ของ HA ข้อนี้อธิบายที่สไลด์เขียนว่า H5 และ H7 มีแค่บางสายพันธุ์เท่านั้นที่ก่อโรครุนแรง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-25741006","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Highly pathogenic avian influenza viruses (HPAIVs) of hemagglutinin H5 and H7 subtypes emerge after introduction of low-pathogenic avian influenza viruses (LPAIVs) from wild birds into poultry flocks, followed by subsequent circulation and "}},{"id":"avian-medicine--avian-ai--เชื้อ-subtype-และการจำแนก-hpai-กับ-lpai--v3","statement":"ไวรัส H9N2 แพร่กระจายไปทั่วโลกในสัตว์ปีกในช่วงสองทศวรรษที่ผ่านมาและกลายเป็น endemic ในฟาร์มสัตว์ปีกทั่วเอเชีย ตะวันออกกลาง แอฟริกาเหนือและแอฟริกาตะวันตก ตรงกับที่สไลด์ระบุว่า LPAI H9N2 แพร่ทั่วโลก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-31284485","locator":"Abstract and section on global distribution","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"H9N2 avian influenza viruses have become globally widespread in poultry over the last two decades and represent a genuine threat both to the global poultry industry but also humans"}},{"id":"avian-medicine--avian-ai--เชื้อ-subtype-และการจำแนก-hpai-กับ-lpai--v4","statement":"หมูทำหน้าที่เป็น mixing vessel ให้เกิด reassortant ไวรัสไข้หวัดใหญ่สายพันธุ์ใหม่ได้จริง แต่ตัวอย่างที่แหล่งนี้ยกว่ามีหลักฐานชัดคือ pandemic H1N1 2009 ไม่ใช่ H3N2 ตามที่สไลด์เขียน ผู้เขียนยังพบว่าทางเดินหายใจส่วนล่างของหมูมี receptor แบบ NeuAc alpha2-6 (แบบคน) มากกว่าแบบ alpha2-3 (แบบนก) ถึง 13 เท่า ซึ่งเป็นแรงกดดันคัดเลือกให้ไวรัสเปลี่ยนไปชอบ receptor แบบคน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-21347401","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"It is known that pigs acted as \"mixing vessels\" for genesis of a new reassortant influenza strain responsible for pandemic H1N1 2009."}}]},"avian-medicine--avian-ai--การติดต่อ-อาการ-และรอยโรค":{"claims":[{"id":"avian-medicine--avian-ai--การติดต่อ-อาการ-และรอยโรค--v1","statement":"WOAH กำหนดระยะฟักตัว (incubation period) ของ high pathogenicity avian influenza ที่ระดับฝูงไว้ที่ 14 วัน ซึ่งตรงกับขอบบน 2 สัปดาห์ที่สรุประบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2024","locator":"Article 10.4.1 General provisions","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The incubation period at the flock-level for high pathogenicity avian influenza is 14 days."}},{"id":"avian-medicine--avian-ai--การติดต่อ-อาการ-และรอยโรค--v2","statement":"HPAI ในสัตว์ปีกกลุ่ม gallinaceous ทำให้เกิด morbidity และ mortality สูง และเป็นโรคแบบ systemic ที่มี necrosis กับ inflammation ในอวัยวะภายในหลายระบบ รวมทั้งระบบประสาท ระบบหัวใจและหลอดเลือด และผิวหนัง/ส่วนประกอบผิวหนัง (integument ซึ่งรวมหงอนและเหนียง) สอดคล้องกับรอยโรคที่สรุประบุทั้งเนื้อตายที่ตับ ม้าม ไต ปอด อาการทางประสาท และหน้า/เหนียงบวมคล้ำ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-19618622","locator":"เล่ม 28 ฉบับ 1 หน้า 113-136, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The HPAIV have primarily been seen in gallinaceous poultry, producing high morbidity and mortality, and systemic disease with necrosis and inflammation in multiple visceral organs, nervous and cardiovascular systems, and the integument."}},{"id":"avian-medicine--avian-ai--การติดต่อ-อาการ-และรอยโรค--v3","statement":"การระบาดของ HPAI H5N8 ในฟาร์มพ่อแม่พันธุ์ไก่เนื้อและฟาร์มไก่ไข่การค้าที่เกาหลีใต้ มีลักษณะเป็นการตายที่ค่อย ๆ เพิ่มขึ้น เชื้อแพร่ช้า และแทบไม่แสดงอาการที่จำเพาะของ HPAI ตรงกับที่สรุประบุว่าไก่ไข่ในกรงติดเชื้อแพร่ช้ากว่าและอาจไม่แสดงอาการหรือแสดงแบบ nonspecific","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26292555","locator":"เล่ม 59 ฉบับ 1 หน้า 175-182, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Clinically, the cases were characterized by a gradual increase in mortality, slow transmission, and unrecognizable clinical signs of HPAI."}}]}},"avian-medicine--avian-coli":{"avian-medicine--avian-coli--เชื้อและ-serotype-ที่ก่อโรค":{"claims":[{"id":"avian-medicine--avian-coli--เชื้อและ-serotype-ที่ก่อโรค--v1","statement":"Serogroup ของ avian pathogenic Escherichia coli (APEC) ที่สัมพันธ์กับโรคมากที่สุดคือ O1, O2 และ O78 ตรงกับที่สรุประบุ แต่แหล่งอ้างอิงย้ำว่ายังมี serogroup อื่นอีกจำนวนมากที่ก่อโรคได้ ไม่ได้จำกัดแค่ไม่กี่ตัว","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-18622850","locator":"vol 37(4):355-66, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Autologous bacterins provide limited serotype-specific protection, yet multiple serogroups are associated with disease, especially O1, O2 and O78 among many others."}},{"id":"avian-medicine--avian-coli--เชื้อและ-serotype-ที่ก่อโรค--v2","statement":"แอนติเจนและโครงสร้างผิวเซลล์ที่สรุประบุว่าสำคัญ (O, K, F) มีบทบาทที่พิสูจน์แล้วคนละหน้าที่กัน คือ fimbriae ชนิด Type 1 (F1) และ P ใช้ในการเกาะยึด (colonization) ส่วนแอนติเจน K และ O ทำหน้าที่ต้านการถูกกลืนกินโดยเซลล์เม็ดเลือดขาว (anti-phagocytic)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-18622850","locator":"vol 37(4):355-66, Abstract, virulence factors","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Well-recognized virulence factors include Type 1 (F1) and P (Pap/Prs) fimbriae for colonization, IbeA for invasion, iron acquisition systems, TraT and Iss for serum survival, K and O antigens for anti-phagocytic activity"}}]},"avian-medicine--avian-coli--pathogenesis-และรูปแบบเฉพาะที่":{"claims":[{"id":"avian-medicine--avian-coli--pathogenesis-และรูปแบบเฉพาะที่--v1","statement":"Swollen Head Syndrome ที่สรุประบุว่ามักเกิดร่วมกับ aMPV มีหลักฐานภาคสนามรองรับ คือในการระบาดที่ฟาร์มไก่เนื้อและไก่พ่อแม่พันธุ์ สามารถแยกได้ทั้ง avian pneumovirus และ Escherichia coli จากไก่ทุกฟาร์ม โดยลักษณะเด่นคือหัวบวมน้ำ โดยเฉพาะรอบเปลือกตา คอ และเหนียง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-18671082","locator":"vol 23(1):169-74, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The disease was characterized by oedematous swelling of the head, especially surrounding the eyelids, the neck and wattles. Avian pneumovirus and Escherichia coli were isolated from birds in all four farms."}},{"id":"avian-medicine--avian-coli--pathogenesis-และรูปแบบเฉพาะที่--v2","statement":"Yolk sac infection (omphalitis) และ cellulitis ที่สรุปจัดเป็น localized form ถูกจัดอยู่ในกลุ่มโรคนอกทางเดินอาหาร (extra-intestinal diseases) ที่เกิดจาก APEC เช่นเดียวกับ colibacillosis และ coligranuloma","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30357106","locator":"vol 9(3):211-216, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Avian pathogenic (APEC) are responsible for wide ranges of extra-intestinal diseases in poultry including colibacillosis, cellulitis, coligranuloma and yolk sac infection."}}]},"avian-medicine--avian-coli--systemic-forms-และการวินิจฉัย":{"claims":[{"id":"avian-medicine--avian-coli--systemic-forms-และการวินิจฉัย--v1","statement":"Coligranuloma เป็นรูปแบบหนึ่งของโรคที่เกิดจาก avian pathogenic Escherichia coli จริงตามที่สรุประบุ โดยจัดอยู่ในกลุ่มโรคนอกทางเดินอาหารร่วมกับ colibacillosis, cellulitis และ yolk sac infection","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30357106","locator":"vol 9(3):211-216, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Avian pathogenic (APEC) are responsible for wide ranges of extra-intestinal diseases in poultry including colibacillosis, cellulitis, coligranuloma and yolk sac infection."}}]},"avian-medicine--avian-coli--การรักษาและวัคซีน":{"claims":[{"id":"avian-medicine--avian-coli--การรักษาและวัคซีน--v1","statement":"เหตุผลที่ต้องทำ drug sensitivity test ก่อนเลือกยาตามที่สรุปเน้น มีหลักฐานรองรับชัดเจน เพราะมีรายงานว่า APEC ดื้อต่อยาปฏิชีวนะแทบทุกกลุ่มแล้ว รวมถึงกลุ่ม carbapenem","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-33921518","locator":"vol 10(4):467, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"APEC resistance to almost all classes of antibiotics, including carbapenems, has been already reported. There is a need for an effective APEC vaccine that can provide protection against diverse APEC serotypes."}},{"id":"avian-medicine--avian-coli--การรักษาและวัคซีน--v2","statement":"วัคซีนเชื้อตายชนิด autologous bacterin ให้ความคุ้มโรคจำกัดและจำเพาะต่อ serotype เท่านั้น ในขณะที่โรคเกิดจาก serogroup หลายชนิด สนับสนุนข้อความในสรุปที่ว่าวัคซีนเชื้อตายไม่มี cross protection จึงไม่นิยม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-18622850","locator":"vol 37(4):355-66, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Autologous bacterins provide limited serotype-specific protection, yet multiple serogroups are associated with disease"}}]}},"avian-medicine--avian-coryza":{"avian-medicine--avian-coryza--เชื้อ-serovar-และโฮสต์":{"claims":[{"id":"avian-medicine--avian-coryza--เชื้อ-serovar-และโฮสต์--v1","statement":"ระบบ Page ที่ใช้กันทั่วไปแบ่ง Avibacterium (Haemophilus) paragallinarum เป็น 3 serovars คือ A, B และ C ด้วยวิธี plate หรือ slide agglutination test ส่วนระบบ Kume แบ่งเป็น 7 serovars ใน 3 serogroups (I, II, III) ตรงกับที่สรุปเขียนว่านิยมใช้ A, B, C มากกว่า I, II, III","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10515906","locator":"vol 12(4):627-32, serotyping schemes","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The Page scheme was initially developed by using a plate or slide agglutination test to recognize the three serovars, A, B, and C."}},{"id":"avian-medicine--avian-coryza--เชื้อ-serovar-และโฮสต์--v2","statement":"การลดลงของผลผลิตไข่จาก infectious coryza อยู่ในช่วง 10% ถึงมากกว่า 40% โดยเฉพาะในฟาร์มที่เลี้ยงหลายรุ่นอายุรวมกัน (multi-age farms) ตรงกับตัวเลข 10-40% ที่สรุปเขียน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10515906","locator":"vol 12(4):627-32, economic impact","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The disease occurs worldwide and causes economic losses due to ... a marked (10% to more than 40%) drop in egg production, particularly on multi-age farms."}},{"id":"avian-medicine--avian-coryza--เชื้อ-serovar-และโฮสต์--v3","statement":"เชื้อที่ก่อโรคหวัดหน้าบวมต้องการเฉพาะ V factor (NAD) ในการเจริญ ซึ่งเป็นเหตุผลที่เพาะบนอาหารเลี้ยงเชื้อธรรมดาไม่ขึ้น อย่างไรก็ตามตั้งแต่ปี 1989 มีรายงานเชื้อสายพันธุ์แปรผันที่ไม่ต้องการ V factor แล้ว ทำให้การวินิจฉัยยากขึ้น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10515906","locator":"vol 12(4):627-32, growth requirements","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"From the 1960s to the 1980s, all isolates of the disease producing-agent have been shown to require only V factor and have been termed Haemophilus paragallinarum."}}]},"avian-medicine--avian-coryza--pathogenesis-อาการ-และรอยโรค":{"claims":[{"id":"avian-medicine--avian-coryza--pathogenesis-อาการ-และรอยโรค--v1","statement":"Hemagglutinin และ capsule เป็น virulence factor หลักของ Avibacterium paragallinarum จริงตามที่สรุปเขียน โดยมีบทบาทในการเกาะยึด การตั้งรกราก และการหลบภูมิคุ้มกัน และตำแหน่งที่เชื้อตั้งรกรากคือ infraorbital sinus กับ nasal epithelium ซึ่งอธิบายว่าทำไมโรคจึงจำกัดอยู่ที่ทางเดินหายใจส่วนบน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-42197478","locator":"vol 14(5):1093, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"emphasizing its colonization strategies in the infraorbital sinus and nasal epithelium of chickens, and analyzes the roles of key virulence factors such as hemagglutinin and capsule in adhesion, colonization, and immune evasion"}},{"id":"avian-medicine--avian-coryza--pathogenesis-อาการ-และรอยโรค--v2","statement":"โดยตัวมันเอง infectious coryza เป็นโรคของทางเดินหายใจส่วนบนที่รู้จักกันดี แต่ในประเทศกำลังพัฒนามักถูกซ้ำเติมด้วยการติดเชื้ออื่นร่วมด้วยหลายชนิด จนกลายเป็นโรครุนแรงและสร้างความเสียหายทางเศรษฐกิจอย่างมาก สนับสนุนข้อความในสรุปที่ว่าอาการจะรุนแรงขึ้นเมื่อมี MG, fowl pox หรือ E. coli ร่วม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10515906","locator":"vol 12(4):627-32, disease in developing countries","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In developing countries, coryza is commonly complicated by the presence of a range of other infections, resulting in severe disease and significant economic losses."}}]},"avian-medicine--avian-coryza--การวินิจฉัย-การรักษา-และวัคซีน":{"claims":[{"id":"avian-medicine--avian-coryza--การวินิจฉัย-การรักษา-และวัคซีน--v1","statement":"การเพาะแยกเชื้อทำได้บน chocolate agar (ซึ่งให้ NAD จากเม็ดเลือดที่แตก) โดยเก็บตัวอย่างจากโพรงจมูกและวัสดุคล้ายเนยแข็งใน infraorbital sinus บ่มที่ 37 องศาเซลเซียสใน CO2 24 ชั่วโมง ได้โคโลนีเล็กใสคล้ายหยดน้ำค้าง และย้อมแกรมพบเป็น Gram-negative short rod หรือ coccobacilli ตรงกับลักษณะที่สรุปเขียน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-40087555","locator":"vol 25(1):141, Methods and Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The isolation of Av. paragallinarum on chocolate and brain heart infusion agar resulted in the observation of small, translucent, dewdrop-shaped colonies after 24 h of incubation at 37 °C in a 5% CO incubator. A smear prepared from a single"}}]}},"avian-medicine--avian-fowl-cholera":{"avian-medicine--avian-fowl-cholera--เชื้อและความไวรับ":{"claims":[{"id":"avian-medicine--avian-fowl-cholera--เชื้อและความไวรับ--v1","statement":"ระบบ Heddleston ที่พัฒนาขึ้นในต้นทศวรรษ 1970 แบ่ง Pasteurella multocida เป็น 16 somatic serovars ตามโครงสร้าง lipopolysaccharide (LPS) ด้วยวิธี agar gel diffusion precipitin test ตรงกับตัวเลข 15-16 serotypes ที่สรุปเขียน แต่ผู้เขียนชี้ว่าวิธีนี้มีปัญหาเรื่องความแม่นยำและความทำซ้ำได้ จึงควรใช้ LPS multiplex PCR แทน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-25428149","locator":"vol 53(2):477-85, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"This scheme was developed in the early 1970s and classifies P. multocida strains into 16 somatic or lipopolysaccharide (LPS) serovars using an agar gel diffusion precipitin test."}},{"id":"avian-medicine--avian-fowl-cholera--เชื้อและความไวรับ--v2","statement":"ความรุนแรงและอุบัติการณ์ของการติดเชื้อ Pasteurella multocida แปรผันมากตามชนิดและอายุของนกที่ติดเชื้อ รวมถึงสภาพแวดล้อมและสายพันธุ์ของเชื้อ ซึ่งเป็นหลักการที่รองรับข้อความในสรุปเรื่องความไวรับต่างกันระหว่างชนิดสัตว์และช่วงอายุ (แต่ตัวเลขเฉพาะเจาะจงในสรุปไม่ได้ระบุไว้ในเอกสารนี้)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10935284","locator":"vol 19(2):626-37, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The severity and incidence of P. multocida infections may vary considerably depending on several factors associated with the host (including species and age of infected birds), the environment and the bacterial strain."}}]},"avian-medicine--avian-fowl-cholera--การวินิจฉัย-รักษา-และป้องกัน":{"claims":[{"id":"avian-medicine--avian-fowl-cholera--การวินิจฉัย-รักษา-และป้องกัน--v1","statement":"การวินิจฉัย fowl cholera ต้องอาศัยการแยกเชื้อเสมอ ส่วนการตรวจการติดเชื้อแบบไม่แสดงอาการแนะนำให้ผ่านหนู (mouse passage) หรือใช้ PCR และการเพาะบนอาหารคัดเลือกเป็นทางเลือก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10935284","locator":"vol 19(2):626-37, diagnosis","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Diagnosis is always dependent upon isolation of the organism. For the detection of subclinical infections, mouse passage of relevant samples is recommended, but polymerase chain reaction and isolation attempts on selective media may represe"}},{"id":"avian-medicine--avian-fowl-cholera--การวินิจฉัย-รักษา-และป้องกัน--v2","statement":"การควบคุมโรคยังต้องพึ่งวัคซีนเชื้อตาย (bacterin) เป็นหลัก เพราะการพัฒนาวัคซีนเชื้อเป็นที่ปลอดภัยและมีประสิทธิภาพยังมีปัญหาอยู่ ตรงกับที่สรุปเขียนว่าวัคซีนเชื้อเป็นไม่นิยมและใช้ bacterin แทน แต่เอกสารระบุว่า bacterin เองก็มีข้อเสียชัดเจนเมื่อเทียบกับวัคซีนเชื้อเป็น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10935284","locator":"vol 19(2):626-37, prevention and control","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Unfortunately, the development of safe and efficient live vaccines still poses problems. As a result, control remains dependent on bacterins which exhibit significant disadvantages compared to live vaccines."}},{"id":"avian-medicine--avian-fowl-cholera--การวินิจฉัย-รักษา-และป้องกัน--v3","statement":"เหตุผลเชิงกลไกที่วัคซีน fowl cholera ไม่ค่อยได้ผลข้าม serotype คือวัคซีนเชื้อตายให้ความคุ้มโรคเฉพาะต่อสายพันธุ์ที่มีโครงสร้าง LPS ผิวเซลล์เหมือนหรือเกือบเหมือนกันเท่านั้น ในขณะที่วัคซีนเชื้อเป็นชนิดลดความรุนแรงให้ความคุ้มโรคกว้างและไม่ขึ้นกับโครงสร้าง LPS","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28825691","locator":"vol 9(8):254, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Recent work has shown that vaccines containing killed bacteria give protection only against other strains with identical, or nearly identical, surface LPS structures. Conversely, live attenuated vaccines give protection that is broadly prot"}}]},"avian-medicine--avian-fowl-cholera--การติดต่อ-อาการ-และรอยโรค":{"claims":[{"id":"avian-medicine--avian-fowl-cholera--การติดต่อ-อาการ-และรอยโรค--v1","statement":"WOAH Terrestrial Animal Health Code กำหนดระยะฟักตัวระดับฝูงของ high pathogenicity avian influenza ไว้ที่ 14 วัน ซึ่งตรงกับขอบบนที่สไลด์ระบุคือ 2 สัปดาห์ (ตัวเลข 14 วันนี้เป็นค่าที่ใช้ทางการค้าและการควบคุมโรค ไม่ใช่ค่าที่วัดจากสัตว์รายตัว)","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2024","locator":"Article 10.4.1, General provisions","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The incubation period at the flock-level for high pathogenicity avian influenza is 14 days."}},{"id":"avian-medicine--avian-fowl-cholera--การติดต่อ-อาการ-และรอยโรค--v2","statement":"ในรูปแบบ peracute และ acute ของ fowl cholera มักเห็นอาการทางคลินิกน้อยมากก่อนตาย และรอยโรคที่เด่นคือรอยโรคแบบ septicaemia ทั่วร่างกาย ตรงกับที่สไลด์ระบุว่า sudden death with no signs","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10935284","locator":"Abstract, section on outcome of infection","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In the former type of infections, few clinical signs are observed before death and the lesions will be dominated by general septicaemic lesions."}},{"id":"avian-medicine--avian-fowl-cholera--การติดต่อ-อาการ-และรอยโรค--v3","statement":"นกที่รอดชีวิตจากฝูงที่เคยป่วยเป็น carrier และ carrier มีบทบาทหลักในการแพร่ fowl cholera ตรงกับที่สไลด์ระบุว่า recovered flocks เป็น carrier แหล่งเดียวกันยังเสริมสิ่งที่สไลด์ไม่ได้พูด คือ carrier ของ Pasteurella multocida อาจมีอยู่ในฝูงที่ไม่เคยมีประวัติระบาดมาก่อนเลยก็ได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10935284","locator":"Abstract, section on epidemiology","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Carrier birds seem to play a major role in the transmission of cholera. Surviving birds from diseased flocks appear to represent a risk, but more recent investigations indicate that carriers of P. multocida may exist within poultry flocks w"}},{"id":"avian-medicine--avian-fowl-cholera--การติดต่อ-อาการ-และรอยโรค--v4","statement":"ตับอักเสบแบบเนื้อตาย (necrotic hepatitis) เป็นรอยโรคสำคัญของ fowl cholera ในไก่ โดยพบจุดเนื้อตายกระจายในเนื้อตับ ซึ่งเป็นรอยโรคเดียวกับ pinpoint necrotic foci ที่สไลด์ระบุว่าเป็น pathognomonic lesion","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-29337619","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Necrotic hepatitis is reported to be a significant lesion associated with fowl cholera in chickens."}}]}},"avian-medicine--avian-intro":{"avian-medicine--avian-intro--riemerella-anatipestifer-infection-new-duck-syndrome-โรคเป็ดหมุน":{"claims":[{"id":"avian-medicine--avian-intro--riemerella-anatipestifer-infection-new-duck-syndrome-โรคเป็ดหมุน--v1","statement":"Riemerella anatipestifer ก่อโรค polyserositis ติดต่อในเป็ดที่มีอัตราการตายสูง และวัคซีนที่มีอยู่ให้ cross protection ไม่ดี จึงต้องเตรียมวัคซีนตาม serotype ที่ระบาดจริงในพื้นที่ ตรงกับหลักการในสรุปที่ว่าต้องใช้ homologous vaccine ให้ตรง serotype","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38262334","locator":"vol 103(3):103427, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Riemerella anatipestifer (RA) causes epizootic infectious polyserositis in ducks with high mortality and leads to huge economic losses worldwide. Bacterial resistance poses a challenge for the control of the disease, vaccines failed to prov"}},{"id":"avian-medicine--avian-intro--riemerella-anatipestifer-infection-new-duck-syndrome-โรคเป็ดหมุน--v2","statement":"การที่สรุประบุว่าต้องทำ antimicrobial susceptibility test ก่อนให้ยามีเหตุผลรองรับ เพราะการดื้อยาของ Riemerella anatipestifer เป็นอุปสรรคสำคัญต่อการควบคุมโรค นอกจากนี้การเลือกวัคซีนต้องอาศัยข้อมูล serotype ที่ระบาดจริง เช่นในจีนตอนใต้ปี 2016-2022 พบ serotype 1, 2, 7 และ 10 โดย serotype 1 กับ 2 รวมกันคิดเป็น 82%","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38262334","locator":"vol 103(3):103427, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"we collected 700 brain and liver tissues of dead ducks from 8 provinces in southern China from 2016 to 2022 and obtained 195 RA isolates with serotypes 1, 2, 7, and 10. Serotypes 1 and 2 were the most prevalent (82%)."}}]},"avian-medicine--avian-intro--duck-plague-duck-viral-enteritis-dve":{"claims":[{"id":"avian-medicine--avian-intro--duck-plague-duck-viral-enteritis-dve--v1","statement":"Duck plague เกิดจาก duck enteritis virus หรือ Anatid herpesvirus-1 ในสกุล Mardivirus วงศ์ Herpesviridae วงศ์ย่อย Alphaherpesvirinae และเป็นโรคติดต่อร้ายแรงของเป็ด ห่าน และหงส์ ตรงกับที่สรุประบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28320263","locator":"vol 37(1):57-80, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"It is caused by duck enteritis virus (DEV)/Anatid herpesvirus-1 of the genus Mardivirus, family Herpesviridae, and subfamily Alpha-herpesvirinae."}},{"id":"avian-medicine--avian-intro--duck-plague-duck-viral-enteritis-dve--v2","statement":"ลักษณะเด่นของโรคคือตายเฉียบพลัน มีความเสียหายของหลอดเลือด (vascular damage) ตามด้วยเลือดออกภายใน รอยโรคที่อวัยวะน้ำเหลือง เยื่อเมือกทางเดินอาหารเป็นแผลนูน ท้องเสียรุนแรง และรอยโรคเสื่อมที่อวัยวะเนื้อ โดยอัตราป่วยและอัตราตายอยู่ในช่วง 5% ถึง 100% ตรงกับกลไก vascular damage ที่สรุปเขียน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28320263","locator":"vol 37(1):57-80, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The disease is characterized by sudden death, vascular damage and subsequent internal hemorrhage, lesions in lymphoid organs, digestive mucosal eruptions, severe diarrhea and degenerative lesions in parenchymatous organs."}},{"id":"avian-medicine--avian-intro--duck-plague-duck-viral-enteritis-dve--v3","statement":"เชื้อ duck enteritis virus สามารถเข้าสู่ระยะแฝง (latent) และปล่อยเชื้อออกมาเป็นระยะได้ และการป้องกันใช้ทั้งวัคซีนเชื้อเป็นลดความรุนแรงและวัคซีนเชื้อตายในเป็ดเนื้อและเป็ดพ่อแม่พันธุ์ที่อายุมากกว่า 2 สัปดาห์ สนับสนุนข้อความในสรุปเรื่อง latent infection และการทำวัคซีนเชื้อเป็น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28320263","locator":"vol 37(1):57-80, Abstract, prophylaxis","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"For prophylaxis, both live-attenuated and killed vaccines are being used in broiler and breeder ducks above 2 weeks of age. Since DEV is capable of becoming latent as well as shed intermittently"}}]},"avian-medicine--avian-intro--duck-viral-hepatitis-dvh-ทั้ง-3-ไทป์":{"claims":[{"id":"avian-medicine--avian-intro--duck-viral-hepatitis-dvh-ทั้ง-3-ไทป์--v1","statement":"Duck hepatitis A virus (DHAV) เป็น picornavirus ที่ก่อโรคติดต่อรุนแรงมากในเป็ด อัตราการตายในฝูงสูงถึง 100% ในลูกเป็ดอายุน้อยกว่า 6 สัปดาห์ ขณะที่เป็ดโตกว่านั้นไม่ได้รับผลกระทบ สอดคล้องกับที่สรุปเขียนว่าเป็นโรคของลูกเป็ดอายุน้อยและ mortality สูงมาก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-27610716","locator":"vol 60(3):576-88, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"DHAV is a picornavirus that causes a highly contagious virus infection in ducks with up to 100% flock mortality in ducklings under 6 wk of age, while older birds remain unaffected."}},{"id":"avian-medicine--avian-intro--duck-viral-hepatitis-dvh-ทั้ง-3-ไทป์--v2","statement":"Duck hepatitis virus type 2 และ type 3 เป็น astrovirus ในวงศ์ Astroviridae ซึ่งต่างวงศ์จาก type 1 ที่เป็น picornavirus ตรงกับที่สรุปเขียนว่าทั้ง 3 ไทป์เกิดจากไวรัสคนละตัวกัน โดย DAstV-1 รายงานในสหราชอาณาจักรและจีน ส่วน DAstV-2 รายงานในสหรัฐอเมริกา","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-27610716","locator":"vol 60(3):576-88, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Duck hepatitis virus Types 2 and 3 are astroviruses in the family of Astroviridae with similarity phylogenetically to turkey astroviruses ... DAstV-1 has only been recognized in the United Kingdom and recently in China, while DAstV-2 has be"}}]},"avian-medicine--avian-intro--duck-flavivirus-tembusu-dtmuv-โรคเป็ดกลิ้ง":{"claims":[{"id":"avian-medicine--avian-intro--duck-flavivirus-tembusu-dtmuv-โรคเป็ดกลิ้ง--v1","statement":"Duck Tembusu virus เป็น flavivirus ที่ก่อโรคอุบัติใหม่ในเป็ด อาการทางคลินิกหลักคือรอยโรคที่อวัยวะภูมิคุ้มกันและความผิดปกติของระบบประสาท ทำให้ไข่ลดอย่างหนัก และระบาดในจีน ไทย มาเลเซีย และประเทศอื่นในเอเชียตะวันออกเฉียงใต้ ตรงกับที่สรุปเขียนเรื่อง encephalitis และความเสียหายทางเศรษฐกิจ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32075929","locator":"vol 94(9), Importance section","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Infection with an emerging flavivirus, DTMUV, manifests with clinical symptoms that include lesions of the immune organs and neurological dysfunction, leading to heavy egg drop and causing serious harm to the duck industry in China, Thailan"}},{"id":"avian-medicine--avian-intro--duck-flavivirus-tembusu-dtmuv-โรคเป็ดกลิ้ง--v2","statement":"การแยกเชื้อได้จากยุงตามที่สรุปเขียนมีหลักฐานจากประเทศไทยโดยตรง คือการสำรวจยุงในฟาร์มเป็ดจังหวัดสิงห์บุรีและอ่างทองปี 2015-2016 จำนวน 30,841 ตัว ตรวจพบ DTMUV ด้วย RT-PCR ในยุง Culex tritaeniorhynchus หนึ่ง pool จึงสนับสนุนมาตรการควบคุมพาหะ (vector borne control)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-31913570","locator":"vol 67(3):1082-1088, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"A total of 273 mosquito pools were examined, with only one pool of Cx. tritaeniorhynchus collected from Sing Buri Province in November 2015 testing positive for DTMUV. ... Thus, this study indicated that Cx. tritaeniorhynchus may play a rol"}}]},"avian-medicine--avian-intro--goose-parvovirus-infection":{"claims":[{"id":"avian-medicine--avian-intro--goose-parvovirus-infection--v1","statement":"Goose parvovirus สายพันธุ์ดั้งเดิม (classical GPV) คือสาเหตุของ Derzsy's disease และก่อโรคที่อัตราการตายสูงมากในลูกห่านอายุน้อย โดยการพิสูจน์เชื้อในลูกห่านอายุ 2 วันด้วยเชื้อ classical GPV ทำให้ตาย 93.3% สนับสนุนข้อความในสรุปที่ว่าลูกห่านอายุน้อยตายเฉียบพลันเกือบทั้งหมด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-29630396","locator":"vol 47(4):391-399, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The mortality (73.3-80%) caused by the first and third egg-passages of the variant GPV was somewhat lower than that (93.3%) caused by the third passage virus of the classical GPV, reflecting the higher pathogenicity of the classical GPV for"}},{"id":"avian-medicine--avian-intro--goose-parvovirus-infection--v2","statement":"การป้องกันโรคด้วยการทำวัคซีนในแม่พันธุ์เพื่อส่งภูมิคุ้มกันไปยังลูกได้ผลชัดเจน ลูกห่านจากพ่อแม่ที่ได้วัคซีนเชื้อเป็นลดความรุนแรง 2 ครั้ง ตายเพียง 4.2% หลังพิสูจน์เชื้อ เทียบกับ 95% ในลูกของพ่อแม่ที่ไม่ได้วัคซีน และในฟาร์มจริงอัตราการตายเดือนแรกคือ 7.7% เทียบกับ 59.8%","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-18770393","locator":"vol 7(3):397-406, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Only 4.2% of gosling progeny of parents vaccinated twice with strain Bav died after challenge with the virulent strain B goose parvovirus compared with 95% of gosling progeny of unvaccinated parents. ... During the first month of life morta"}}]},"avian-medicine--avian-intro--avian-encephalomyelitis-ae-และสาเหตุที่ทำวัคซีนแล้วภูมิไม่ขึ้น":{"claims":[{"id":"avian-medicine--avian-intro--avian-encephalomyelitis-ae-และสาเหตุที่ทำวัคซีนแล้วภูมิไม่ขึ้น--v1","statement":"AE เป็นโรคที่มี age resistance จริงตามที่สรุปเขียน เพราะเชื้อ AEV สายพันธุ์ธรรมชาติทำให้เกิดอาการทางประสาทในลูกไก่เล็กเท่านั้น ส่วนไก่สาวไม่แสดงอาการเมื่อได้รับเชื้อทางปากหรือทางผิวหนัง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28532787","locator":"vol 204:1-7, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Wild-type avian encephalomyelitis virus (AEV) causes neurological signs in young chicks but no disease in pullets after oral or intracutaneous infection."}},{"id":"avian-medicine--avian-intro--avian-encephalomyelitis-ae-และสาเหตุที่ทำวัคซีนแล้วภูมิไม่ขึ้น--v2","statement":"หลักที่สรุปเน้นว่า route กับ strain ต้องเข้ากันมีหลักฐานเชิงกลไกรองรับ คือเมื่อไวรัสถูกปรับให้เพิ่มจำนวนในตัวอ่อนไก่ (embryo-adapted) โดยการผ่านต่อเนื่อง คุณสมบัติจะเปลี่ยนจนก่อโรค AE ได้ในไก่ทุกช่วงอายุเมื่อให้ทางผิวหนัง และมีรายงานไก่สาวป่วยเป็น AE ไม่นานหลังได้รับวัคซีนทางผิวหนัง (เอกสารนี้ไม่ได้ทดสอบกรณีให้วัคซีนผสมน้ำโดยตรง)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28532787","locator":"vol 204:1-7, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"However, if the virus gets embryo-adapted by serial passaging in chicken embryos, it will cause AE after intracutaneous infection in chickens of all ages. Recently, several cases of AE in layer pullets occurring shortly after intracutaneous"}}]},"avian-medicine--avian-intro--ปัญหาจากโรงฟักและคุณภาพลูกไก่-ascites-ขาแบะ-ขาบิด-สะดือ-yolk-sac":{"claims":[{"id":"avian-medicine--avian-intro--ปัญหาจากโรงฟักและคุณภาพลูกไก่-ascites-ขาแบะ-ขาบิด-สะดือ-yolk-sac--v1","statement":"ลูกโซ่พยาธิกำเนิดของ ascites ที่สรุปเขียนตรงกับตำราคลาสสิก คือ pulmonary hypertension ที่เกิดจากเลือดไหลผ่านปอดมากขึ้นหรือมีแรงต้านมากขึ้น นำไปสู่ right ventricular hypertrophy ลิ้นหัวใจรั่ว ความดันหลอดเลือดดำสูงขึ้น และลงท้ายด้วย ascites ส่วน polycythemia จากภาวะ hypoxia ทำให้เลือดหนืดขึ้นและยิ่งเร่งให้เกิด pulmonary hypertension","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-18671031","locator":"vol 22(3):419-54, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Pulmonary hypertension (PH) caused by increased blood flow or increased resistance to flow in the lung results in right ventricular hypertrophy (RVH), valvular insufficiency, increased venous pressure and ascites. ... Increased blood viscos"}},{"id":"avian-medicine--avian-intro--ปัญหาจากโรงฟักและคุณภาพลูกไก่-ascites-ขาแบะ-ขาบิด-สะดือ-yolk-sac--v2","statement":"อุณหภูมิเปลือกไข่ที่สูงเกินระหว่างฟัก (38.9 เทียบกับ 37.8 องศาเซลเซียส) ทำให้คุณภาพลูกไก่แรกฟักแย่ลงจริงตามที่สรุประบุเรื่อง heat stress โดยลูกไก่มี residual yolk เหลือมากกว่า และมี yolk free body mass กับน้ำหนักตับและหัวใจต่ำกว่า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34030030","locator":"vol 15(6):100223, Results and Conclusion","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"At 6 h after hatching, an EST of 38.9 °C resulted in a higher residual yolk weight and lower YFBM, liver weight and heart weight than an EST of 37.8 °C (all P < 0.003). ... a higher EST from day 8 of incubation onward appears to negatively "}},{"id":"avian-medicine--avian-intro--ปัญหาจากโรงฟักและคุณภาพลูกไก่-ascites-ขาแบะ-ขาบิด-สะดือ-yolk-sac--v3","statement":"คุณภาพสะดือ (navel quality) เป็นตัวชี้วัดคุณภาพลูกไก่ที่ขึ้นกับสภาวะการฟักจริง โดยพบปฏิสัมพันธ์สามทางระหว่างอายุแม่พันธุ์ สายพันธุ์ไก่เนื้อ และอุณหภูมิเปลือกไข่ ที่มีผลต่อระยะเวลาฟัก คุณภาพสะดือ และน้ำหนักสัมพัทธ์ของหัวใจกับกระเพาะที่ 3 ชั่วโมงหลังฟัก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26957632","locator":"vol 95(7):1666-1679, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"A 3-way interaction among breeder age, strain, and EST was found, especially for incubation duration, navel quality, and relative heart and stomach weights at 3 h after hatch (all P < 0.05)."}}]},"avian-medicine--avian-intro--staphylococcosis":{"claims":[{"id":"avian-medicine--avian-intro--staphylococcosis--v1","statement":"Staphylococcus spp. โดยเฉพาะ S. aureus เป็นสาเหตุหลักของโรคกระดูกและข้อในสัตว์ปีก ทำให้เกิด bacterial chondronecrosis with osteomyelitis (BCO), arthritis, tenosynovitis, osteomyelitis และ bumblefoot ซึ่งแสดงออกเป็นการเดินกะเผลก (lameness)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35076352","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Staphylococci readily infect bones and joints and are associated with bacterial chondronecrosis with osteomyelitis (BCO), spondylitis, arthritis, tendinitis, tenosynovitis, osteomyelitis, turkey osteomyelitis complex (TOC), bumblefoot, dysc"}},{"id":"avian-medicine--avian-intro--staphylococcosis--v2","statement":"การรักษา staphylococcosis ด้วยยาปฏิชีวนะมักไม่ได้ผล แหล่งอ้างอิงระบุเหตุผลว่าเป็นเพราะตำแหน่งและชนิดของรอยโรค (กระดูกและข้อ ซึ่งยาเข้าถึงยาก) ร่วมกับการมีเชื้อดื้อยาหลายขนาน ไม่ได้ระบุการติดเชื้อไวรัสร่วมเป็นเหตุผลหลักอย่างที่เอกสารบรรยายอ้าง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35076352","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Antimicrobial treatment of staphylococcosis is usually ineffective due to the location and type of lesion, as well as the possible occurrence of multidrug-resistant strains."}}]},"avian-medicine--avian-intro--salmonellosis-ในคน-และภาพรวม-avian-salmonellosis":{"claims":[{"id":"avian-medicine--avian-intro--salmonellosis-ในคน-และภาพรวม-avian-salmonellosis--v1","statement":"ซัลโมเนลลา 5 ซีโรวาร์ที่เอกสารระบุว่ามีผลต่อการส่งออก ตรงกับ 5 ซีโรวาร์ที่สหภาพยุโรปกำหนดเป้าหมายควบคุมในฝูงไก่พ่อแม่พันธุ์ Gallus gallus ตามกฎหมาย คือ S. Enteritidis, S. Hadar, S. Infantis, S. Typhimurium และ S. Virchow","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-european-commission-of-2005","locator":"Article 1(1)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Salmonella enteritidis, Salmonella hadar, Salmonella infantis, Salmonella typhimurium and Salmonella virchow"}},{"id":"avian-medicine--avian-intro--salmonellosis-ในคน-และภาพรวม-avian-salmonellosis--v2","statement":"Caeca เป็นตำแหน่งหลักที่ใช้วัด colonization ของ Salmonella ในลูกไก่ และการให้ competitive exclusion culture ลดปริมาณเชื้อใน caeca ได้มากกว่า 99% เมื่อ challenge ด้วย S. Typhimurium 10,000 CFU","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12448744","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In day-old broiler chicks provided CF3, and challenged with 10,000 CFU Salmonella typhimurium greater than a 99% reduction in Salmonella cecal colonization levels was observed compared to control chicks."}}]},"avian-medicine--avian-intro--non-motile-serovar-pullorum-disease-และ-fowl-typhoid":{"claims":[{"id":"avian-medicine--avian-intro--non-motile-serovar-pullorum-disease-และ-fowl-typhoid--v1","statement":"S. enterica serovar Gallinarum biovar Gallinarum และ biovar Pullorum เป็นเชื้อที่จำเพาะกับโฮสต์สัตว์ปีก และก่อโรคแบบ systemic ที่รุนแรง คือ fowl typhoid (FT) และ Pullorum disease (PD) ตามลำดับ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38247582","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"They are bacterial pathogens that exhibit host specificity for poultry and aquatic birds, causing severe systemic diseases known as fowl typhoid (FT) and Pullorum disease (PD), respectively."}},{"id":"avian-medicine--avian-intro--non-motile-serovar-pullorum-disease-และ-fowl-typhoid--v2","statement":"ต่างจากกลุ่ม motile serovar การติดเชื้อ S. Pullorum หรือ S. Gallinarum ไม่ก่อการอักเสบในทางเดินอาหารอย่างชัดเจน เนื่องจากไม่มี flagella จึงไม่ถูกจดจำโดย TLR5 ซึ่งเป็นตัวจุดชนวนการตอบสนองแบบอักเสบ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-19070366","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Infection with S. Pullorum or S. Gallinarum does not cause substantial inflammation, unlike S. Typhimurium or S. Enteritidis... The absence of flagella in S. Gallinarum and S. Pullorum means they are not recognised by TLR5"}},{"id":"avian-medicine--avian-intro--non-motile-serovar-pullorum-disease-และ-fowl-typhoid--v3","statement":"ในกรณี S. Pullorum สัตว์จำนวนไม่น้อยกลายเป็นพาหะที่มีเชื้อคงอยู่ใน macrophage ของม้าม และเมื่อแม่ไก่เข้าสู่วัยเจริญพันธุ์ เชื้อจะลามไปยังระบบสืบพันธุ์และไข่ ซึ่งอธิบายว่าทำไมการกำจัดสัตว์พาหะจึงเป็นหัวใจของการควบคุมโรค","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-19070366","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In S. Pullorum a significant number of animals develop persistent infection of splenic macrophages... In carrier animals persistence may lead to reproductive tract and egg infection associated with a decline in CD4+ T cell numbers and funct"}}]},"avian-medicine--avian-intro--motile-serovar-paratyphoid-infection":{"claims":[{"id":"avian-medicine--avian-intro--motile-serovar-paratyphoid-infection--v1","statement":"การควบคุม GI colonization ด้วย competitive exclusion culture ป้องกันการตั้งรกรากของทั้ง S. Enteritidis และ S. Typhimurium ในลูกไก่แรกฟักได้จริง โดยวัดจากจำนวนเชื้อใน caeca และตับ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-9105931","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The results for birds pretreated with Broilact showed a distinct protective effect against both S. enteritidis and S. typhimurium at a challenge dose of 10(4) cfu/bird."}}]},"avian-medicine--avian-intro--avian-adenoviruses-และ-inclusion-body-hepatitis-ibh":{"claims":[{"id":"avian-medicine--avian-intro--avian-adenoviruses-และ-inclusion-body-hepatitis-ibh--v1","statement":"ในประเทศไทยมีรายงาน fowl adenovirus (FAdV) 3 ซีโรไทป์ที่สัมพันธ์กับ inclusion body hepatitis (IBH) คือ FAdV-2, FAdV-8b และ FAdV-11 ตรงกับที่เอกสารบรรยายระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-42436524","locator":"Abstract, Background","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In Thailand, FAdV-2, 8b, and 11 have been reported in association with inclusion body hepatitis (IBH), however, AGE remains undocumented."}},{"id":"avian-medicine--avian-intro--avian-adenoviruses-และ-inclusion-body-hepatitis-ibh--v2","statement":"Fowl adenovirus serotype 2 เป็นสาเหตุของ inclusion body hepatitis ที่ส่งผลเสียต่ออุตสาหกรรมไก่เนื้อของไทยจริง มีการพัฒนา indirect ELISA จาก recombinant hexon protein เพื่อใช้เฝ้าระวังโรคนี้ในไทย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-24141320","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Fowl adenovirus (FAdv) serotype 2 causes inclusion body hepatitis (IBH) disease which adversely affects the broiler industry in Thailand."}}]},"avian-medicine--avian-intro--egg-drop-syndrome-โรคไข่นิ่ม-ไข่หนัง":{"claims":[{"id":"avian-medicine--avian-intro--egg-drop-syndrome-โรคไข่นิ่ม-ไข่หนัง--v1","statement":"Egg drop syndrome 1976 (EDS-76) เกิดจาก adenovirus ที่มีคุณสมบัติ haemagglutinating และไอโซเลตทั้งหมดเหมือนกันทางซีรัมวิทยา ซึ่งเป็นพื้นฐานที่ทำให้ใช้ haemagglutination inhibition (HI) ตรวจแอนติบอดีได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-15379439","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Egg drop syndrome 1976 (EDS-76) is caused by a haemagglutinating adenovirus... All isolates are serologically identical"}},{"id":"avian-medicine--avian-intro--egg-drop-syndrome-โรคไข่นิ่ม-ไข่หนัง--v2","statement":"EDS virus เพิ่มจำนวนได้ดีกว่าในไข่เป็ดและ duck embryo fibroblast เมื่อเทียบกับไข่ไก่ SPF และ chicken embryo fibroblast ซึ่งสอดคล้องกับที่เอกสารบรรยายว่าเชื้อมีต้นกำเนิดจากเป็ดแล้วข้ามมาติดไก่","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38028827","locator":"Abstract, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The findings showed that duck egg embryos and primary DEF cell lines are more appropriate for EDSV replication, compared to CEF and SPF chicken eggs."}},{"id":"avian-medicine--avian-intro--egg-drop-syndrome-โรคไข่นิ่ม-ไข่หนัง--v3","statement":"สำหรับการตรวจหาตัวเชื้อ EDS (แอนติเจนหรือจีโนม) แนะนำให้ใช้ PCR โดยทำโดยตรงกับ tissue homogenate ที่ต้ม ส่วนตัวอย่างที่ให้ผลลบให้เพาะใน embryonated duck egg ก่อนตรวจซ้ำ ซึ่งเป็นคนละวัตถุประสงค์กับ HI ที่ใช้ตรวจแอนติบอดี","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-14522711","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"For diagnosis of EDS viral infections, PCR is recommended due to its ease and the lack of requirement of prepared reagents such as mAbs or conjugates. We recommend that PCR be performed directly on boiled tissue homogenates."}}]},"avian-medicine--avian-intro--ornithobacterium-rhinotracheale-ort":{"claims":[{"id":"avian-medicine--avian-intro--ornithobacterium-rhinotracheale-ort--v1","statement":"Ornithobacterium rhinotracheale (ORT) เป็นแบคทีเรียแกรมลบรูปแท่ง pleomorphic ที่ก่อโรคทางเดินหายใจ และในไก่อายุมากจะเกิดรอยโรครุนแรงกว่าและตายมากกว่า จึงเป็นปัญหาสำคัญเป็นพิเศษในไก่พันธุ์ ตรงกับที่เอกสารบรรยายระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-40249587","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In older birds, ORT causes more severe lesions and increases in mortality; therefore it is of particular concern in the breeder industry because infection and loss of production in breeders impact all stages of production."}},{"id":"avian-medicine--avian-intro--ornithobacterium-rhinotracheale-ort--v2","statement":"ORT ติดต่อได้ทั้งแนวราบและแนวดิ่ง เพาะแยกเชื้อได้ยาก การดื้อยาปฏิชีวนะที่ใช้ทั่วไปเป็นเรื่องพบบ่อยจึงทำให้การรักษายาก และวัคซีนที่พัฒนาขึ้นเป็นวัคซีนเชื้อตายสำหรับไก่พ่อแม่พันธุ์เนื้อ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10705607","locator":"Abstract (English)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"It is transmitted horizontally as well as vertically. O. rhinotracheale is difficult to isolate... Treatment can be difficult, because acquired resistance against the regular antibiotics is common in O. rhinotracheale isolates. An inactivat"}},{"id":"avian-medicine--avian-intro--ornithobacterium-rhinotracheale-ort--v3","statement":"อาการทางคลินิกและรอยโรคของ ORT มีค่าน้อยมากในการวินิจฉัย ต้องยืนยันด้วยการแยกเชื้อและระบุชนิดเชื้อ และ/หรือการตรวจแอนติบอดี ซึ่งสนับสนุนที่เอกสารบรรยายบอกว่าผล seropositive อย่างเดียวยืนยันโรคไม่ได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-9581349","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Clinical signs and lesions are of little value in diagnosis. Accurate diagnosis must be substantiated by isolation and identification of the causative bacteria and/or detection of antibodies using serological examination."}}]},"avian-medicine--avian-intro--campylobacter":{"claims":[{"id":"avian-medicine--avian-intro--campylobacter--v1","statement":"การศึกษา source attribution ในเดนมาร์กด้วยสองแบบจำลองระบุว่า แหล่งหลักของ campylobacteriosis ในคนคือไก่เนื้อ โดยแบบจำลอง Asymmetric Island ให้ 52% จากไก่ในประเทศบวก 17% จากไก่นำเข้า (รวมประมาณ 69%) ซึ่งอยู่ในช่วง 50-70% ตามที่เอกสารบรรยายระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-24168860","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Both models used indicate that the major burden of human campylobacteriosis in Denmark originates from the domestic broiler chicken reservoir... The Asymmetric Island model attributed 52% to Danish chicken, 17% to imported chicken"}}]},"avian-medicine--avian-intro--listeriosis":{"claims":[{"id":"avian-medicine--avian-intro--listeriosis--v1","statement":"Listeria monocytogenes เป็นแบคทีเรียแกรมบวกและเป็น facultative intracellular pathogen จริง และในคนกลุ่มเสี่ยง คือผู้สูงอายุ ผู้ที่มีภูมิคุ้มกันบกพร่อง และหญิงตั้งครรภ์ เชื้อสามารถข้าม blood-brain barrier และรกได้ ทำให้เกิด meningoencephalitis และการติดเชื้อในทารกในครรภ์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-33583696","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Listeria monocytogenes is a foodborne pathogen responsible for listeriosis, an infection that can manifest in humans as bacteremia, meningoencephalitis in immunocompromised patients and the elderly, and fetal-placental infection in pregnant"}},{"id":"avian-medicine--avian-intro--listeriosis--v2","statement":"L. monocytogenes เป็นแบคทีเรียแกรมบวกแบบ saprophyte ที่ปรับตัวทนสภาวะเครียดได้ดีมากจนกระจายอยู่ทั่วไป (ubiquitous) และวิธีถนอมอาหารกับการฆ่าเชื้อในโรงงานแปรรูปหลายวิธียังป้องกันการปนเปื้อนได้ไม่ดีพอ ซึ่งสนับสนุนที่เอกสารบรรยายว่าเชื้ออยู่ได้ทุกที่และปนเปื้อนในเนื้อได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34612177","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"It has evolved an exceptional ability to adapt to stress conditions encountered in different environments, resulting in a ubiquitous distribution. Because some food preservation methods and disinfection protocols in food-processing environm"}},{"id":"avian-medicine--avian-intro--listeriosis--v3","statement":"Listeria monocytogenes เป็นเชื้อที่ติดต่อทางอาหารและก่อโรคทั้งในสัตว์และคน โดยสุกรทำหน้าที่เป็นแหล่งรังโรคแบบไม่แสดงอาการ ตรงกับที่เอกสารระบุว่าสุกรมักเป็นพาหะและเป็นเชื้อติดต่อสู่คน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-33024008","locator":"Abstract, Background","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Listeria monocytogenes is a foodborne bacterial pathogen that causes listeriosis, an infectious disease in animals and people, with pigs acting as asymptomatic reservoirs."}},{"id":"avian-medicine--avian-intro--listeriosis--v4","statement":"การสำรวจตามสายการผลิตสุกรจากฟาร์มถึงโรงฆ่าพบ L. monocytogenes ที่ต่อมทอนซิลมากที่สุด (ร้อยละ 24) ขณะที่พบใน rectal swab และเนื้อหาในลำไส้เพียงร้อยละ 1 ยืนยันภาพการเป็นพาหะที่ระบบทางเดินหายใจส่วนต้นมากกว่าการเป็นโรค","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-20377951","locator":"Abstract, results of 1,962 samples from 364 pigs","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The prevalence of L. monocytogenes was 11, 1, 1, 24, 5, 1, and 4% in feed and litter, rectal swabs, intestinal contents, tonsils, pluck sets (including lungs, heart, liver, and kidney), carcasses, and meat cuts, respectively."}}]},"avian-medicine--avian-intro--histomoniasis-black-head-disease":{"claims":[{"id":"avian-medicine--avian-intro--histomoniasis-black-head-disease--v1","statement":"ในธรรมชาติ Histomonas meleagridis ถ่ายทอดผ่านไข่ของพยาธิตัวกลม Heterakis gallinarum โดยโปรโตซัวเข้าไปอยู่ในเนื้อเยื่อของพยาธิทั้งตัวผู้และตัวเมียแล้วถูกพาไปอยู่ในไข่พยาธิ ซึ่งเป็นเหตุผลที่โปรแกรมถ่ายพยาธิเป็นมาตรการป้องกันโรคโปรโตซัวชนิดนี้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38982636","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Under natural conditions, the parasite is transmitted through eggs of a nematode, Heterakis gallinarum, that shares its hosts with Hi. meleagridis. The protozoan infects tissues of both male and female He. gallinarum and eventually is carri"}},{"id":"avian-medicine--avian-intro--histomoniasis-black-head-disease--v2","statement":"ไก่งวงไวต่อโรคมากกว่าไก่อย่างชัดเจน อัตราตายในไก่งวงบางครั้งเข้าใกล้ 100% ของฝูง ขณะที่ในไก่อัตราตายประมาณ 10-20% แม้จะป่วยเป็นจำนวนมากก็ตาม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16404985","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Blackhead disease causes high mortality in turkeys, sometimes approaching 100% of a flock. In chickens, the mortality may be 10%-20% with high morbidity, although many outbreaks pass unnoticed."}},{"id":"avian-medicine--avian-intro--histomoniasis-black-head-disease--v3","statement":"การแบนยากลุ่ม nitroimidazole ในสหรัฐอเมริกาและยุโรปตามมาด้วยจำนวนเคสที่เพิ่มขึ้นในไก่งวงและไก่ และเนื่องจากยังไม่มีวัคซีน การป้องกันจึงต้องอาศัยการควบคุมพยาธิร่วมกับการจัดการฟาร์ม ตรงกับที่เอกสารบรรยายระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16404985","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The ban of nitroimidazole products in the United States and Europe was followed by an upsurge in reported cases in turkeys and chickens... The lack of suitable treatment drugs or vaccines emphasizes the importance of prevention by worm cont"}}]},"avian-medicine--avian-intro--ภาพรวม-mycotic-infection-ในสัตว์ปีก":{"claims":[{"id":"avian-medicine--avian-intro--ภาพรวม-mycotic-infection-ในสัตว์ปีก--v1","statement":"การเก็บวัตถุดิบอาหารสัตว์ในสภาพฟาร์มเขตร้อนชื้นของไทยเพิ่มระดับ aflatoxin B1 จริง การศึกษาในฟาร์มโคนม 63 แห่งที่เชียงใหม่พบว่าหลังเก็บเพียง 1 เดือน (หรือ 1 สัปดาห์สำหรับอาหารหมัก) ระดับ AF-B1 เพิ่มขึ้นประมาณ 2 ถึง 3 เท่าอย่างมีนัยสำคัญ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28367869","locator":"Abstract, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Concentrations of AF-B1 at before storage in all feeds were significantly lower than after storage (P<0.01), and the increased ratio of AF-B1 levels was approximately 2 to 3 times."}}]},"avian-medicine--avian-intro--aspergillosis-brooder-pneumonia":{"claims":[{"id":"avian-medicine--avian-intro--aspergillosis-brooder-pneumonia--v1","statement":"การตายในลูกไก่เนื้อระยะแรกจาก aspergillosis กระจุกตัวในสัปดาห์แรกของชีวิตจริง การสำรวจ 87 outbreak ในลูกไก่อายุไม่เกิน 2 สัปดาห์พบว่า aspergillosis ทำให้ตายในสัปดาห์แรก 1.0% ต่างจาก colibacillosis salmonellosis และ gout ที่ทำให้ตายมากกว่าในสัปดาห์ที่สอง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-39737043","locator":"Abstract, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Colibacillosis (2.1%), salmonellosis (3.2%), and gout (1.7%) were responsible for causing higher mortality (3.2%) in the second week of life of broilers, aspergillosis in the first week (1.0%)"}},{"id":"avian-medicine--avian-intro--aspergillosis-brooder-pneumonia--v2","statement":"ในลูกไก่เนื้อที่ติด Aspergillus fumigatus พบ granulomatous nodule จำนวนมากที่ปอดและ thoracic air sac เป็นหลัก โดยแสดงอาการอ้าปากหายใจ (gasping) ซึม ผอม และตายมาก ส่วนในไก่ไข่โตพบเพียงก้อนใหญ่ไม่กี่ก้อนที่ abdominal air sac","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-2697044","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The disease in broiler chicks was characterized by gasping, droopiness, emaciation and heavy mortality... The nodules were numerous and affected mainly the lungs and thoracic air sacs in the broiler chicks while only few large nodules were "}}]},"avian-medicine--avian-intro--candidiasis-crop-mycosis-thrush-และ-favus-white-comb":{"claims":[{"id":"avian-medicine--avian-intro--candidiasis-crop-mycosis-thrush-และ-favus-white-comb--v1","statement":"รอยโรคของ crop candidiasis คือแผ่นคราบสีขาวคล้ายนมบูด (white curd-like plaque) ในกระเพาะพัก โดยพบ Candida albicans ยืนยันด้วย immunohistochemistry กระจายอยู่ที่ลิ้น choanal mucosa หลอดอาหาร และกระเพาะพัก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-27610735","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"At necropsy, white curd-like plaques were observed in the crop. Fungal elements that stained positive for Candida albicans with immunohistochemistry were distributed throughout the tongue, choanal mucosa, esophagus, and crop."}},{"id":"avian-medicine--avian-intro--candidiasis-crop-mycosis-thrush-และ-favus-white-comb--v2","statement":"Candida albicans เป็นเชื้อหลักที่พบในกระเพาะพักไก่เนื้อ คิดเป็น 95% ของไอโซเลต และในไก่สุขภาพดีพบเชื้อได้ 17.4-51.5% แต่มีน้อยกว่า 1% ที่เห็นรอยโรค จึงสนับสนุนว่าโรคนี้มักเป็น local lesion ไม่ใช่ systemic infection","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-1103110","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Of the 573 birds examined in this study less than 1% exhibited visible lesions attributable to Candida. C. albicans comprised 95% of the isolates"}},{"id":"avian-medicine--avian-intro--candidiasis-crop-mycosis-thrush-และ-favus-white-comb--v3","statement":"Favus (avian dermatophytosis) เกิดจาก Microsporum gallinae ให้รอยโรคเป็นคราบสีขาวที่หงอน หน้า และติ่งหู แล้วลามลงคอ วินิจฉัยได้ด้วยการเพาะบน Sabouraud dextrose agar ร่วมกับ dermatophyte test medium และการตรวจจุลพยาธิวิทยา","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-8141747","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The appearance of white plaques on the comb, face, and/or ear lobes was followed by feather loss starting at the caudal base of the comb... The samples were examined histologically and by culturing on Sabouraud's dextrose agar and dermatoph"}}]},"avian-medicine--avian-intro--mycotoxicosis-ชนิดของสารพิษและปัจจัยที่ทำให้เกิดพิษ":{"claims":[{"id":"avian-medicine--avian-intro--mycotoxicosis-ชนิดของสารพิษและปัจจัยที่ทำให้เกิดพิษ--v1","statement":"Aflatoxin B1 เป็น aflatoxin ที่มีความเป็นพิษสูงสุด สร้างโดยเชื้อรา Aspergillus กลุ่มที่สร้างสารพิษได้ และมีลักษณะที่อธิบายไว้ชัดเจนว่าลดสมรรถภาพการผลิตและทำให้ไก่เนื้อตาย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34228958","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Aflatoxin B1 (AFB1), the most potent aflatoxin, is well characterized to reduce productive performance and mortality in broilers."}}]},"avian-medicine--avian-intro--aflatoxin-และ-ochratoxin":{"claims":[{"id":"avian-medicine--avian-intro--aflatoxin-และ-ochratoxin--v1","statement":"Aflatoxin B1 ก่อความเสียหายต่อตับ (liver damage) พิษต่อสารพันธุกรรม (genotoxicity) และกดภูมิคุ้มกัน (immunosuppression) ในไก่เนื้อ ผ่านกลไก oxidative stress และการสร้าง AFB1 macromolecular adduct ตรงกับที่เอกสารบรรยายอธิบาย pathogenesis ว่าเกิดจาก active metabolite ที่ไปจับ DNA และ RNA","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34228958","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The biochemical and molecular mode of action of AFB1 to induce liver damage, genotoxicity, immunosuppression and the protective effect of plant products against such mechanisms and their toxic effects are discussed."}},{"id":"avian-medicine--avian-intro--aflatoxin-และ-ochratoxin--v2","statement":"รอยโรคของ aflatoxicosis ในไก่ตรงกับที่เอกสารบรรยายระบุ คือน้ำหนักสัมพัทธ์ของตับ ไต proventriculus และกึ๋นเพิ่มขึ้น (ตับไตขยายใหญ่) ขณะที่น้ำหนักสัมพัทธ์ของ bursa ลดลง (bursa ฝ่อ จึงกดภูมิ) ร่วมกับโปรตีนรวมและอัลบูมินในซีรัมลดลง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-1973286","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"caused a significant increase in the relative weights of the liver, kidney, proventriculus, and gizzard as well as significant increases in activity of serum gamma glutamyltransferase; also, significant decreases in the relative bursa weigh"}},{"id":"avian-medicine--avian-intro--aflatoxin-และ-ochratoxin--v3","statement":"Ochratoxin A สร้างโดยเชื้อรา Aspergillus และ Penicillium และก่อพิษต่อไตในไก่เนื้อจริง โดยทำให้ creatinine กรดยูริก และ BUN ในซีรัมสูงขึ้น เพิ่ม malondialdehyde ในไต ลดสารต้านอนุมูลอิสระในไต และพบรอยโรคทางพยาธิวิทยาหลายแบบที่ไตร่วมกับการเกิด apoptosis","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-36179809","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The mycotoxin ochratoxin A (OTA) is produced by the fungi Aspergillus and Penicillium... The results demonstrated that OTA exposure increased serum levels of creatinine, uric acid, and blood urea nitrogen... OTA-exposed chickens exhibited m"}}]},"avian-medicine--avian-intro--citrinin-trichothecenes-fumonisins-zearalenone-ergotism":{"claims":[{"id":"avian-medicine--avian-intro--citrinin-trichothecenes-fumonisins-zearalenone-ergotism--v1","statement":"T-2 toxin และ diacetoxyscirpenol (DAS) ซึ่งเป็น trichothecene จาก Fusarium ทำให้เกิดรอยโรคเป็นแผ่นสีเหลืองและเนื้อตายที่จงอยปาก ลิ้น และมุมปากของลูกไก่เนื้อจริง ขณะที่ crotocin ไม่ทำให้เกิดรอยโรคเช่นนี้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-674054","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Chicks fed the diet containing DAS and T-2 toxin showed yellowish plaque-type lesions on the beak, tongue, and angle of the mouth. Crotocin did not cause such lesions"}},{"id":"avian-medicine--avian-intro--citrinin-trichothecenes-fumonisins-zearalenone-ergotism--v2","statement":"รอยโรคในช่องปากจาก scirpenol trichothecene สัมพันธ์กับขนาดที่ได้รับ (dose-related) และไวเท่ากับหรือมากกว่าการหยุดโต จึงใช้เป็นตัวชี้วัดพิษ trichothecene ได้ดี โดยมุมปาก (angles) และจงอยปากบนเป็นตำแหน่งที่ถูกกระทบมากที่สุดสำหรับ T-2 กลุ่ม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-1956853","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The mouth lesions provoked by each scirpenol were dose-related... Thus, mouth lesions were of equal or greater sensitivity than growth inhibition as an indicator of scirpenol toxicity."}},{"id":"avian-medicine--avian-intro--citrinin-trichothecenes-fumonisins-zearalenone-ergotism--v3","statement":"Ergot คือ Claviceps purpurea ที่ปนมากับเมล็ดธัญพืชในสูตรอาหารจริง โดยมี ergot alkaloid หลักคือ ergocristine, ergometrine, ergotamine และ ergocornine อย่างไรก็ตามในการทดลอง dose-response ที่ควบคุม ไก่ไวต่อ ergot น้อยกว่าลูกสุกร และในไก่ผลกระทบที่วัดได้คือการกินอาหารลดลงกับเอนไซม์ตับในซีรัมเปลี่ยนแปลง ไม่ได้รายงานเนื้อตายที่อวัยวะส่วนปลาย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16080303","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"increasing amounts of ergot (Claviceps purpurea) with a defined alkaloid content and pattern... showed the following composition: ergometrine 8.1%, ergotamine 5.4%, ergocomine 3.2%, alpha-ergocryptine 1.9%, ergocristine 14.9%... piglets see"}}]},"avian-medicine--avian-intro--การวินิจฉัยและการควบคุมสารพิษจากเชื้อรา":{"claims":[{"id":"avian-medicine--avian-intro--การวินิจฉัยและการควบคุมสารพิษจากเชื้อรา--v1","statement":"Hydrated sodium calcium aluminosilicate (HSCAS) เป็นสารดูดซับที่มีความสัมพันธ์สูงกับ aflatoxin B1 การเติมในอาหารเพียง 0.5% ลดผลเสียของ AFB1 ที่ระดับ 7.5 มก. ต่อกิโลกรัมอาหารในลูกไก่ไข่และไก่เนื้อได้อย่างมีนัยสำคัญ ยืนยันสิ่งที่เอกสารบรรยายระบุว่ากลุ่ม clay อะลูมิโนซิลิเกตและ zeolite จับ aflatoxin ได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-2837754","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The HSCAS, when added to the diet of Leghorn and broiler chicks at a level of .5%, significantly diminished the adverse effects of feeding 7.5 mg AFB1/kg of feed."}},{"id":"avian-medicine--avian-intro--การวินิจฉัยและการควบคุมสารพิษจากเชื้อรา--v2","statement":"HSCAS ลดผลยับยั้งการเจริญเติบโตจาก aflatoxin ในลูกไก่ได้ 50-67% ขณะที่ activated charcoal ที่ระดับเดียวกันไม่แสดงคุณสมบัติป้องกัน จึงเป็นข้อมูลเปรียบเทียบว่าไม่ใช่สารดูดซับทุกชนิดจะใช้แทนกันได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-1973286","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The HSCAS significantly diminished the growth-inhibitory effects of AFB1 or of AF on growing chicks by 50 to 67 percent... adding activated charcoal to the diet did not appear to have protective properties against the effects of aflatoxin B"}}]}},"avian-medicine--avian-myco":{"avian-medicine--avian-myco--ลักษณะเชื้อและชนิดที่พบในสัตว์ปีก":{"claims":[{"id":"avian-medicine--avian-myco--ลักษณะเชื้อและชนิดที่พบในสัตว์ปีก--v1","statement":"Mycoplasma gallisepticum มีลักษณะเด่นคือไม่มีผนังเซลล์โดยสิ้นเชิง สามารถก่อการติดเชื้อแบบคงอยู่ (persistent infection) ในโฮสต์ และติดต่อได้ทั้งแนวราบและแนวดิ่ง ตรงกับที่เอกสารบรรยายระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-36006306","locator":"Section 1, Introduction","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The bacterium is unusual in its complete lack of a cell wall, its ability to cause a persistent infection within a host and its potential for both horizontal and vertical transmission."}}]},"avian-medicine--avian-myco--mg-m-gallisepticum-การติดต่อ-อาการ-รอยโรค":{"claims":[{"id":"avian-medicine--avian-myco--mg-m-gallisepticum-การติดต่อ-อาการ-รอยโรค--v1","statement":"ในไก่เนื้อ MG สัมพันธ์กับ chronic respiratory disease (CRD) น้ำหนักเพิ่มลดลง และการตัดซากทิ้ง และเชื้อมีแนวโน้มร่วมกับเชื้ออื่นเช่น E. coli หรือ avian metapneumovirus ทำให้โรครุนแรงขึ้น ตรงกับที่เอกสารบรรยายระบุเรื่องรอยโรคจาก secondary infection","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-36006306","locator":"Section 1, Introduction","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In broiler chickens it is associated with chronic respiratory disease (CRD), reduced weight gain and carcass condemnations... Another feature of MG is its propensity combine with other pathogens, for example [E. coli] or Avian Metapneumovir"}}]},"avian-medicine--avian-myco--ms-m-synoviae-ข้ออักเสบและ-egg-apex-abnormality":{"claims":[{"id":"avian-medicine--avian-myco--ms-m-synoviae-ข้ออักเสบและ-egg-apex-abnormality--v1","statement":"M. synoviae ทำให้เกิดรอยโรคที่จำกัดอยู่เฉพาะด้านแหลม (apex) ของเปลือกไข่ เห็นเป็นบริเวณหยาบสีเข้มขนาดราว 2 ซม. ขอบชัด ร่วมกับเปลือกแตกง่ายและผลผลิตไข่ลดลง ซึ่งตรงกับ Egg Apex Abnormality (EAA) ที่สรุประบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section A.1 Description and impact of the disease, p. 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The lesions appear to be confined to the apex of the shell and consist of rough dark areas of 2 cm in diameter with clear edges; in addition, a decrease in egg production is reported."}},{"id":"avian-medicine--avian-myco--ms-m-synoviae-ข้ออักเสบและ-egg-apex-abnormality--v2","statement":"อาการทางคลินิกของ MS ได้แก่ หงอนซีด ขากะเผลก โตช้า ข้อบวม ขี้เขียวที่มี urate มาก และในข้อกับปลอกหุ้มเอ็นพบของเหลวหนืดสีครีมถึงเทา ร่วมกับตับม้ามโตและไตบวมลาย","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section A.1 Description and impact of the disease, p. 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Joints may contain a viscous, creamy to grey exudate in the joint and along tendon sheaths, along with hepatosplenomegaly and mottled, swollen kidneys."}},{"id":"avian-medicine--avian-myco--ms-m-synoviae-ข้ออักเสบและ-egg-apex-abnormality--v3","statement":"ไข่ที่เป็น EAA มีความแข็งแรงของเปลือกต่ำกว่าไข่ปกติอย่างมีนัยสำคัญ (22.8 นิวตัน เทียบกับ 33.7 ถึง 39.5 นิวตัน) ซึ่งเป็นหลักฐานเชิงตัวเลขว่าเปลือกบางลงจริงและแตกง่าย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-19937520","locator":"Abstract, results; 38(5):333-40","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The eggshell strength of eggs with EAA (22.8 N) was significantly lower (P<0.05) than non-affected eggs from the other groups (33.7 to 39.5 N)."}},{"id":"avian-medicine--avian-myco--ms-m-synoviae-ข้ออักเสบและ-egg-apex-abnormality--v4","statement":"NAD (nicotinamide adenine dinucleotide) เป็นสารที่จำเป็นต่อการเพาะแยกเชื้อ MS ในครั้งแรก แต่สามารถตัดออกจากอาหารเลี้ยงเชื้อสำหรับ MG ได้ ตรงกับที่สรุประบุว่า MS ต้องการ NAD มากกว่า MG","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section B.1.1 In-vitro culture, p. 4","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Nicotinamide adenine dinucleotide (NAD) is a growth requirement for the primary isolation of MS, but it may be omitted in the medium for the cultivation of MG."}},{"id":"avian-medicine--avian-myco--ms-m-synoviae-ข้ออักเสบและ-egg-apex-abnormality--v5","statement":"วัคซีนเชื้อเป็นสายพันธุ์ MS-H แนะนำให้โดยการหยอดตา และการทำวัคซีนด้วยวัคซีน MS เชื้อเป็นลดการเกิด EAA ลงได้อย่างมีนัยสำคัญ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Summary, Requirements for vaccines, p. 1","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Eyedrop administration is advised for the MS-H strain whereas fine aerosol is recommended for MS1."}}]},"avian-medicine--avian-myco--diagnostic-tools-และ-serology":{"claims":[{"id":"avian-medicine--avian-myco--diagnostic-tools-และ-serology--v1","statement":"ในสัตว์มีชีวิต tracheal swab ถือเป็นตัวอย่างที่ดีที่สุดสำหรับเพาะแยก mycoplasma และสามารถเก็บ swab จาก choanal cleft ได้ด้วย ส่วนซากเก็บจากหลอดลม ปอด ถุงลม ท่อนำไข่ และข้อ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section B.1.1 In-vitro culture, p. 4","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The tracheal swab is considered to be the best sample in live animals for most mycoplasma species. In addition, for isolation purposes, it is possible to collect swabs from the choanal cleft."}},{"id":"avian-medicine--avian-myco--diagnostic-tools-และ-serology--v2","statement":"ซีรัมที่ให้ผลบวกในการทดสอบ rapid serum plate agglutination (RSA หรือ SPA) ต้องนำไปยืนยันต่อด้วย ELISA หรือ HI เสมอ โดยทำ RSA เป็นการทดสอบคัดกรองเบื้องต้นเท่านั้น","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Summary, Serological tests, p. 1","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Sera that still react, especially when diluted, are considered positive and are tested by either ELISA or HI for confirmation."}},{"id":"avian-medicine--avian-myco--diagnostic-tools-และ-serology--v3","statement":"ห้ามแช่แข็งซีรัมก่อนนำมาทดสอบ RSA และซีรัมต้องไม่มี haemolysis หรือการปนเปื้อน เพื่อเลี่ยงปฏิกิริยาที่ไม่จำเพาะ ซึ่งเป็นเหตุผลเดียวกับที่สรุปเตือนเรื่องซีรัมแช่แข็งให้ผลบวกลวง","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section B.2.4.3 Additional comments, p. 14","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Samples of serum should not be frozen before use in RSA tests. They should be free from haemolysis and contamination to avoid nonspecific reactions."}},{"id":"avian-medicine--avian-myco--diagnostic-tools-และ-serology--v4","statement":"การทดสอบทางซีรัมวิทยาสำหรับ mycoplasma ที่ใช้กันทั่วไปขาดความจำเพาะและหรือความไว จึงแนะนำอย่างยิ่งให้ใช้เพื่อเฝ้าระวังระดับฝูงเท่านั้น ไม่ใช่เพื่อตัดสินสัตว์รายตัว","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section B.2 Serological tests, p. 11","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The serological tests in common use lack specificity and/or sensitivity. It is strongly recommended that their use is limited to flock monitoring rather than testing individual birds."}},{"id":"avian-medicine--avian-myco--diagnostic-tools-และ-serology--v5","statement":"Real-time PCR เป็นวิธีที่ WOAH แนะนำสูงสุดสำหรับยืนยันเคสทางคลินิกและประเมินความชุก ขณะที่การเพาะแยกเชื้อบนอาหารเลี้ยงเชื้อถูกจัดว่าเหมาะสมในสถานการณ์จำกัดเท่านั้น","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Table 1. Test methods available for diagnosis of avian mycoplasmosis, p. 3","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Real-time PCR: +++ for confirmation of clinical cases; key: +++ = recommended for this purpose; + = suitable in very limited circumstances."}}]},"avian-medicine--avian-myco--วัคซีน-mg-เชื้อตาย-เชื้อเป็น-3-สายพันธุ์-และ-fp-mg":{"claims":[{"id":"avian-medicine--avian-myco--วัคซีน-mg-เชื้อตาย-เชื้อเป็น-3-สายพันธุ์-และ-fp-mg--v1","statement":"วัคซีน MG เชื้อเป็นสำหรับไก่ผลิตจากสายพันธุ์ F, ts-11 และ 6/85 โดยแนะนำวิธีหยอดตาสำหรับ ts-11 และพ่นละอองฝอยสำหรับ 6/85 ตรงกับที่สรุประบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Summary, Requirements for vaccines, p. 1","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The eyedrop method is recommended for ts-11, and a fine spray for 6/85."}},{"id":"avian-medicine--avian-myco--วัคซีน-mg-เชื้อตาย-เชื้อเป็น-3-สายพันธุ์-และ-fp-mg--v2","statement":"วัคซีน MG สายพันธุ์ F ก่อโรคได้ในไก่และก่อโรคในไก่งวง จึงเป็นสายพันธุ์ที่เสี่ยงสูงและไม่เหมาะกับไก่งวง ตรงกับที่สรุปเตือนไว้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-7832700","locator":"Abstract; 38(3):475-82","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Because Mycoplasma gallisepticum F strain vaccine can be pathogenic in chickens and is pathogenic in turkeys, we monitored the spread of MG F strain into unvaccinated flocks."}},{"id":"avian-medicine--avian-myco--วัคซีน-mg-เชื้อตาย-เชื้อเป็น-3-สายพันธุ์-และ-fp-mg--v3","statement":"การใช้สายพันธุ์ F ต่อเนื่องระยะยาวในฟาร์มหลายรุ่นอายุทำให้เชื้อวัคซีนเข้าแทนที่เชื้อในธรรมชาติได้ และสายพันธุ์ ts-11 เคยถูกใช้กำจัดสายพันธุ์ F ในไก่ไข่เชิงการค้าได้สำเร็จ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Summary, Requirements for vaccines, p. 1","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Long-term use of the F strain on multi-age sites can result in displacement of field strains."}},{"id":"avian-medicine--avian-myco--วัคซีน-mg-เชื้อตาย-เชื้อเป็น-3-สายพันธุ์-และ-fp-mg--v4","statement":"วัคซีนเชื้อตายเป็นแบคทีเรียเข้มข้นใน oil emulsion ให้ทางพาเรนเทอรัลแก่ไก่รุ่นอายุ 12 ถึง 16 สัปดาห์ โดยควรให้ 2 โดส และป้องกันการสูญเสียผลผลิตไข่ได้แต่ไม่ป้องกันการติดเชื้อ MG สายพันธุ์ธรรมชาติ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Summary, Requirements for vaccines, p. 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Two doses are desirable. MG bacterins are effective in preventing egg-production losses and respiratory disease, but do not prevent infection with wild-type MG."}},{"id":"avian-medicine--avian-myco--วัคซีน-mg-เชื้อตาย-เชื้อเป็น-3-สายพันธุ์-และ-fp-mg--v5","statement":"วัคซีน FP-MG เป็น recombinant fowlpox virus ที่แสดงออกยีน 40k และ mgc ของ MG และให้โดยการแทงที่ wing web ตรงกับที่สรุประบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-20460677","locator":"Abstract; 89(6):1301-6","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Vectormune FP-MG vaccine, a recombinant fowlpox virus expressing both M. gallisepticum 40k and mgc genes... The vaccine virus was serially passaged 5 times by wing-web inoculation."}},{"id":"avian-medicine--avian-myco--วัคซีน-mg-เชื้อตาย-เชื้อเป็น-3-สายพันธุ์-และ-fp-mg--v6","statement":"การใช้ยาปฏิชีวนะหลังทำวัคซีน mycoplasma เชื้อเป็นอาจรบกวนการคงอยู่และประสิทธิภาพของเชื้อวัคซีน โดยพบเชื้อสายพันธุ์ธรรมชาติบ่อยกว่าในฝูงที่ได้รับยาหลังทำวัคซีน ซึ่งสนับสนุนหลักการเว้นระยะยากับวัคซีนตามที่สรุประบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-33068825","locator":"Abstract; 250:108840","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The results also suggested that antimicrobial use after mycoplasma vaccination may interfere with vaccine strain persistence and efficacy."}}]},"avian-medicine--avian-myco--ยาปฏิชีวนะที่ใช้ได้และที่ใช้ไม่ได้ผล":{"claims":[{"id":"avian-medicine--avian-myco--ยาปฏิชีวนะที่ใช้ได้และที่ใช้ไม่ได้ผล--v1","statement":"Mycoplasma ดื้อยาโดยธรรมชาติต่อยาที่ออกฤทธิ์ที่ผนังเซลล์ ได้แก่ fosfomycin, glycopeptides และ beta-lactam รวมทั้งดื้อต่อ sulfonamides, quinolone รุ่นแรก, trimethoprim, polymyxin และ rifampicin","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30003864","locator":"Abstract; 6(4)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Mycoplasmas are intrinsically resistant to antimicrobials targeting the cell wall (fosfomycin, glycopeptides, or beta-lactam antibiotics)."}},{"id":"avian-medicine--avian-myco--ยาปฏิชีวนะที่ใช้ได้และที่ใช้ไม่ได้ผล--v2","statement":"ยาที่ใช้ควบคุมการติดเชื้อ mycoplasma ในสัตว์บ่อยที่สุดคือกลุ่ม macrolides และ tetracyclines ส่วน lincosamides, fluoroquinolones, pleuromutilins, phenicols และ aminoglycosides ก็ออกฤทธิ์ได้ โดย pleuromutilins (เช่น tiamulin) เป็นกลุ่มที่ได้ผลดีที่สุด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30003864","locator":"Abstract; 6(4)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The antibiotics most frequently used to control mycoplasmal infections in animals are macrolides and tetracyclines... Pleuromutilins are the most effective antibiotics."}},{"id":"avian-medicine--avian-myco--ยาปฏิชีวนะที่ใช้ได้และที่ใช้ไม่ได้ผล--v3","statement":"การใช้ tiamulin ร่วมกับยากลุ่ม ionophore เช่น monensin หรือ salinomycin ทำให้เกิดปฏิกิริยาเป็นพิษได้ทั้งในสุกรและสัตว์ปีก จึงห้ามใช้ร่วมกับยากันบิดกลุ่ม ionophore ตามที่สรุประบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-7966553","locator":"Abstract; 17(4):317-22","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The simultaneous use of the antibiotic tiamulin with certain ionophoric antibiotics (monensin, salinomycin) may give rise to a toxic interaction in pigs and poultry."}},{"id":"avian-medicine--avian-myco--ยาปฏิชีวนะที่ใช้ได้และที่ใช้ไม่ได้ผล--v4","statement":"Tylvalosin เป็นยาที่ออกฤทธิ์ดีที่สุดต่อเชื้อ MG และ MS ที่แยกได้จากภาคสนาม โดยมีค่า MIC ต่ำที่สุดในการทดสอบ (0.015 ถึง 0.03 ไมโครกรัมต่อมิลลิลิตร)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-31579902","locator":"Abstract; 98(12):6281-6288","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Tylvalosin was the most active antibiotic against MG and MS isolates with the lowest MIC values (0.015 to 0.03 microgram/mL)."}}]},"avian-medicine--avian-myco--หัวข้อที่สรุปบันทึกว่าถูกถามในข้อสอบชุดก่อน":{"claims":[{"id":"avian-medicine--avian-myco--หัวข้อที่สรุปบันทึกว่าถูกถามในข้อสอบชุดก่อน--v1","statement":"Mycoplasma synoviae ก่อโรค infectious synovitis และโรคระบบหายใจในไก่และไก่งวง และทำให้เกิดความผิดปกติที่ปลายแหลมของเปลือกไข่ (egg shell apex abnormalities) ในไก่ ซึ่งเป็นหัวข้อ Egg apex abnormalities ที่สรุปบันทึกไว้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-29149886","locator":"Background, first sentence of the abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Mycoplasma synoviae causes infectious synovitis and respiratory diseases in chickens and turkeys and may lead to egg shell apex abnormalities in chickens; hence possesses high economic impact on the poultry industry."}},{"id":"avian-medicine--avian-myco--หัวข้อที่สรุปบันทึกว่าถูกถามในข้อสอบชุดก่อน--v2","statement":"ts-11 และ F-strain เป็นวัคซีนเชื้อเป็นของ Mycoplasma gallisepticum ที่ใช้จริงในไก่ โดย ts-11 ให้แบบหยอดตาในไก่ไข่อายุ 12 สัปดาห์ และลดคะแนนรอยโรคถุงลมกับความชุกของการเสื่อมของรังไข่หลัง challenge ด้วยเชื้อ R-strain อย่างมีนัยสำคัญ ส่วน F-strain ให้แบบพ่นฝอยและป้องกันรอยโรคถุงลมกับท่อลมได้ ตรงกับหัวข้อ vaccine strain ts-11 และ vaccine F-strain ที่สรุปบันทึกไว้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-25571953","locator":"Abstract, Trial 1 and Trial 2","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In Trial 2, commercial layer-type chickens were vaccinated with ts-11 (via eye drop) or K-strain (via aerosol) at 12 weeks of age ... The ts-11 and K-strain vaccinated groups both had significantly lower air sac lesion scores and a lower pr"}}]}},"avian-medicine--avian-serology":{"avian-medicine--avian-serology--วิธีตรวจซีรัมกับโรคที่ใช้คู่กัน":{"claims":[{"id":"avian-medicine--avian-serology--วิธีตรวจซีรัมกับโรคที่ใช้คู่กัน--v1","statement":"การทดสอบ rapid serum plate agglutination (rapid plate test) ใช้กับทั้ง MG และ MS โดยเป็นหนึ่งในสามวิธีที่ใช้บ่อยที่สุดร่วมกับ ELISA และ HI ตรงกับที่สรุประบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Summary and Section B.2, pp. 1 and 11","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The most commonly used are the rapid serum agglutination (RSA) test, the enzyme-linked immunosorbent assay (ELISA) and the haemagglutination inhibition (HI) test."}},{"id":"avian-medicine--avian-serology--วิธีตรวจซีรัมกับโรคที่ใช้คู่กัน--v2","statement":"HI ถูกใช้เป็นการทดสอบทางซีรัมวิทยาในการวินิจฉัยไข้หวัดนกด้วย แม้จะมีข้อจำกัดว่าอาจตรวจไม่พบการติดเชื้อบางกรณีเพราะ haemagglutinin เป็นแบบจำเพาะต่อ subtype","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Summary, Serological tests, p. 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Haemagglutination inhibition tests have also been employed in routine diagnostic serology, but it is possible that this technique may miss some particular infections because the haemagglutinin is subtype specific."}},{"id":"avian-medicine--avian-serology--วิธีตรวจซีรัมกับโรคที่ใช้คู่กัน--v3","statement":"การทดสอบ haemagglutination inhibition ถูกใช้ยืนยันการวินิจฉัย egg drop syndrome 76 ในฝูงจริง โดยใช้ร่วมกับ PCR และผลบวกสอดคล้องกับช่วงที่ผลผลิตไข่ตกและเปลือกไข่ผิดปกติ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-39400224","locator":"Abstract; 68(3):282-286","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"A four-house broiler breeder farm of approximately 35-wk-old hens was diagnosed with egg drop syndrome (EDS'76) utilizing PCR and hemagglutination inhibition (HI) testing."}}]},"avian-medicine--avian-serology--paired-sera-การวินิจฉัยโรค-และการดูผลวัคซีน":{"claims":[{"id":"avian-medicine--avian-serology--paired-sera-การวินิจฉัยโรค-และการดูผลวัคซีน--v1","statement":"การใช้ HI หรือ ELISA เพื่อยืนยันเคสทางคลินิกของ mycoplasma เหมาะสมก็ต่อเมื่อสามารถวิเคราะห์ตัวอย่างคู่ (paired samples) ที่เก็บห่างกันไม่กี่สัปดาห์ได้ ซึ่งเป็นหลักการเดียวกับ paired sera ที่สรุปอธิบาย","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Table 1, footnote (f), p. 3","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"suitable provided paired samples collected a few weeks apart can be analysed."}},{"id":"avian-medicine--avian-serology--paired-sera-การวินิจฉัยโรค-และการดูผลวัคซีน--v2","statement":"ปฏิกิริยาบวกของ RSA สามารถยืนยันด้วย HI ได้เมื่อใช้ซีรัมที่เก็บหลังการติดเชื้อไปแล้ว 2 ถึง 3 สัปดาห์ ซึ่งเป็นระยะเวลาที่แอนติบอดีชนิด HI ใช้ในการพัฒนา และอธิบายว่าทำไมการเจาะครั้งแรกจึงอาจยังไม่เห็นการเปลี่ยนแปลง","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section B.2.4.3 Additional comments, p. 14","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Positive RSA reactions can be confirmed by the HI test with sera taken after the first 2-3 weeks of infection (the time taken for HI antibodies to develop)."}},{"id":"avian-medicine--avian-serology--paired-sera-การวินิจฉัยโรค-และการดูผลวัคซีน--v3","statement":"การประเมิน seroconversion หลังทำวัคซีนสามารถทำได้ตั้งแต่ 2 สัปดาห์หลังทำวัคซีน โดยตรวจพบแอนติบอดีในซีรัมของไก่ที่ได้รับวัคซีนตั้งแต่สัปดาห์ที่ 2 เป็นต้นไป ซึ่งสอดคล้องกับกรอบเวลา 14 ถึง 21 วันที่สรุประบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17992943","locator":"Abstract; 51(3):788-90","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The developed immunofiltration test could detect antibodies in the sera of experimentally vaccinated chickens from 2 wk postvaccination."}}]},"avian-medicine--avian-serology--จะยืนยันว่าฝูงไม่เคยได้วัคซีนและไม่มีการติดเชื้อได้อย่างไร":{"claims":[{"id":"avian-medicine--avian-serology--จะยืนยันว่าฝูงไม่เคยได้วัคซีนและไม่มีการติดเชื้อได้อย่างไร--v1","statement":"การพิสูจน์ว่าประชากรปลอดจากการติดเชื้อ mycoplasma ต้องใช้ทั้งการตรวจหาตัวเชื้อและการตรวจภูมิคุ้มกันร่วมกัน โดย WOAH แนะนำ real-time PCR ร่วมกับ HI หรือ ELISA และย้ำว่าควรใช้วิธีระบุตัวเชื้อหลายวิธีกับตัวอย่างเดียวกัน","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Table 1 and footnote (a), p. 3","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"A combination of agent identification methods applied on the same clinical sample is recommended."}},{"id":"avian-medicine--avian-serology--จะยืนยันว่าฝูงไม่เคยได้วัคซีนและไม่มีการติดเชื้อได้อย่างไร--v2","statement":"จำนวนตัวอย่างซีรัมที่ต้องสุ่มตรวจภายในฝูงขึ้นอยู่กับระดับการตรวจจับและช่วงความเชื่อมั่นที่ต้องการ ซึ่งเป็นเหตุผลเชิงระบาดวิทยาที่รองรับการทำ random sampling ตามที่สรุประบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section B.2 Serological tests, p. 11","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The number of sera to be tested within a flock depends on the level of detection and the confidence limits required."}}]},"avian-medicine--avian-serology--การแปลผลซีรัมในแม่พันธุ์-และกรณี-hpai-ในลูกไก่อายุ-1-วัน":{"claims":[{"id":"avian-medicine--avian-serology--การแปลผลซีรัมในแม่พันธุ์-และกรณี-hpai-ในลูกไก่อายุ-1-วัน--v1","statement":"ในสัตว์ปีก MG แพร่ในแนวดิ่งผ่านไข่ที่ติดเชื้อและแพร่ในแนวราบโดยการสัมผัสใกล้ชิด ดังนั้นแม่พันธุ์ที่ให้ผลบวกต่อ MG หรือ MS จึงหมายถึงความเสี่ยงที่จะส่งเชื้อไปยังลูก ต่างจากโรคไวรัสที่ผลบวกหมายถึงภูมิที่ส่งต่อ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section A.1 Description and impact of the disease, p. 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In poultry the infection is spread vertically through infected eggs and horizontally by close contact."}},{"id":"avian-medicine--avian-serology--การแปลผลซีรัมในแม่พันธุ์-และกรณี-hpai-ในลูกไก่อายุ-1-วัน--v2","statement":"ภูมิคุ้มกันที่ได้รับมาจากแม่ (passive immunity) อยู่ได้ราว 2 ถึง 3 สัปดาห์ และรบกวนการเพิ่มจำนวนของไวรัสวัคซีน จึงควรทำวัคซีนในลูกหลังจากระดับแอนติบอดีที่ได้รับมาลดลงแล้ว","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Section C.1 Background, p. 5","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"As passive immunity (for 2-3 weeks) may interfere with vaccine virus multiplication, such progeny should be vaccinated only after the decline of passively acquired antibody."}},{"id":"avian-medicine--avian-serology--การแปลผลซีรัมในแม่พันธุ์-และกรณี-hpai-ในลูกไก่อายุ-1-วัน--v3","statement":"โรคจากเชื้อไข้หวัดนกชนิดรุนแรงในสัตว์ที่ไวรับเต็มที่อาจแสดงเป็นการตายกะทันหันโดยไม่มีอาการนำ และเกณฑ์นิยามความรุนแรงสูงคือทำให้ตายเกิน 75 เปอร์เซ็นต์ภายใน 10 วัน ซึ่งสนับสนุนเหตุผลที่ว่าลูกไก่ที่มี Ab ต่อ HPAI น่าจะได้ภูมิจากแม่ที่ทำวัคซีน ไม่ใช่จากการติดเชื้อจริง","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Summary and Section A. Introduction, pp. 1-2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"strains are considered to be of high pathogenicity if they cause more than 75% mortality within 10 days... the highly pathogenic disease, in fully susceptible birds, may vary from one of sudden death with no overt clinical signs."}}]},"avian-medicine--avian-serology--การเก็บตัวอย่างเลือดเพื่อส่งตรวจซีรัม":{"claims":[{"id":"avian-medicine--avian-serology--การเก็บตัวอย่างเลือดเพื่อส่งตรวจซีรัม--v1","statement":"ตัวเลข 30 ตัวอย่างต่อโรงเรือนมาจากการคำนวณ design prevalence คือถ้าฝูงติดเชื้อจริงและมี seroprevalence อย่างน้อย 10% การสุ่มเจาะเลือด 30 ตัวที่กระจายทั่วฟาร์มจะเพียงพอที่จะตรวจพบ ตรงกับที่สไลด์ระบุว่าเก็บ 30 ตัวต่อ 1 โรงเรือน (ดังนั้นการเจาะเพียง 15-20 ตัวตามที่ทำจริงในภาคสนามจะยอมรับ design prevalence ที่สูงกว่า 10%)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-37494751","locator":"Section on surveillance design and random sample sizes","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Assuming that in case of infection the seroprevalence would mount to 10% at least, this would imply that we would need collect 30 samples from birds randomly distributed across the farm."}}]}},"avian-medicine--avian-vaccine-prog":{"avian-medicine--avian-vaccine-prog--ไก่เนื้อต้องใช้วัคซีนอะไร-และให้วันไหนบ้าง":{"claims":[{"id":"avian-medicine--avian-vaccine-prog--ไก่เนื้อต้องใช้วัคซีนอะไร-และให้วันไหนบ้าง--v1","statement":"วัคซีน recombinant ที่ใช้ poxvirus เป็น vector รวมถึงตัวที่แทรกยีนของ NDV สามารถให้ได้ตั้งแต่ในไข่ (in-ovo) หรือในลูกไก่อายุ 1 วันโดยฉีดใต้ผิวหนังหรือแทงที่ wing web ซึ่งสนับสนุนการให้วัคซีน ND ชนิด recombinant ที่อายุ 1 วันตามตารางที่สรุปบันทึก","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Section C.1 Background, p. 5","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Several recombinant fowlpox vaccines are available for use by in-ovo, or 1-day-of-age subcutaneous or wing-web administration."}},{"id":"avian-medicine--avian-vaccine-prog--ไก่เนื้อต้องใช้วัคซีนอะไร-และให้วันไหนบ้าง--v2","statement":"ช่วงเวลาที่เหมาะสมในการให้วัคซีน IBD ถูกกำหนดโดยจุดที่ระดับ maternally derived antibody ลดลงต่ำกว่าระดับที่ไวรัสวัคซีนทะลุผ่านได้ ซึ่งคำนวณด้วย Deventer formula จึงเป็นเหตุผลเชิงวิชาการของการให้ IBD ที่อายุราว 14 ถึง 18 วันในไก่เนื้อ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-31901750","locator":"Abstract; 220:109993","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The Deventer formula was used to determine the optimal time point of inoculation with an intermediate plus IBDV strain when maternally derived antibody (MDA) titers were below the calculated breakthrough level of the virus."}}]},"avian-medicine--avian-vaccine-prog--หลังให้วัคซีนในลูกไก่อายุ-1-10-วัน-สิ่งที่สำคัญที่สุดคืออะไร":{"claims":[{"id":"avian-medicine--avian-vaccine-prog--หลังให้วัคซีนในลูกไก่อายุ-1-10-วัน-สิ่งที่สำคัญที่สุดคืออะไร--v1","statement":"ระดับ maternally derived antibody ที่สูงเกินไปเป็นอุปสรรคต่อการทำงานของวัคซีน จึงต้องเลือกชนิดวัคซีนที่ทะลุผ่านระดับภูมิจากแม่ได้ และแนะนำให้ยืนยันระดับ MDA ก่อนทำวัคซีนเพื่อจำกัดรอยโรคที่ bursa","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26292544","locator":"Abstract; 59(1):114-21","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In order to limit bursal lesions after vaccination it is recommended to confirm the presence of MDA before vaccinating with the V877 vaccine."}}]},"avian-medicine--avian-vaccine-prog--ทำไมโปรแกรมลูกไก่จึงใช้วัคซีนเชื้อเป็นเป็นหลัก":{"claims":[{"id":"avian-medicine--avian-vaccine-prog--ทำไมโปรแกรมลูกไก่จึงใช้วัคซีนเชื้อเป็นเป็นหลัก--v1","statement":"วัคซีนเชื้อเป็นสามารถให้แก่สัตว์ปีกได้หลายเส้นทางในรูปแบบหมู่ และผลิตโดยเก็บ allantoic หรือ amniotic fluid จากไข่ฟักที่ฉีดเชื้อ ซึ่งเป็นเหตุผลด้านต้นทุนและวิธีให้ที่ทำให้เหมาะกับลูกไก่จำนวนมาก","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Summary, Requirements for vaccines, p. 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Live vaccines may be administered to poultry by various routes. They are usually produced by harvesting the infective allantoic/amniotic fluids from inoculated embryonated chickens' eggs."}},{"id":"avian-medicine--avian-vaccine-prog--ทำไมโปรแกรมลูกไก่จึงใช้วัคซีนเชื้อเป็นเป็นหลัก--v2","statement":"วัคซีนเชื้อเป็นชนิด intermediate plus ก่อรอยโรคที่ bursa ได้จริงตามที่คาดหมายจากวัคซีนชนิดนี้ ซึ่งยืนยันข้อเสียเรื่องความเสี่ยงต่อ reaction ที่สรุประบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26292544","locator":"Abstract; 59(1):114-21","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The vaccine virus caused lesions, as could be expected for an intermediate plus vaccine, but the scores were not much higher than the maximal scores allowed for mild IBD vaccines."}},{"id":"avian-medicine--avian-vaccine-prog--ทำไมโปรแกรมลูกไก่จึงใช้วัคซีนเชื้อเป็นเป็นหลัก--v3","statement":"สำหรับวัคซีน mycoplasma เชื้อเป็น สายพันธุ์วัคซีนต้องเข้าตั้งรกรากที่ทางเดินหายใจส่วนต้นได้ดี และการตอบสนองของแอนติบอดีที่สูงไม่จำเป็นต้องสัมพันธ์กับความคุ้มโรค ซึ่งสนับสนุนหลักที่สรุประบุว่าการป้องกันโรคขึ้นกับภูมิที่เยื่อเมือกมากกว่าระดับ Ab ในเลือด","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section C.1.1.1 Live vaccine, p. 14","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The vaccine strain should be immunogenic, must readily colonise the upper respiratory tract, and cause minimal damage to the respiratory system. A strong antibody response does not necessarily correlate with immunity."}}]},"avian-medicine--avian-vaccine-prog--การอ่านกราฟระดับภูมิเปรียบเทียบสองฟาร์ม":{"claims":[{"id":"avian-medicine--avian-vaccine-prog--การอ่านกราฟระดับภูมิเปรียบเทียบสองฟาร์ม--v1","statement":"วัคซีน IBD ชนิด intermediate plus ถูกออกแบบมาใช้ในไก่ที่มี maternal antibody titre สูงและเผชิญแรงกดดันการติดเชื้อสูง โดยสามารถทะลุผ่าน titre ที่สูงกว่า 1100 จากการวัดด้วย IBD ELISA ได้ ซึ่งเป็นบริบทเดียวกับโจทย์กราฟที่สรุปยกมา","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26292544","locator":"Abstract; 59(1):114-21","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Intermediate plus vaccines are used in chickens with high maternal antibody titers which face high infection pressure... can break through maternal antibody titers of higher than 1100."}}]},"avian-medicine--avian-vaccine-prog--mda-กับช่วงเวลาที่วัคซีนได้ผล":{"claims":[{"id":"avian-medicine--avian-vaccine-prog--mda-กับช่วงเวลาที่วัคซีนได้ผล--v1","statement":"อายุของไก่และระดับ MDA ที่ยังเหลืออยู่มีอิทธิพลต่อจังหวะการเริ่มต้นของการตอบสนองทางแอนติบอดีและ T-cell ที่จำเพาะต่อ IBDV ซึ่งสนับสนุนหลักที่สรุประบุว่าช่วงที่ MDA ยังสูงจะรบกวนการตอบสนองต่อวัคซีน และช่วงที่ MDA หมดแล้วไก่จะตอบสนองได้ชัดเจน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-31901750","locator":"Abstract; 220:109993","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the age and residual MDA levels had a genotype-dependent influence on the onset of the anti-IBDV specific humoral and T-cell mediated immune responses."}},{"id":"avian-medicine--avian-vaccine-prog--mda-กับช่วงเวลาที่วัคซีนได้ผล--v2","statement":"ภูมิคุ้มกันที่ได้รับจากแม่คงอยู่ราว 2 ถึง 3 สัปดาห์แรกและรบกวนการเพิ่มจำนวนของไวรัสวัคซีน จึงควรทำวัคซีนหลังจากแอนติบอดีที่ได้รับมาลดลง ซึ่งตรงกับกรอบเวลาช่วงต้นอายุ 1 ถึง 14 วันที่สรุประบุว่า MDA รบกวนวัคซีน","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2023","locator":"Section C.1 Background, p. 5","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"As passive immunity (for 2-3 weeks) may interfere with vaccine virus multiplication, such progeny should be vaccinated only after the decline of passively acquired antibody."}}]}}};
