export const CORRECTIONS = {"avian-medicine--avian-lt--recombinant-vaccine-virus-vector-vaccine":[{"severity":"narrows","lectureSays":"สไลด์เขียนใต้หัวข้อ \"Turkey herpesvirus (HVT-ILT)\" รวบเป็นบรรทัดเดียวว่า \"บรรจุ GaHV-1 glycoprotein I, D and B protein\" โดยไม่ได้แยกว่าเป็นคนละผลิตภัณฑ์ และวางขนานกับหัวข้อ Fowlpox virus (FPV-ILT) ซึ่งเป็นผลิตภัณฑ์เดียว จึงชวนให้เข้าใจว่า HVT-ILT คือวัคซีนตัวเดียวที่บรรจุ glycoprotein ครบทั้งสามชนิด (สไลด์ไม่ได้เขียนคำว่าผลิตภัณฑ์เดียวออกมาตรงตัว)","evidenceSays":"review ระบุว่ามี \"two HVT vector vaccines, one containing ILTV glycoproteins I and D, and another containing ILTV glycoprotein B\" ส่วนข้อมูล FPV-ILT ในสไลด์ (gB และ UL32) ตรงกับ review ที่เขียนว่า \"FPV vector vaccine expressing glycoprotein B and UL32 genes of ILTV\" รายชื่อ glycoprotein ในสไลด์จึงถูกต้องเมื่อพูดถึงกลุ่ม HVT-vectored ILT vaccine โดยรวม แต่ในตลาดจริงเป็นคนละผลิตภัณฑ์สองตัว ตัวหนึ่งบรรจุ gI กับ gD อีกตัวบรรจุ gB ไม่มีตัวใดบรรจุครบทั้งสาม (PMID 32315579)","examAdvice":"ตอบตามสไลด์ คือ HVT-ILT บรรจุ gI, gD, gB และ FPV-ILT บรรจุ gB กับ UL32 ให้จำเพิ่มไว้ว่าในตลาดจริง HVT vector เป็นสองผลิตภัณฑ์แยกกัน (กลุ่ม gI+gD และกลุ่ม gB) ซึ่งจะมีผลตอนต้องเลือกวัคซีนหรืออ่านฉลากผลิตภัณฑ์จริง ไม่ใช่ตอนสอบ","sourceRef":"PMID 32315579 (doi 10.1080/01652176.2020.1759845)"}],"avian-medicine--avian-lt--การวินิจฉัย-diagnosis":[{"severity":"contradicts","lectureSays":"สไลด์ระบุใต้หัวข้อการวินิจฉัยจากรอยโรคว่า \"Histopathology: Eosinophilic cytoplasmic inclusion body in epithelial cell\" คือวาง inclusion body ไว้ใน cytoplasm","evidenceSays":"WOAH ระบุว่า \"Intranuclear inclusions may be seen in the epithelial cells of the trachea after staining with haematoxylin and eosin\" และ \"Inclusion bodies are the classical Cowdry type A inclusions of herpesviruses, but they may be present for only 3-5 days after infection\" คือ inclusion body ของ ILT อยู่ในนิวเคลียส เป็น Cowdry type A ตามแบบฉบับของ herpesvirus และพบได้เพียงประมาณ 3-5 วันแรกหลังติดเชื้อเท่านั้น จุดนี้สำคัญเพราะโรคที่สไลด์เองให้วินิจฉัยแยกคือ avian poxvirus ซึ่งเป็นเชื้อที่ให้ inclusion body ใน cytoplasm (Bollinger body) ตำแหน่ง nucleus กับ cytoplasm จึงเป็นตัวแยกสองโรคนี้ (WOAH Terrestrial Manual 2021, Chapter 3.3.3, Section B.1.4)","examAdvice":"ถ้าเป็นข้อสอบตัวเลือกที่ลอกมาจากสไลด์ ให้ตอบตามที่อาจารย์สอน แต่ถ้าเป็นข้อเขียนที่ต้องอธิบาย ให้เขียนคำว่า eosinophilic inclusion body ใน epithelial cell ของหลอดลม แล้วเน้นที่เนื้อหาอื่นแทนการระบุตำแหน่ง และให้จำหลักที่ถูกไว้ใช้ตอนแยกโรค คือ herpesvirus (ILT) เป็น intranuclear Cowdry type A ส่วน poxvirus (fowlpox) เป็น intracytoplasmic Bollinger body อีกจุดที่ควรจำคือ inclusion body อยู่ให้เห็นแค่ช่วงต้นของการติดเชื้อ ถ้าเก็บตัวอย่างช้าจะหาไม่เจอ ไม่ได้แปลว่าไม่ใช่ ILT","sourceRef":"WOAH Terrestrial Manual 2021, Chapter 3.3.3 Avian infectious laryngotracheitis, Section B.1.4 Histopathology"},{"severity":"contradicts","lectureSays":"สไลด์ระบุว่า \"Histopathology: Eosinophilic cytoplasmic inclusion body in epithelial cell\" คำว่า eosinophilic ถูก แต่ตำแหน่งที่ระบุคือ cytoplasm","evidenceSays":"review ยืนยันตรงกับ WOAH ว่า \"Intranuclear basophilic or eosinophilic inclusion bodies surrounded by a halo are usually seen during initial stages of infection (1-5 days) and disappear later due to necrosis and denudation of epithelial cells\" คือ inclusion body อยู่ในนิวเคลียส ติดสีได้ทั้ง basophilic และ eosinophilic มี halo ล้อมรอบ และพบในช่วง 1-5 วันแรกแล้วหายไปเมื่อเยื่อบุตายและหลุดลอก ในคำบรรยายภาพ histopath ของ review เองก็เขียนว่า \"intranuclear eosinophilic inclusion bodies\" ดังนั้นคำว่า eosinophilic ในสไลด์ใช้ได้ แต่ต้องเป็น intranuclear ไม่ใช่ cytoplasmic (PMID 32315579)","examAdvice":"ตอบตามสไลด์ในห้องสอบของอาจารย์ แล้วจำคำเต็มที่ถูกต้องไว้ว่า intranuclear eosinophilic inclusion body with halo in tracheal epithelial cell พร้อมกับข้อมูลที่ใช้ได้จริงคือ inclusion body จะเห็นเฉพาะช่วง 1-5 วันแรกของการติดเชื้อ เวลาส่งชิ้นเนื้อจึงต้องเลือกไก่ที่เพิ่งป่วย ไม่ใช่ไก่ที่ป่วยมานาน","sourceRef":"PMID 32315579 (doi 10.1080/01652176.2020.1759845)"}],"avian-medicine--avian-lt--ข้อควรระวังในการใช้วัคซีนเชื้อเป็น":[{"severity":"narrows","lectureSays":"สไลด์ระบุว่า \"ไม่ควรให้วัคซีนเชื้อเป็น ILT ในช่วงเดียวกับที่ให้วัคซีนป้องกันโรคระบบหายใจอื่นๆ ควรให้ห่างกันประมาณ 7 วัน\"","evidenceSays":"review ระบุว่า \"no interference has been reported between ILT and other vaccines if the vaccine interval is more than 2 weeks\" คือช่วงห่างที่มีรายงานว่าไม่เกิดการรบกวนกันคือมากกว่า 2 สัปดาห์ ไม่ใช่ 7 วัน review ไม่ได้พิสูจน์ว่าเว้น 7 วันแล้วจะเกิด interference แน่ๆ แต่ 7 วันคือช่วงที่ยังไม่มีข้อมูลรองรับว่าปลอดภัย หลักการวัคซีนของสไลด์จึงถูก เพียงแต่ตัวเลขที่ให้ไว้สั้นกว่าที่หลักฐานรองรับ (PMID 32315579)","examAdvice":"ตอบ 7 วัน ตามสไลด์ในข้อสอบของอาจารย์ ส่วนเวลาวางโปรแกรมวัคซีนจริงในฟาร์ม ให้เว้นเกิน 2 สัปดาห์จะปลอดภัยกว่า และจำหลักไว้ว่าเหตุผลของการเว้นระยะคือกันไม่ให้วัคซีนตัวอื่นที่ลงระบบหายใจไปรบกวนการติดเชื้อของวัคซีน ILT ที่หลอดลม","sourceRef":"PMID 32315579 (doi 10.1080/01652176.2020.1759845)"}],"avian-medicine--avian-lt--อาการ-clinical-signs":[{"severity":"contradicts","lectureSays":"สไลด์ระบุว่า \"อัตราการป่วยสูง 90-100%\" และ \"อัตราการตายปานกลาง 5-20%\"","evidenceSays":"ตัวเลข morbidity ตรงกัน แต่ mortality ไม่ตรง review เขียนว่า severe epizootic form มี \"high morbidity (90-100%) or variable mortality ranging from 5 to 70% (average of 10-20%)\" คือค่าเฉลี่ย 10-20% ตรงกับสไลด์ แต่ช่วงที่รายงานจริงกว้างถึง 70% และในพื้นที่เลี้ยงไก่หนาแน่นเคยมีรายงาน overall mortality สูงถึง 70% (PMID 32315579) สอดคล้องกับ WOAH ที่ระบุว่ารูปแบบ peracute อัตราการตายอาจเกิน 50% ส่วนรูปแบบ subacute อยู่ที่ 10-30% (WOAH Terrestrial Manual 2021, Chapter 3.3.3)","examAdvice":"ตอบ 5-20% ตามสไลด์ในข้อสอบของอาจารย์ แต่ให้จำ 5-70% (เฉลี่ย 10-20%) ไว้ใช้ตอนเจอเคสจริง ถ้าฟาร์มตาย 40-50% อย่าเพิ่งตัด ILT ทิ้งเพียงเพราะตัวเลขเกิน 20%","sourceRef":"PMID 32315579 (doi 10.1080/01652176.2020.1759845)"}],"avian-medicine--avian-lt--เชื้อสาเหตุ-etiology":[{"severity":"contradicts","lectureSays":"สไลด์ไล่อนุกรมวิธานของ ILTV ว่า \"Genus Iltovirus\" \"Subfamily Alphaherpesvirinae\" \"Family Herpesviridae\" โดยระบุ family เป็น Herpesviridae และเรียกเชื้อว่า Gallid herpesvirus type 1 (GaHV-1)","evidenceSays":"ICTV ให้สัตยาบันการเปลี่ยนชื่อในปี 2023 family ที่ ILTV สังกัดปัจจุบันชื่อ Orthoherpesviridae ซึ่งอยู่ใน order Herpesvirales ร่วมกับ Alloherpesviridae (ปลาและสัตว์สะเทินน้ำสะเทินบก) และ Malacoherpesviridae (สัตว์ไม่มีกระดูกสันหลัง) family นี้มี 3 subfamilies คือ Alphaherpesvirinae, Betaherpesvirinae และ Gammaherpesvirinae genus Iltovirus อยู่ใน Alphaherpesvirinae ตามที่สไลด์เขียนถูกต้อง แต่ชื่อสปีชีส์ทางการปัจจุบันคือ Iltovirus gallidalpha1 ไม่ใช่ Gallid herpesvirus 1 ประเด็นนี้เป็นการเปลี่ยนชื่อทางอนุกรมวิธาน ไม่ใช่ชีววิทยาของไวรัสเปลี่ยน (ICTV Report: Orthoherpesviridae, ictv.global, ให้สัตยาบัน 2023)","examAdvice":"ในข้อสอบของอาจารย์ให้ตอบตามสไลด์ คือ Family Herpesviridae, Subfamily Alphaherpesvirinae, Genus Iltovirus, GaHV-1 ซึ่งเป็นชื่อที่ตำรา Diseases of Poultry และสไลด์ใช้ ให้จำเพิ่มไว้เฉยๆ ว่าถ้าอ่าน paper หรือเขียนงานวิชาการหลังปี 2023 จะเจอชื่อ Orthoherpesviridae และ Iltovirus gallidalpha1 อย่าไปแก้คำตอบในห้องสอบ","sourceRef":"ICTV Report: Orthoherpesviridae (ictv.global, ratified 2023)"}],"avian-medicine--avian-lt--เซลล์เป้าหมาย-การติดต่อ-และระยะฟักตัว":[{"severity":"contradicts","lectureSays":"สไลด์ระบุว่า \"ระยะฟักตัวของโรค: 3-7 วัน\"","evidenceSays":"review รวบรวมไว้ว่า \"The incubation period of ILTV varies between 6 and 14 days\" คือ 6 ถึง 14 วัน เพดานบนสูงกว่าสไลด์เท่าตัว และขอบล่าง 3 วันของสไลด์ต่ำกว่าที่รายงานไว้ ตัวเลขระยะฟักตัวสั้นราว 2-5 วันเป็นค่าที่ได้จากการให้เชื้อทดลองเข้าหลอดลมโดยตรงหรือทางอากาศ ไม่ใช่การติดเชื้อตามธรรมชาติในฟาร์ม จึงน่าจะเป็นที่มาของช่วงที่สั้นกว่า (Infectious laryngotracheitis: Etiology, epidemiology, pathobiology, and advances in diagnosis and control, PMID 32315579)","examAdvice":"ข้อสอบของอาจารย์ให้ตอบ 3-7 วัน ตามสไลด์ ส่วนเวลาไปคิดงานจริงหรือเจอโจทย์ระบาดวิทยาที่ต้องไล่ timeline ว่าเชื้อเข้าฝูงวันไหน ให้เผื่อระยะฟักตัวได้ถึง 14 วัน ไม่งั้นจะตัดช่วงเวลาที่เชื้อเข้าจริงทิ้งไป","sourceRef":"PMID 32315579 (doi 10.1080/01652176.2020.1759845)"}],"avian-medicine--avian-mpv--subtypes-ของ-ampv":[{"severity":"contradicts","lectureSays":"สไลด์จำกัดทั้งพื้นที่และ host ของ subtype C ไว้ว่า \"subtype C พบเฉพาะในสหรัฐอเมริกาและฝรั่งเศส และพบเฉพาะในไก่งวง\"","evidenceSays":"บทความทบทวนระบุว่า AMPV-C ถูกตรวจพบนอกไก่งวงและนอกสองประเทศนั้นชัดเจน \"Virus isolates or RT-PCR positive samples obtained from a Muscovy duck in France in 1999, in pheasants from a live bird market in Korea in 2005, and in Muscovy ducks and chickens from China\" และยังแบ่ง AMPV-C ออกเป็น 2 lineage คือ American turkey lineage กับ Eurasian duck lineage ที่ติดเชื้อในเป็ดเป็นหลัก โดยมีรายงานการระบาดที่ทำให้ไก่ในจีนแสดงอาการทางระบบหายใจรุนแรงเมื่อปี 2012 (Zoonotic Origins of Human Metapneumovirus: A Journey from Birds to Humans, PMID 35458407, doi 10.3390/v14040677) สอดคล้องกับ WOAH ที่ระบุว่าไวรัส subgroup C สัมพันธ์กับอาการทางระบบหายใจและไข่ลดในเป็ดที่ฝรั่งเศส (Toquin et al., 2006)","examAdvice":"ข้อสอบของอาจารย์ท่านนี้ให้ตอบตามสไลด์ คือ subtype C พบที่สหรัฐฯ กับฝรั่งเศส และผูกกับไก่งวง แต่ให้จำความจริงไว้ด้วยว่า host range ของ subtype C กว้างกว่านั้นมาก โดยเฉพาะเป็ด Muscovy รวมถึงไก่ฟ้าที่เกาหลีและเป็ดกับไก่ที่จีน ถ้าเจอโจทย์เชิงระบาดวิทยาหรือกรณีศึกษาที่ถามว่า subtype C พบในเป็ดได้หรือไม่ คำตอบทางวิชาการคือได้","sourceRef":"PMID 35458407 (doi 10.3390/v14040677)"}],"avian-medicine--avian-mpv--การเก็บตัวอย่าง-จากสัตว์เป็นและจากการผ่าซาก":[{"severity":"narrows","lectureSays":"สไลด์ตั้งเกณฑ์เลือกตัวสัตว์ไว้ว่า \"Collect sample at early stage of infection or from severely sick animal\" คือเสนอสัตว์ที่ป่วยหนักเป็นทางเลือกที่ดีพอกันกับสัตว์ในระยะต้นของการติดเชื้อ","evidenceSays":"WOAH ระบุว่าตัวที่ควรเก็บคือทางเดินหายใจส่วนต้นของนกเป็นในระยะ acute ของโรค \"Ideally, the upper respiratory tract of live birds in the acute phase of the disease should be sampled\" และเตือนต่อทันทีว่า \"Isolation of virus is rarely successful from birds showing severe chronic signs as the extreme clinical signs are usually due to secondary adventitious agents\" พร้อมย้ำว่าข้อนี้ใช้กับ SHS ในไก่โดยตรง เพราะอาการหัวบวมที่เห็นเด่นชัดเกิดจากแบคทีเรียแทรกซ้อนเช่น Escherichia coli ไม่ใช่จากตัวไวรัสที่ยังอยู่ จุดที่ต่างจากสไลด์คือ WOAH แยกชัดระหว่าง severe acute กับ severe chronic แต่สไลด์เขียนเพียง severely sick animal โดยไม่มีเงื่อนไขกำกับ ทำให้อ่านได้ว่าสัตว์ที่ป่วยหนักทุกตัวใช้ได้พอกันกับสัตว์ระยะต้น ซึ่งเป็นกับดักที่ WOAH เตือนไว้ตรงตัว (Manual of Diagnostic Tests and Vaccines for Terrestrial Animals, Chapter 3.3.11, WOAH 2022, Section B.1.1 Collection and selection of diagnostic specimens)","examAdvice":"ตอบตามสไลด์ได้ คือเก็บที่ระยะต้นของการติดเชื้อหรือจากสัตว์ที่ป่วยชัดเจน แต่ให้เข้าใจเงื่อนไขว่า สัตว์ป่วยหนักที่ใช้ได้คือตัวที่อยู่ในระยะ acute ไม่ใช่ตัวที่ป่วยรุนแรงเรื้อรัง ถ้าเจอโจทย์ถามว่าทำไมเก็บจากไก่ที่หัวบวมมากแล้วแยกเชื้อไม่ขึ้น คำตอบคือรอยโรครุนแรงนั้นเกิดจาก secondary bacteria ขณะที่ไวรัสหมดไปจาก sinus และ turbinate แล้ว","sourceRef":"WOAH Terrestrial Manual 2022, Chapter 3.3.11 Turkey rhinotracheitis (avian metapneumovirus infections)"}],"avian-medicine--avian-mpv--การเก็บตัวอย่าง-ชนิดตัวอย่างและจังหวะเวลา":[{"severity":"narrows","lectureSays":"สไลด์ให้กรอบเวลาไว้แคบว่า \"ต้องเก็บทันทีในช่วงที่ไก่ติดเชื้อ หรือมีอาการ เพราะไวรัสจะอยู่บริเวณ sinus, turbinate แค่ 6-7 วัน\"","evidenceSays":"WOAH เห็นตรงกับสไลด์ว่าต้องเก็บเร็ว โดยระบุว่า nasal exudate, choanal cleft swab และ turbinate ที่เก็บ 2 ถึง 7 วันหลังสัมผัสเชื้อคือตัวอย่างที่ดีที่สุด แต่กรอบการตรวจพบยาวกว่า 6-7 วัน คือ \"Infectious virus can only usually be isolated for approximately ten days after infection\" และ \"viral RNA persists for 9 days in the trachea and up to 14 days in the nasal turbinates (Velayudhan et al., 2005)\" อีกทั้งระบุว่า aMPV ยังตรวจพบได้จากตัวอย่างที่เก็บ 7 ถึง 10 วันหลังสัมผัสเชื้อ เพียงแต่ปริมาณไวรัสน้อยลงมากจนโอกาสตรวจเจอลดลง (Manual of Diagnostic Tests and Vaccines for Terrestrial Animals, Chapter 3.3.11, WOAH 2022, Summary และ Section B.1.3 Molecular identification)","examAdvice":"ตอบตามสไลด์คือ 6-7 วัน เพราะแก่นที่อาจารย์ต้องการคือ ต้องเก็บให้เร็วในช่วงที่ยังแสดงอาการ แต่ให้แยกให้ออกในหัวว่า 6-7 วันคือช่วงที่เก็บแล้วได้ผลดีที่สุด ไม่ใช่เส้นตายของการตรวจพบ เพราะการแยกเชื้อยังทำได้ราว 10 วัน และ RT-PCR ยังจับ viral RNA ได้ถึง 14 วันใน nasal turbinate ประเด็นนี้ใช้ตอบเวลาโจทย์ถามว่าทำไมเลือกส่ง RT-PCR แทน virus isolation ในเคสที่มาช้า","sourceRef":"WOAH Terrestrial Manual 2022, Chapter 3.3.11 Turkey rhinotracheitis (avian metapneumovirus infections)"}],"avian-medicine--avian-mpv--โรคหัวบวมคืออะไร-ภาพรวม":[{"severity":"narrows","lectureSays":"สไลด์วางเพดานอัตราการตายไว้ที่ 50% โดยเขียนว่า \"อัตราการป่วยอาจสูง 100% อัตราการตายอาจถึง 50% ในลูกไก่งวง\" คือให้ 50% เป็นค่าสูงสุดของ mortality ในลูกไก่งวง","evidenceSays":"WOAH ให้ตัวเลข morbidity ตรงกับสไลด์ แต่ช่วง mortality กว้างกว่า คือ \"Morbidity can be as high as 100%, with mortality ranging from 0.5% in adult turkeys to 80% in young poults (Van De Zande et al., 1999)\" นั่นคือต่ำเพียง 0.5% ในไก่งวงโตเต็มวัย แต่สูงได้ถึง 80% ในลูกไก่งวง ซึ่งเกินเพดาน 50% ที่สไลด์ระบุ (Manual of Diagnostic Tests and Vaccines for Terrestrial Animals, Chapter 3.3.11 Turkey rhinotracheitis (avian metapneumovirus infections), WOAH 2022, Section A. Introduction)","examAdvice":"ในข้อสอบของอาจารย์ท่านนี้ให้ตอบตามสไลด์ คือ morbidity ถึง 100% และ mortality ถึง 50% ในลูกไก่งวง แต่จำไว้ว่าตัวเลขนี้ไม่ได้มีค่าเดียวในวรรณกรรม Merck ให้ช่วง 1 ถึง 50% ส่วน WOAH ให้ 0.5% ในตัวโตถึง 80% ในลูกไก่งวง สิ่งที่ต้องตอบให้ได้เสมอไม่ว่าเจอตัวเลขไหนคือ mortality ขึ้นกับอายุและการมี secondary infection ส่วน morbidity สูงเสมอ","sourceRef":"WOAH Terrestrial Manual 2022, Chapter 3.3.11 Turkey rhinotracheitis (avian metapneumovirus infections)"}],"avian-medicine--avian-nd--การเก็บรักษาตัวอย่างตามวิธีตรวจ-virus-culture-vs-molecular":[{"severity":"narrows","lectureSays":"สไลด์ให้เพดานเวลาที่ตู้เย็นสั้นกว่าคู่มือ โดยสำหรับ virus culture เขียนว่า \"Put swab or organ in Viral Transport Media (VTM)\" แล้ว \"Keep sample in refrigerator (4°C) for 1-2 day\" และ \"Not recommend to keep in the freezer\"","evidenceSays":"คู่มือ WOAH บทนิวคาสเซิล หัวข้อตัวอย่างสำหรับ virus isolation เขียนกำกับไว้ในย่อหน้าเดียวกันว่าให้ process ตัวอย่างให้เร็วที่สุด แล้วจึงต่อด้วย \"When immediate processing is impracticable, samples may be stored at 4°C for up to 4 days.\" ตัวเลข 4 วันจึงเป็นเพดานสำหรับกรณีส่งตรวจไม่ทัน ไม่ใช่ระยะเวลาที่แนะนำให้ถือไว้เป็นปกติ ดังนั้น 1-2 วันของสไลด์ไม่ใช่ตัวเลขผิด แต่เป็นเกณฑ์ปฏิบัติที่รัดกุมกว่าคู่มือ จุดที่ต่างกันจริงคือเพดานสูงสุดที่ 4°C เท่านั้น ส่วนประเด็นห้ามแช่แข็งของสไลด์ไม่ได้ถูกค้าน เพราะคู่มือระบุต่อว่าถ้าจะเก็บยาวต้องเก็บที่ -80°C และขนส่งบน dry ice (ไม่เกิน -50°C) พร้อมเลี่ยง freeze-thaw ซ้ำ ซึ่งไม่ใช่ช่องแช่แข็งธรรมดา (Chapter 3.3.14 Newcastle disease, Manual of Diagnostic Tests and Vaccines for Terrestrial Animals, WOAH Terrestrial Manual 2021, Section B.1.1)","examAdvice":"ข้อสอบวิชานี้ตอบ 1-2 วัน ตามสไลด์ และตอบจุดต่างที่สไลด์เน้นไว้ให้ครบ (virus culture ห้ามแช่แข็ง, molecular แช่แข็งได้ 3-5 วัน, อวัยวะสำหรับ molecular ไม่ต้องแช่ VTM) ส่วนตัวเลขที่ควรจำไว้ใช้จริงคือ 4°C ถือได้ถึง 4 วัน ตามคู่มือ WOAH เวลาเจอเคสที่ส่งตัวอย่างล่าช้าเกิน 2 วัน ตัวอย่างยังมีค่าอยู่ ไม่ต้องทิ้ง และการเก็บยาวต้องเป็น -80°C ไม่ใช่ช่องแช่แข็งตู้เย็นทั่วไป","sourceRef":"WOAH Terrestrial Manual 2021, Chapter 3.3.14 Newcastle disease, Section B.1.1 Samples for virus isolation (p.4)"}],"avian-medicine--avian-nd--เชื้อก่อโรค-ชื่อเรียก-การจัดจำแนก-และโครงสร้างไวรัส":[{"severity":"narrows","lectureSays":"สไลด์บรรยายรูปร่างและขนาดไวรัสไว้ค่าเดียวว่า \"Enveloped, spherical. Diameter of about 150 nm\" โดยใช้รูปประกอบจาก viralzone.expasy.org","evidenceSays":"บทความทบทวน NDV ระบุในหัวข้อ Newcastle disease virus ว่า \"NDV is a pleomorphic enveloped virus around 200-300 nm in diameter\" คือรูปร่างไม่คงที่ ไม่ใช่ทรงกลมอย่างเดียว (Newcastle disease virus: current status and our understanding, PMID 24589707, doi 10.1016/j.virusres.2014.02.016) ประเด็นที่ขัดกันจริงและตอบได้ชัดคือคำว่ารูปร่าง เพราะสไลด์ตัดเหลือ spherical คำเดียว ส่วนตัวเลขขนาดนั้นให้เข้าใจว่าทั้ง 150 nm และ 200-300 nm ต่างอยู่ในช่วงที่วรรณกรรมรายงานสำหรับอนุภาค paramyxovirus ที่ pleomorphic ซึ่งวัดได้ตั้งแต่ราว 100 ถึง 500 nm ไม่ใช่ว่าค่าใดค่าหนึ่งผิด แต่การให้ค่าเดียวโดยไม่บอกว่าแปรผันคือสิ่งที่ทำให้เข้าใจคลาดเคลื่อน","examAdvice":"ในข้อสอบของอาจารย์ท่านนี้ให้ตอบตามสไลด์ คือ enveloped, spherical, ประมาณ 150 nm แต่ถ้าโจทย์เปิดให้บรรยาย morphology เอง ให้ใส่คำว่า pleomorphic ลงไปด้วย และจำไว้ว่าค่าขนาดที่รายงานในวรรณกรรมกว้างกว่าค่าเดี่ยว 150 nm มาก โครงสร้างส่วนที่ห้ามพลาดและไม่มีข้อขัดแย้งคือ negative sense ssRNA มีเปลือกหุ้ม และมี HN กับ F เป็น surface glycoprotein","sourceRef":"PMID 24589707 (doi 10.1016/j.virusres.2014.02.016)"}],"avian-medicine--avian-nd--เซลล์และอวัยวะเป้าหมาย-การติดต่อ-และระยะฟักตัว":[{"severity":"narrows","lectureSays":"สไลด์พูดแบบปิดประตูว่า \"No evident of vertical transmission because NDV cause embryonic dead & dead-in-shell\" คือไม่มีหลักฐานการติดต่อแนวดิ่งเลย เพราะไวรัสทำให้ตัวอ่อนตายและตายคาเปลือกไปก่อน","evidenceSays":"WOAH Technical Disease Card ชื่อ Newcastle Disease (Avian Paramyxovirus Serotype 1) ท้ายเล่มระบุ Last updated 2019 เขียนโดยได้รับความช่วยเหลือจาก USGS National Wildlife Health Center และต้นเล่มประกาศว่าใช้กับการรายงานโรคในสัตว์ป่าที่ไม่ใช่สัตว์ปีกเลี้ยง แต่หัวข้อ Transmission เขียนไว้เป็นข้อความไวรัสวิทยาทั่วไปว่า \"Vertical transmission has been documented for lentogenic strains.\" ซึ่งวรรณกรรมสัตว์ปีกบันทึกตรงกันว่ามีลูกไก่ติดเชื้อฟักออกจากไข่ที่มีไวรัส เหตุผลของสไลด์จึงใช้ได้กับสายพันธุ์รุนแรง (velogenic และ mesogenic) ที่ทำให้ embryo ตายและ dead-in-shell แต่ไปไม่ถึง lentogenic ทั้งนี้เป็นเหตุการณ์ที่พบไม่บ่อยและยังเป็นประเด็นถกเถียง ไม่ใช่เส้นทางติดต่อหลัก","examAdvice":"ตอบตามสไลด์ว่าไม่มี vertical transmission เพราะ embryo ตายคาเปลือก นั่นคือคำตอบที่อาจารย์ตรวจ ส่วนข้อยกเว้น lentogenic strain เก็บไว้เติมเฉพาะข้อสอบอัตนัยที่เปิดให้ขยายความ หรือไว้ใช้เวลาทำงานจริง อย่าเอาไปตอบสวนในข้อปรนัย","sourceRef":"WOAH Technical Disease Card, Newcastle Disease (Avian Paramyxovirus Serotype 1), last updated 2019, หัวข้อ Epidemiology, Transmission"}],"avian-medicine--avian-pox--recombinant-vaccine":[{"severity":"contradicts","lectureSays":"สไลด์ยกตัวอย่างยีนที่ตัดมาใส่ใน poxvirus vector ว่า \"F gene ของ NDV, HN gene ของ ILT\" แล้วย้ำอีกครั้งว่าไก่จะสร้างภูมิคุ้มกัน \"ทั้งต่อ Poxvirus และ F gene ของ NDV หรือ HN gene ของ ILT\" คือระบุชัดว่า HN เป็นยีนของ ILT","evidenceSays":"F (fusion) และ HN (hemagglutinin-neuraminidase) เป็นยีนของ Newcastle disease virus ทั้งคู่ ส่วนยีนของ infectious laryngotracheitis virus ที่ใส่ใน recombinant fowlpox vaccine คือ glycoprotein B (gB) งานที่สร้าง rFPV ตัวนี้เขียนไว้ตรงว่า \"A recombinant fowlpox virus (rFPV) coexpressing the Newcastle disease virus (NDV) fusion and hemagglutinin-neuraminidase genes and infectious laryngothracheitis virus (ILTV) glycoprotein B gene was constructed.\" เหตุผลเชิงชีววิทยาคือ ILTV เป็น herpesvirus (Gallid alphaherpesvirus 1) ซึ่งไม่มียีน HN แบบ paramyxovirus (Protection of chickens from Newcastle disease and infectious laryngotracheitis with a recombinant fowlpox virus co-expressing the F, HN genes of Newcastle disease virus and gB gene of infectious laryngotracheitis virus, PMID 18459306, doi 10.1637/7998-041807-Reg)","examAdvice":"ในห้องสอบให้ตอบตามที่อาจารย์สอนไว้ก่อน เพราะข้อสอบตรวจตามสไลด์ แต่จำของจริงไว้แน่น ๆ ว่า F และ HN คือยีนของ NDV ส่วน ILTV ใช้ gB ถ้ามีจังหวะถามอาจารย์นอกห้องสอบ จุดนี้ควรถามให้เคลียร์ เพราะน่าจะเป็นคำพิมพ์ตกบนสไลด์มากกว่าความตั้งใจ","sourceRef":"PMID 18459306 (doi 10.1637/7998-041807-Reg)"}],"avian-medicine--avian-pox--การตรวจสอบผลการให้วัคซีนที่-wing-web":[{"severity":"narrows","lectureSays":"สไลด์เปิดหน้าต่างการอ่านผล take ตั้งแต่วันที่ 5 โดยระบุว่า \"หากวัคซีนได้ผล จะพบ ตุ่มนูนแข็งบริเวณที่ให้วัคซีน 5-10 วัน หลังทำวัคซีน\" และให้ \"สุ่มตรวจไก่อย่างน้อย 50 ตัว ต่อ 1 โรงเรือน\" ถ้าไม่พบตุ่มมากกว่า 10% ให้ทำวัคซีนใหม่ทั้งโรงเรือน","evidenceSays":"คู่มือ WOAH ใช้หน้าต่าง 7-10 วัน ไม่ใช่ 5-10 วัน ในหัวข้อ serological tests เขียนว่า \"Evidence of successful immunisation with vaccine can be determined by examining a flock 7-10 days after vaccination for 'takes'. A take consists of a swelling of the skin or a scab at the site where the vaccine was applied and its presence is evidence of successful immunisation.\" และในหัวข้อ safety test ของวัคซีน (C.2.1.3) ก็ใช้หน้าต่างเดียวกันว่า \"The birds are observed for 7-10 days for evidence of 'takes'\" ขอบบนตรงกันที่ 10 วัน ต่างกันที่ขอบล่าง คือสไลด์เริ่มอ่านผลเร็วกว่าคู่มือ 2 วัน (Manual of Diagnostic Tests and Vaccines for Terrestrial Animals, Chapter 3.3.10 Fowlpox, WOAH Terrestrial Manual 2023, Section B.2 และ C.2.1.3)","examAdvice":"ข้อสอบวิชานี้ตอบ 5-10 วัน ตามสไลด์ และตอบเกณฑ์ทำวัคซีนซ้ำตามที่สไลด์เขียนไว้ ส่วนหน้างานจริงให้จำ 7-10 วัน ประเด็นที่ใช้ได้จริงคือ ถ้าไปสุ่มดู wing web ตั้งแต่วันที่ 5 แล้วยังเห็นตุ่มไม่ครบ อย่าเพิ่งสรุปว่าวัคซีนไม่ take เพราะยังไม่ถึงหน้าต่างที่ WOAH ใช้ ควรรอถึงวันที่ 7 ก่อนตัดสินใจทำวัคซีนใหม่ทั้งโรงเรือน","sourceRef":"WOAH Terrestrial Manual 2023, Chapter 3.3.10 Fowlpox, Section B.2 (p.4) และ Section C.2.1.3 (p.6)"}],"avian-medicine--avian-pox--การวินิจฉัย-diagnosis":[{"severity":"narrows","lectureSays":"สไลด์จัด RFLP ไว้ในหัวข้อการวินิจฉัยทางไวรัสวิทยา โดยเขียนสามวิธีเรียงบรรทัดเดียวกันว่า \"Molecular techniques; PCR, RFLP, DNA probes\" ซึ่งไม่ได้จัดลำดับความสำคัญ นิสิตจึงอ่านได้ว่าทั้งสามใช้ตรวจวินิจฉัยได้เท่ากัน","evidenceSays":"คู่มือ WOAH บทฝีดาษไก่ หัวข้อ Molecular methods เขียนไว้ตรงว่า \"Restriction fragment length polymorphism (RFLP) analysis has been reported for comparison of field isolates and vaccine strains of FPV (Ghildyal et al., 1989; Schnitzlein et al., 1988); however this procedure is not routinely used for detection or diagnosis.\" คือ RFLP ใช้เปรียบเทียบเชื้อภาคสนามกับเชื้อวัคซีน ประโยคนี้และ primer ที่จับ conserved region ของ major core protein P4b อยู่ใน Section B.1.3 Molecular methods หน้า 4 ส่วนวิธี molecular ที่เป็นงานประจำของแล็บสัตว์ปีกคือ PCR และ real-time PCR โดยคู่มือเขียนไว้ในย่อหน้าเปิดของ Section B.1 Detection of the agent หน้า 3 ว่า \"Molecular detection methods designed to amplify FPV DNA by polymerase chain reaction (PCR) or real-time PCR have become routine in many avian diagnostic laboratories\" (Manual of Diagnostic Tests and Vaccines for Terrestrial Animals, Chapter 3.3.10 Fowlpox, WOAH 2023)","examAdvice":"ถ้าโจทย์ถามว่า molecular techniques ของ fowlpox มีอะไรบ้าง ให้ตอบ PCR, RFLP, DNA probes ตามสไลด์ แต่ถ้าเป็นข้อเขียนที่ถามว่าจะ \"ตรวจวินิจฉัย\" ด้วยวิธีใด ให้ชู PCR และ real-time PCR เป็นหลักแล้วค่อยเสริมว่า RFLP มีบทบาทในการแยกเชื้อภาคสนามออกจากเชื้อวัคซีน จะได้ทั้งคะแนนตามสไลด์และตรงกับของจริง","sourceRef":"WOAH Terrestrial Manual 2023, Chapter 3.3.10 Fowlpox, Section B.1 Detection of the agent (p.3) และ Section B.1.3 Molecular methods (p.4)"}],"avian-medicine--avian-pox--พยาธิกำเนิด-pathogenesis-เทียบ-2-form-ตาม-dpi":[{"severity":"narrows","lectureSays":"สไลด์วางไทม์ไลน์ cutaneous form ว่า \"2 DPI: replicate in skin\", \"4 DPI found in lung\", \"5 DPI viremia\" แล้วปิดท้ายว่า \"5-10 DPI พบ Nodular lesion\" คือให้กรอบเดียวสำหรับการเกิดรอยโรคที่ผิวหนัง","evidenceSays":"งานที่ให้ตัวเลขชุดเดียวกับสไลด์ทั้งชุด (i.d. พบเชื้อที่ผิวหนังวันที่ 2 ปอดวันที่ 4 viremia วันที่ 5 และแยกเชื้อได้จากตับ ม้าม ไต สมอง แต่ไม่พบที่หัวใจ ส่วน i.t. พบที่ปอดวันที่ 2 และ viremia วันที่ 4) ระบุเรื่องรอยโรคละเอียดกว่าว่า \"Initiation of pocks at the inoculation site in i.d. infected birds was observed on days 3 to 4 p.i., generalized cutaneous pock lesions appeared from 7 to 8 days p.i.\" คือตุ่มแรกที่ตำแหน่งได้รับเชื้อขึ้นตั้งแต่วันที่ 3 ถึง 4 ส่วนตุ่มที่กระจายทั่วตัวขึ้นวันที่ 7 ถึง 8 กรอบ 5-10 DPI ของสไลด์จึงครอบคลุมรอยโรคที่กระจายแล้ว แต่ช้ากว่าตุ่มแรกที่ตำแหน่งได้รับเชื้อ (Studies on pathogenesis of fowl pox: virological study, PMID 2891281, Acta Virol 1987;31(5):417-423)","examAdvice":"ข้อสอบของอาจารย์ใช้กรอบ 5-10 DPI ให้ตอบตามนั้น และสิ่งที่ควรท่องคือคู่เทียบที่สไลด์เน้น คือ cutaneous 2/4/5 DPI เทียบกับ diphtheritic 2/4 DPI ส่วนตัวเลข 3-4 วันของตุ่มแรกที่ตำแหน่งได้รับเชื้อ กับ 7-8 วันของตุ่มที่กระจายทั่วตัว เก็บไว้ตอบเวลามีคนถามว่ารอยโรคเร็วที่สุดกี่วัน อย่าเอาไปเขียนแทนกรอบของสไลด์ในข้อปรนัย","sourceRef":"PMID 2891281"}]};
